/**
 * Localized catalog content, one entry per app id and supported language.
 * Generated by scripts/translate_content.mjs - do not hand-edit single
 * strings; re-run the script instead. Missing fields fall back to English.
 */
export type LocalizedAppText = Partial<Record<'tagline' | 'description' | 'whyItsAwesome' | 'beginnerGuide', string>>;

export const APP_DESCRIPTIONS: Record<string, Partial<Record<Exclude<Language, 'en'>, LocalizedAppText>>> = 
{
  'localsend': { fa: { tagline: "ابزار اشتراک‌گذاری فایل در شبکه محلی", description: "یک جایگزین متن‌باز و چند‌پلتفرمی برای AirDrop. فایل‌ها به صورت امن و بدون نیاز به اینترنت یا سرورهای واسط، از طریق شبکه Wi-Fi محلی منتقل می‌شوند.", whyItsAwesome: "بدون نیاز به ثبت‌نام، آپلود در فضای ابری و کار فوری بین ویندوز، اندروید، iOS، macOS و لینوکس در یک شبکه Wi-Fi.", beginnerGuide: "اپلیکیشن را روی کامپیوتر و موبایل نصب کنید. هر دو اپ را باز کنید، هر فایلی را به LocalSend بکشید و موبایل خود را از لیست برای انتقال فوری انتخاب نمایید." }, es: { tagline: "Herramienta para compartir archivos en red local", description: "Una alternativa de código abierto multiplataforma a AirDrop. Los archivos se transfieren de forma segura por la red Wi-Fi local sin servidores de terceros ni acceso a internet.", whyItsAwesome: "Cero registro de cuenta, sin subida a la nube, funciona al instante entre Windows, Android, iOS, macOS y Linux en la misma red Wi-Fi.", beginnerGuide: "Instala la app en tu computadora y teléfono. Abre ambas, arrastra cualquier archivo a LocalSend y selecciona tu teléfono en la lista para transferirlo de inmediato." }, fr: { tagline: "Utilitaire de partage de fichiers sur réseau local", description: "Une alternative open source multiplateforme à AirDrop. Les fichiers sont transférés de manière sécurisée sur le réseau Wi-Fi local sans serveur tiers ni accès internet.", whyItsAwesome: "Pas d'inscription, pas de cloud, fonctionne instantanément sur Windows, Android, iOS, macOS et Linux sur le même réseau Wi-Fi.", beginnerGuide: "Installez l'application sur votre ordinateur et votre téléphone. Ouvrez les deux, glissez n'importe quel fichier dans LocalSend, et sélectionnez votre téléphone dans la liste pour transférer immédiatement." }, de: { tagline: "Werkzeug für Dateifreigabe im lokalen Netzwerk", description: "Eine quelloffene, plattformübergreifende Alternative zu AirDrop. Dateien werden sicher über das lokale WLAN übertragen, ohne dass externe Server oder Internetzugang nötig sind.", whyItsAwesome: "Keine Anmeldung, keine Cloud-Uploads, funktioniert sofort unter Windows, Android, iOS, macOS und Linux im selben WLAN.", beginnerGuide: "Installiere die App auf deinem Computer und Telefon. Öffne beide Apps, ziehe eine Datei in LocalSend und wähle dein Telefon aus der Liste zum sofortigen Transfer." } },
  'sharex': { fa: { tagline: "ضبط صفحه‌نمایش، اسکرین‌شات و آپلودر فایل", description: "یک ابزار سبک، متن‌باز ویندوزی برای گرفتن اسکرین‌شات یا ضبط هر بخشی از صفحه‌نمایش و اشتراک‌گذاری آن با یک فشار کلید.", whyItsAwesome: "شامل استخراج متن از تصاویر با OCR، انتخابر رنگ، اسکرین‌شات اسکرول و آپلود خودکار به مقصد دلخواه.", beginnerGuide: "کلید PrintScreen را فشار دهید تا ناحیه‌ای را برای اسکرین‌شات انتخاب کنید. می‌توانید با فلش‌ها آنوتейт کنید، پسوردهای حساس را تار کنید و مستقیماً کلیپ‌بورد کپی کنید." }, es: { tagline: "Captura de pantalla, grabación y subidor de archivos", description: "Una utilidad ligera y de código abierto para Windows que te permite capturar o grabar cualquier área de tu pantalla y compartirla con una sola pulsación de tecla.", whyItsAwesome: "Incluye extracción de texto OCR de imágenes, selector de colores, captura de pantalla desplazable y subida automática a tu destino elegido.", beginnerGuide: "Presiona ImprPantalla para seleccionar un área. Puedes añadir anotaciones con flechas, desenfocar contraseñas sensibles y copiar directamente al portapapeles." }, fr: { tagline: "Capture d'écran, enregistrement et téléverseur de fichiers", description: "Un utilitaire open source et léger pour Windows qui permet de capturer ou d'enregistrer n'importe quelle zone de votre écran et de la partager avec une seule touche.", whyItsAwesome: "Extraction de texte par OCR depuis les images, pipettes de couleur, capture de défilement, et téléversement automatique vers votre destination choisie.", beginnerGuide: "Appuyez sur Impr. écran pour sélectionner une zone à capturer. Vous pouvez ajouter des annotations, flouter des mots de passe sensibles, et copier directement dans le presse-papiers." }, de: { tagline: "Tool für Bildschirmaufnahmen und -aufnahmen", description: "Ein leichtgewichtiges, quelloffenes Tool für Windows, mit dem du jeden Bereich deines Bildschirms aufnehmen oder aufzeichnen und mit einer einzigen Tastenkombination teilen kannst.", whyItsAwesome: "Enthält integrierte OCR-Texterkennung aus Bildern, Farbwähler, Bildschirmaufnahmen mit Scrollen und automatisches Hochladen an dein Ziel.", beginnerGuide: "Drücke Druck, um einen Bereich auszuwählen. Du kannst mit Pfeilen annotieren, sensible Passwörter unscharf machen und direkt in die Zwischenablage kopieren." } },
  'vlc': { fa: { tagline: "پخش‌کننده چندرسانه‌ای جهانی و موتور استریمینگ", description: "یک پخش‌کننده چندرسانه‌ای رایگان، متن‌باز و چند‌پلتفرمی که اکثر فایل‌های چندرسانه‌ای، دی‌وی‌دی، سی‌دی صوتی و استریم‌های مختلف را بدون نیاز به کدک پخش می‌کند.", whyItsAwesome: "تقریباً هر فرمت ویدیویی یا صوتی را بدون نصب پکیج کدک خارجی پخش می‌کند، بدون اسپای‌ویر و بدون تبلیغات.", beginnerGuide: "روی هر فایل رسانه‌ای دابل‌کلیک کنید. اگر صدای یک ترک کم است، VLC اجازه می‌دهد تا با اسلایدر یا اسکرول موس، حجم را تا ۱۲۵ درصد افزایش دهید." }, es: { tagline: "Reproductor multimedia universal y motor de streaming", description: "Un reproductor multimedia gratuito y de código abierto multiplataforma que reproduce la mayoría de archivos multimedia, DVDs, CDs de audio, VCDs y varios protocolos de streaming sin necesidad de códecs.", whyItsAwesome: "Reproduce casi cualquier formato de vídeo o audio sin instalar paquetes de códecs externos, no contiene spyware y no muestra anuncios.", beginnerGuide: "Haz doble clic en cualquier archivo multimedia para abrirlo. Si un audio está bajo, VLC permite subir el volumen hasta un 125% usando el deslizador o la rueda del ratón." }, fr: { tagline: "Lecteur multimédia universel et moteur de streaming", description: "Un lecteur multimédia gratuit et open source multiplateforme qui lit la plupart des fichiers multimédias ainsi que les DVD, CD audio, VCD et divers protocoles de streaming sans besoin de codecs.", whyItsAwesome: "Lit virtuellement tous les formats de fichiers vidéo ou audio sans installer de packs de codecs externes, ne contient aucun espion et n'affiche aucune publicité.", beginnerGuide: "Double-cliquez sur n'importe quel fichier média pour l'ouvrir. Si une piste audio est faible, VLC permet d'augmenter le volume jusqu'à 125 % avec le curseur ou la molette de la souris." }, de: { tagline: "Universeller Mediaplayer und Streaming-Engine", description: "Ein kostenloser, quelloffener, plattformübergreifender Mediaplayer, der die meisten Medienformate sowie DVDs, Audio-CDs, VCDs und diverse Streaming-Protokolle abspielt, ohne dass Codec-Pakete benötigt werden.", whyItsAwesome: "Spielt praktisch jedes Video- oder Audioformat ab, ohne externe Codec-Pakete zu installieren, enthält keine Spyware und zeigt keine Werbung.", beginnerGuide: "Doppelklicke auf eine Mediendatei, um sie zu öffnen. Wenn eine Audiospur leise ist, kannst du die Lautstärke in VLC bis zu 125 Prozent erhöhen." } },
  'obsidian': { fa: { tagline: "پایگاه دانش شخصی مبتنی بر مارک‌داون", description: "یک پایگاه دانش قدرتمند که روی یک پوشه محلی از فایل‌های ساده متنی مارک‌داون کار می‌کند. با حریم خصوصی کامل و بدون قفل‌شدن به یک پلتفرم.", whyItsAwesome: "یادداشت‌های شما به صورت فایل‌های متنی ساده (.md) روی هارد دیسکتان باقی می‌مانند، یعنی داده‌هایتان برای همیشه متعلق به شماست و تحت تأثیر هیچ شرکتی قرار نمی‌گیرد.", beginnerGuide: "یک پوشه‌ای برای پایگاه خود بسازید. افکارتان را تایپ کنید، از براکت‌های دوگانه برای لینک کردن صفحات استفاده کنید و برای دیدن ایده‌هایتان به گراف ویو بروید." }, es: { tagline: "Base de conocimiento personal con Markdown", description: "Una base de conocimiento potente que funciona sobre una carpeta local de archivos de texto plano Markdown. Privacidad total sin ataduras.", whyItsAwesome: "Tus notas permanecen en tu disco duro como archivos de texto plano simples (.md), lo que significa que posees tus datos para siempre, pase lo que pase con cualquier empresa.", beginnerGuide: "Crea una carpeta vault en tu PC. Escribe tus pensamientos, usa corchetes dobles para enlazar páginas y cambia a Vista Gráfica para ver tus ideas conectadas." }, fr: { tagline: "Base de connaissances personnelle en Markdown", description: "Une base de connaissances qui fonctionne sur un dossier local de fichiers texte Markdown. Confidentialité totale et aucun lock-in.", whyItsAwesome: "Vos notes restent sur votre disque dur sous forme de fichiers texte simples (.md), ce qui signifie que vous possédez vos données pour toujours, peu importe ce qui arrive à n'importe quelle entreprise.", beginnerGuide: "Créez un dossier vault sur votre PC. Tapez vos idées, utilisez des crochets doubles pour lier les pages, et passez en Vue Graphe pour voir vos idées connectées." }, de: { tagline: "Persönliche Wissensbasis mit Markdown", description: "Eine leistungsstarke Wissensbasis, die auf einem lokalen Ordner mit einfachen Text-Markdown-Dateien basiert. Volle Privatsphäre ohne Lock-in.", whyItsAwesome: "Deine Notizen bleiben als einfache Textdateien (.md) auf deiner Festplatte, du besitzt deine Daten also für immer, egal was mit einem Unternehmen passiert.", beginnerGuide: "Erstelle einen Vault-Ordner auf deinem PC. Tippe deine Gedanken, verwende doppelte eckige Klammern, um Seiten zu verlinken, und wechsle in die Graphansicht, um deine Ideen zu sehen." } },
  'bitwarden': { fa: { tagline: "مدیریت پسورد متن‌باز", description: "یک راه‌حل مدیریت پسورد امن و متن‌باز برای ذخیره‌ی اعتبارنامه‌ها، جزئیات کارت اعتباری و یادداشت‌های خصوصی با رمزنگاری سرتاسر.", whyItsAwesome: "کاملاً چند‌پلتفرمی با اکستنشن مرورگر و اپلیکیشن موبایل یکپارچه. متن‌باز و توسط محققان مستقل رمزنگاری شده است.", beginnerGuide: "اکستنشن مرورگر را نصب کنید. هنگام ثبت‌نام در هر وب‌سایتی، Bitwarden یک پسورد تصادفی و امن تولید و به صورت خودکار ذخیره می‌کند." }, es: { tagline: "Gestor de contraseñas de código abierto", description: "Una solución de gestión de contraseñas segura y de código abierto para guardar credenciales, detalles de tarjetas de crédito y notas privadas con cifrado de extremo a extremo.", whyItsAwesome: "Totalmente multiplataforma con extensiones de navegador y apps móviles perfectamente integradas. Código abierto auditado por investigadores criptográficos independientes.", beginnerGuide: "Instala la extensión del navegador. Al registrarte en cualquier sitio, Bitwarden generará una contraseña aleatoria segura y la guardará automáticamente." }, fr: { tagline: "Gestionnaire de mots de passe open source", description: "Une solution de gestion de mots de passe sécurisée et open source pour stocker les identifiants, les détails de cartes de crédit et des notes privées chiffrées de bout en bout.", whyItsAwesome: "Entièrement multiplateforme avec des extensions de navigateur et des applications mobiles. Sécurité open source auditée par des chercheurs cryptographiques indépendants.", beginnerGuide: "Installez l'extension de navigateur. Lors de l'inscription sur un site web, Bitwarden générera un mot de passe aléatoire et le sauvegardera automatiquement." }, de: { tagline: "Quelloffener Passwortmanager", description: "Eine sichere, quelloffene Lösung zur Passwortverwaltung zum Speichern von Zugangsdaten, Kreditkarteninformationen und privaten, verschlüsselten Notizen mit Ende-zu-Ende-Verschlüsselung.", whyItsAwesome: "Vollständig plattformübergreifend mit nahtlosen Browser-Erweiterungen und mobilen Apps. Quelloffene Sicherheit, die von unabhängigen Kryptografie-Forschern geprüft wurde.", beginnerGuide: "Installiere die Browser-Erweiterung. Bei der Anmeldung auf einer Webseite generiert Bitwarden ein sicheres, zufälliges Passwort und speichert es automatisch." } },
  'handbrake': { fa: { tagline: "کدکننده ویدیوی متن‌باز", description: "ابزاری برای تبدیل ویدیو از تقریباً هر فرمتی به مجموعه‌ای از کدک‌های مدرن و پشتیبانی‌شده با پریست‌هایی برای وب، موبایل و سینمای خانگی.", whyItsAwesome: "فایل‌های ویدیویی بزرگ را بدون افت کیفیت قابل توجه فشرده می‌کند. عالی برای کاهش حجم ویدیو قبل از اشتراک‌گذاری.", beginnerGuide: "یک ویدیو را پنجره HandBrake بیندازید، پریست Fast 1080p30 را انتخاب کنید، محل ذخیره‌ی فایل خروجی را مشخص کرده و Start Encode را بزنید." }, es: { tagline: "Transcodificador de vídeo de código abierto", description: "Una herramienta para convertir vídeo de casi cualquier formato a una selección de códecs modernos y ampliamente compatibles, con ajustes predefinidos para web, móvil y cine en casa.", whyItsAwesome: "Comprime archivos de vídeo grandes a tamaños manejables sin pérdida de calidad perceptible. Perfecto para reducir el tamaño de los vídeos antes de compartirlos.", beginnerGuide: "Suelta un vídeo en la ventana de HandBrake, elige el ajuste predefinido Rápido 1080p30, selecciona dónde quieres guardar el archivo y haz clic en Iniciar Codificación." }, fr: { tagline: "Transcodeur vidéo open source", description: "Un outil pour convertir des vidéos à partir de presque n'importe quel format vers une sélection de codecs modernes et largement pris en charge, avec des préréglages pour le web, mobile et le cinéma.", whyItsAwesome: "Compresse les gros fichiers vidéo à des tailles gérables sans perte de qualité notable. Idéal pour réduire la taille des vidéos avant de les partager.", beginnerGuide: "Déposez une vidéo dans la fenêtre de HandBrake, choisissez le préréglage Rapide 1080p30, sélectionnez où enregistrer le fichier de sortie, et cliquez sur Démarrer l'encodage." }, de: { tagline: "Quelloffener Video-Transcoder", description: "Ein Werkzeug zum Konvertieren von Videos aus fast jedem Format in eine Auswahl modern, weit verbreiteter Codecs mit Voreinstellungen für Web, Mobilgeräte und Heimkinos.", whyItsAwesome: "Komprimiert große Videodateien auf handhabbare Größen ohne spürbaren Qualitätsverlust. Ideal zur Größenreduzierung vor dem Teilen.", beginnerGuide: "Ziehe ein Video in das HandBrake-Fenster, wähle die Voreinstellung 'Schnell 1080p30', speicher die Ausgabedatei und klicke auf 'Start Encode'." } },
  'blender': { fa: { tagline: "مجموعه‌ی مدلسازی، انیمیشن و رندرینگ سه‌بعدی", description: "مجموعه‌ی رایگان و متن‌باز ساخت سه‌بعدی که شامل مدلسازی، اسکلت‌بندی، انیمیشن، شبیه‌سازی، رندرینگ، ترکیب‌بندی، ردیابی حرکت و ویرایش ویدیو است.", whyItsAwesome: "قابلیت‌های استاندارد صنعتی که در فیلم‌ها و بازی‌های بزرگ استفاده می‌شود، کاملاً رایگان بدون اشتراک یا محدودیت قابلیت‌ها.", beginnerGuide: "با آموزش‌های مقدماتی مدلسازی دونات در یوتیوب شروع کنید تا با ناوبری ویوپورت با دکمه‌ی ماوس وسط، G برای جابجایی و S برای تغییر اندازه آشنا شوید." }, es: { tagline: "Suite de modelado 3D, animación y renderizado", description: "La suite de creación 3D gratuita y de código abierto que soporta modelado, esqueleto, animación, simulación, renderizado, composición, seguimiento de movimiento y edición de vídeo.", whyItsAwesome: "Capacidades de nivel industrial usadas en grandes películas y videojuegos, completamente gratuita sin suscripción ni bloqueo de funciones.", beginnerGuide: "Empieza con los tutoriales de modelado de donuts en YouTube para aprender a navegar por la vista con el botón central del ratón, G para agarrar y S para escalar." }, fr: { tagline: "Suite de modélisation 3D, d'animation et de rendu", description: "La suite de création 3D gratuite et open source prenant en charge le modélisme, le rigging, l'animation, la simulation, le rendu, le compositage, le suivi de mouvement et le montage vidéo.", whyItsAwesome: "Capacités de niveau industriel utilisées dans les grands films et jeux vidéo, entièrement gratuite sans abonnement ou restriction de fonctionnalités.", beginnerGuide: "Commencez par les tutoriels de modélisation de donuts sur YouTube pour apprendre la navigation dans la vue avec le bouton central de la souris, G pour saisir et S pour l'échelle." }, de: { tagline: "Suite für 3D-Modellierung, Animation und Rendering", description: "Die kostenlose, quelloffene 3D-Erstellungssuite für Modellierung, Rigging, Animation, Simulation, Rendering, Compositing, Motion Tracking und Videoschnitt.", whyItsAwesome: "Branchenstandardfähigkeiten, die in großen Filmen und Videospielen verwendet werden, komplett kostenlos ohne Abonnement oder eingeschränkte Funktionen.", beginnerGuide: "Beginne mit Einführungs-Tutorials zum Donut-Modellieren auf YouTube, um die Navigation im Ansichtsfenster mit der mittleren Maustaste, G zum Verschieben und S zum Skalieren zu lernen." } },
  'krita': { fa: { tagline: "برنامه نقاشی دیجیتال و تصویرسازی دو‌بعدی", description: "یک برنامه نقاشی حرفه‌ای، رایگان و متن‌باز که توسط هنرمندان ساخته شده تا ابزارهای هنری مقرون‌به‌صرفه برای همه در دسترس باشد. عالی برای کامیک و آرت کانستپت.", whyItsAwesome: "بیش از ۱۰۰ براش حرفه‌ای، ثبات‌دهنده براش برای خطوط صاف تمیز و انیمیشن دو‌بعدی فریم‌به‌فریم یکپارچه.", beginnerGuide: "یک براش از پنل سمت راست انتخاب کنید، کلید B را فشار دهید تا روی کانواس شروع به اسکتچ کنید و با Shift+بکشید، قطره براش را به صورت روان تغییر دهید." }, es: { tagline: "Programa de pintura digital e ilustración 2D", description: "Un programa de pintura profesional y gratuito de código abierto, hecho por artistas que quieren que las herramientas de arte sean accesibles para todos. Ideal para cómics y arte conceptual.", whyItsAwesome: "Más de 100 pinceles diseñados profesionalmente, estabilizadores de pincel para líneas suaves y limpias, e integración de animación 2D fotograma a fotograma.", beginnerGuide: "Selecciona un pincel predefinido en el panel derecho, pulsa B para empezar a bosquejar en tu lienzo y usa Shift más arrastrar para redimensionar el diámetro del pincel suavemente." }, fr: { tagline: "Programme de peinture numérique et d'illustration 2D", description: "Un programme de peinture professionnel et open source créé par des artistes qui souhaitent voir des outils d'art abordables pour tous. Excellent pour les bandes dessinées et l'art conceptuel.", whyItsAwesome: "Plus de 100 pinceaux conçus par des professionnels, stabilisateurs de pinceau pour des lignes lisses et propres, et animation 2D image par image intégrée.", beginnerGuide: "Sélectionnez un préréglage de pinceau dans le dock de droite, appuyez sur B pour commencer à esquisser sur votre toile, et utilisez Maj + glisser pour redimensionner le diamètre du pinceau." }, de: { tagline: "Digitales Mal- und 2D-Illustrationsprogramm", description: "Ein professionelles, kostenloses und quelloffenes Malprogramm, das von Künstlern entwickelt wurde, die erschwingliche Werkzeuge für alle wollten. Ideal für Comics und Concept Art.", whyItsAwesome: "Über 100 professionell gestaltete Pinsel, Pinselstabilisator für saubere Linien und integrierte 2D-Zeichenanimation (Frame-for-Frame).", beginnerGuide: "Wähle einen Pinselvorgaben im rechten Dock, drücke B, um auf der Leinwand zu zeichnen, und verwende Umschalt + Ziehen, um den Pinseldurchmesser glatt zu ändern." } },
  '7zip': { fa: { tagline: "فشرده‌ساز فایل با فشرده‌سازی بالا", description: "نسخه رسمی و آپ‌استریم فرمت 7z که اکنون به صورت آزاد روی GitHub توسعه می‌یابد. یک فشرده‌ساز رایگان با نسبت فشرده‌سازی بالا. پشتیبانی از استخراج تقریباً همه فرمت‌های آرشیو شامل ZIP، RAR، 7z، TAR و ISO.", whyItsAwesome: "کاملا رایگان بدون پاپ‌آپ منقضی شدن نسخه آزمایشی، استفاده بسیار کم از حافظه و پشتیبانی از رمزنگاری قوی AES-256.", beginnerGuide: "روی هر فایل یا پوشه در اکسپلورر ویندوز راست‌کلیک کنید، منوی 7-Zip را باز کرده و روی Add to archive کلیک کنید تا یک فایل فشرده zip یا 7z ایجاد کنید." }, es: { tagline: "Compresor de archivos de alta relación", description: "La versión oficial del formato 7z, ahora desarrollado abiertamente en GitHub. Un compresor de archivos gratuito con alta relación de compresión. Soporta descompresión de casi todos los formatos, incluyendo ZIP, RAR, 7z, TAR e ISO.", whyItsAwesome: "Totalmente sin pop-ups de prueba expirada, usa muy poca memoria y soporta cifrado AES-256 fuerte para contraseñas.", beginnerGuide: "Haz clic derecho en cualquier archivo o carpeta en el Explorador de Windows, abre el menú de 7-Zip y haz clic en 'Añadir al archivo' para crear un archivo zip o 7z compacto." }, fr: { tagline: "Archiveur de fichiers à haute compression", description: "La version officielle du format 7z, maintenant développé ouvertement sur GitHub. Un archiveur gratuit avec un taux de compression élevé. Prend en charge la décompression de presque tous les formats d'archive, dont ZIP, RAR, 7z, TAR et ISO.", whyItsAwesome: "Complètement gratuit sans fenêtres d'essai expirées, utilise très peu de mémoire et prend en charge le chiffrement AES-256 fort pour les mots de passe.", beginnerGuide: "Cliquez avec le bouton droit sur n'importe quel fichier ou dossier dans l'explorateur Windows, ouvrez le menu 7-Zip et cliquez sur Ajouter à l'archive pour créer un fichier zip ou 7z compact." }, de: { tagline: "Hochkomprimierendes Archivierungsprogramm", description: "Die offizielle Version des 7z-Formats, die jetzt offen auf GitHub entwickelt wird. Ein kostenloses Archivierungsprogramm mit hoher Komprimierungsrate. Entpackt fast jedes Archivformat, darunter ZIP, RAR, 7z, TAR und ISO.", whyItsAwesome: "Komplett kostenlos ohne Abo-Verfallsbenachrichtigungen, verwendet sehr wenig Speicher und unterstützt die starke AES-256-Verschlüsselung für Passwörter.", beginnerGuide: "Klicke mit der rechten Maustaste auf eine Datei oder einen Ordner im Windows Explorer, öffne das 7-Zip-Menü und klicke auf „Zum Archiv hinzufügen“, um eine kompakte ZIP- oder 7z-Datei zu erstellen." } },
  'devtoys': { fa: { tagline: "چاقوی سوئیسی آفلاین برای توسعه‌دهندگان", description: "یک جعبه ابزار دسکتاپ برای توسعه‌دهندگان که به کارهای روزانه مانند فرمت‌سازی JSON، رمزگشایی JWT، مقایسه تفاوت‌های متنی و تست عبارات باقاعده کمک می‌کند.", whyItsAwesome: "به طور 100 درصد آفلاین روی کامپیوتر محلی شما اجرا می‌شود، بنابراین توکن‌های خصوصی و داده‌های حساس کلاینت هرگز به وب‌سایت‌های خارجی ارسال نمی‌شوند.", beginnerGuide: "DevToys را باز کنید، متن فرمت‌نشده را در ابزار JSON Formatter یا Base64 قرار دهید و خروجی تمیز و فرمت‌شده را ببینید." }, es: { tagline: "Navaja suiza para desarrolladores offline", description: "Un escritorio de herramientas para desarrolladores que ayuda con tareas diarias como formatear JSON, decodificar JWTs, comparar diferencias de texto y probar expresiones regulares.", whyItsAwesome: "Opera 100 por ciento offline en tu computadora local, por lo que nunca se envían tokens privados ni datos sensibles de clientes a sitios web externos.", beginnerGuide: "Abre DevToys, pega texto sin formato en el 'JSON Formatter' o la herramienta 'Base64', y verás la salida decodificada y formateada al instante." }, fr: { tagline: "Couteau suisse hors ligne pour développeurs", description: "Une boîte à outils de bureau pour développeurs qui aide avec des tâches quotidiennes comme formater du JSON, décoder des JWT, comparer des différences de texte et tester des expressions régulières.", whyItsAwesome: "Fonctionne 100% hors ligne sur votre ordinateur local, ainsi les jetons privés et les données sensibles des clients ne sont jamais envoyés à des sites web externes.", beginnerGuide: "Ouvrez DevToys, collez du texte non formaté dans l'outil JSON Formatter ou Base64, et voyez le résultat propre et décodé formaté instantanément." }, de: { tagline: "Offline-Schweizer Taschenmesser für Entwickler", description: "Ein Desktop-Toolkasten für Entwickler, der bei täglichen Aufgaben wie der Formatierung von JSON, dem Decodieren von JWTs, dem Vergleich von Textunterschieden und dem Testen von regulären Ausdrücken hilft.", whyItsAwesome: "Läuft zu 100 % offline auf deinem lokalen Computer, sodass private Tokens und sensible Kundendaten niemals an externe Webseiten gesendet werden.", beginnerGuide: "Öffne DevToys, füge unformatierten Text in den JSON-Formatter oder das Base64-Tool ein und sieh die saubere, dekodierte Ausgabe, die sofort formatiert wird." } },
  'vscodium': { fa: { tagline: "ویرایشگر کد متن‌باز بدون ردیابی", description: "نسخه‌های باینری مبتنی بر جامعه از مخزن VS Code با غیرفعال‌سازی ردیابی، پایش و مجوزهای مالکانه مایکروسافت.", whyItsAwesome: "تجربه دقیقاً یکسان با اکوسیستم پسوندها و ویرایشگر Visual Studio Code، با صفر داده ردیابی تأییدشده به سرورها ارسال شده است.", beginnerGuide: "یک پوشه پروژه را باز کنید، پسوند زبان برنامه‌نویسی خود را از بازار گشوده نصب کنید و در یک محیط تمیز کدنویسی را شروع کنید." }, es: { tagline: "Editor de código abierto sin telemetría", description: "Versiones binarias impulsadas por la comunidad del repositorio de VS Code, con telemetría, seguimiento y licencias propietarias de Microsoft deshabilitadas.", whyItsAwesome: "El mismo ecosistema de extensiones y experiencia de edición que Visual Studio Code, con cero datos de verificación enviados a servidores.", beginnerGuide: "Abre una carpeta de proyecto, instala la extensión de tu lenguaje de programación desde el mercado abierto y empieza a programar en un entorno limpio." }, fr: { tagline: "Éditeur de code open source sans télémétrie", description: "Binaires pilotés par la communauté du dépôt VS Code, avec la télémétrie, le suivi et la licence propriétaire de Microsoft désactivés.", whyItsAwesome: "Le même écosystème d'extensions et la même expérience de modification que Visual Studio Code, avec une vérification de zéro donnée de suivi envoyée aux serveurs.", beginnerGuide: "Ouvrez un dossier de projet, installez l'extension de votre langage de programmation depuis la place de marché ouverte, et commencez à coder dans un environnement propre." }, de: { tagline: "Datenschutz-freier Open-Source-Code-Editor", description: "Von der Community betriebene Binärdateien des VS-Code-Repositories mit deaktivierter Microsoft-Telemetrie, Verfolgung und proprietärer Lizenzierung.", whyItsAwesome: "Die exakt gleiche Erweiterungs-Ökosystem und Bearbeitungserfahrung wie Visual Studio Code, mit bestätigt null Tracking-Daten, die an Server gesendet werden.", beginnerGuide: "Öffne einen Projektordner, installiere deine Programmiersprachenerweiterung aus dem offenen Marketplace und beginne in einer sauberen Umgebung zu codieren." } },
  'rustdesk': { fa: { tagline: "نرم‌افزار رومیزی راه دور متن‌باز", description: "یک برنامه رومیزی دسترسی و کنترل متن‌باز. جایگزین کامل TeamViewer و AnyDesk با قابلیت میزبانی خودکار.", whyItsAwesome: "اتصال رمزنگاری شده از سر تا سر بین کامپیوترها بدون هشدار استفاده تجاری، زمان‌بندی جلسه یا حساب اجباری.", beginnerGuide: "RustDesk را روی هر دو کامپیوتر باز کنید. شناسه و رمز عبور ۹ رقمی کامپیوتر راه دور را وارد کنید تا دسکتاپ آن را ببینید و کنترل کنید." }, es: { tagline: "Software de escritorio remoto de código abierto", description: "Una aplicación de escritorio remota y de control de acceso de código abierto. Alternativa completa a TeamViewer y AnyDesk con capacidad de autohospedaje.", whyItsAwesome: "Conexión cifrada de extremo a extremo entre computadoras sin advertencias de uso comercial, tiempos de espera de sesión o cuentas obligatorias.", beginnerGuide: "Abre RustDesk en ambas computadoras. Ingresa el ID y la contraseña de 9 dígitos de la PC remota en tu computadora para ver y controlar su escritorio." }, fr: { tagline: "Logiciel de bureau à distance open source", description: "Une application de bureau d'accès et de contrôle à distance open source. Alternative complète à TeamViewer et AnyDesk avec la capacité d'hébergement autonome.", whyItsAwesome: "Connexion chiffrée de bout en bout entre ordinateurs, sans avertissements d'utilisation commerciale, délais de session ou comptes forcés.", beginnerGuide: "Ouvrez RustDesk sur les deux ordinateurs. Entrez l'ID et le mot de passe à 9 chiffres de l'ordinateur distant dans le vôtre pour voir et contrôler son bureau." }, de: { tagline: "Open-Source-Fernsoftware", description: "Eine Open-Source-Anwendung für den Fernzugriff und die Steuerung von Desktops. Vollständige Alternative zu TeamViewer und AnyDesk mit der Möglichkeit zur Selbstverwaltung.", whyItsAwesome: "Ende-zu-Ende-verschlüsselte Verbindung zwischen Computern ohne Warnungen für kommerzielle Nutzung, Sitzungs-Timeouts oder erzwungene Konten.", beginnerGuide: "Öffne RustDesk auf beiden Computern. Gib die 9-stellige ID und das Passwort des Remote-PCs in deinem Computer ein, um dessen Desktop anzuzeigen und zu steuern." } },
  'inkscape': { fa: { tagline: "ویرایشگر گرافیک برداری حرفه‌ای", description: "یک ویرایشگر گرافیک برداری برای ایجاد تصاویر، لوگوها، آیکون‌ها، نمودارها و تایپوگرافی با استفاده از فرمت استاندارد باز W3C SVG.", whyItsAwesome: "جایگزین رایگان Adobe Illustrator که مستقیماً با فایل‌های بومی SVG کار می‌کند، بنابراین آثار شما تا هر اندازه‌ای روی صفحه نمایش بزرگ می‌شوند.", beginnerGuide: "اشکال ساده با ابزار مستطیل یا دایره بکشید، آن‌ها را با عملیات مسیر (Union, Difference) ترکیب کنید و مستقیماً به PNG یا SVG صادر کنید." }, es: { tagline: "Editor de gráficos vectoriales profesional", description: "Un editor de gráficos vectoriales para crear ilustraciones, logos, iconos, diagramas y tipografía usando el formato SVG estándar abierto de W3C.", whyItsAwesome: "Alternativa gratuita a Adobe Illustrator que trabaja directamente con archivos SVG nativos, por lo que tu arte se escala infinitamente a cualquier tamaño de pantalla.", beginnerGuide: "Dibuja formas simples usando las herramientas de rectángulo o círculo, combínalas con operaciones de Ruta (Unión, Diferencia) y exporta directamente a PNG o SVG." }, fr: { tagline: "Éditeur de graphisme vectoriel professionnel", description: "Un éditeur de graphisme vectoriel pour créer des illustrations, logos, icônes, diagrammes et typographie utilisant le format SVG standard ouvert du W3C.", whyItsAwesome: "Alternative gratuite à Adobe Illustrator qui fonctionne directement avec les fichiers SVG natifs, donc votre artwork se redimensionne à l'infini à n'importe quelle taille d'écran.", beginnerGuide: "Dessinez des formes simples avec les outils rectangle ou cercle, combinez-les avec des opérations de Chemin (Union, Différence), et exportez directement en PNG ou SVG." }, de: { tagline: "Professioneller Vektorgrafik-Editor", description: "Ein Vektorgrafik-Editor zum Erstellen von Illustrationen, Logos, Icons, Diagrammen und Typografie im offenen W3C-Standardformat SVG.", whyItsAwesome: "Kostenlose Alternative zu Adobe Illustrator, die direkt mit nativen SVG-Dateien arbeitet, sodass deine Grafiken auf jeden Bildschirmmaßstab skaliert werden können.", beginnerGuide: "Zeichne einfache Formen mit den Rechteck- oder Kreiswerkzeugen, kombiniere sie mit Pfadoperationen (Vereinigen, Differenz) und exportiere direkt nach PNG oder SVG." } },
  'audacity': { fa: { tagline: "ویرایشگر و ضبط چندترکه صدا", description: "یک ویرایشگر و ضبط‌کننده صدا چندترکه و آسان برای ضبط صوت زنده، ویرایش پادکست، حذف نویز پس‌زمینه و افزودن افکت‌های صوتی.", whyItsAwesome: "شامل فیلترهای کاهش نویز داخلی که نویس و وزش فن را از ضبط‌های میکروفون در دو کلیک ساده پاک می‌کنند.", beginnerGuide: "برای ضبط صدای خود روی دایره قرمز کلیک کنید. سکوت پس‌زمینه را هایلایت کنید، Effect > Noise Removal > Get Profile را بزنید، سپس تمام صدا را انتخاب و اعمال کنید." }, es: { tagline: "Editor y grabador de audio multipista", description: "Un editor y grabador de audio multipista fácil de usar para grabar audio en vivo, recortar podcasts, eliminar ruido de fondo y añadir efectos de audio.", whyItsAwesome: "Incluye filtros de reducción de ruido integrados que limpian siseo y zumbido de ventilador de grabaciones de micrófono en dos simples clics.", beginnerGuide: "Haz clic en el círculo rojo para grabar tu voz. Resalta el silencio de fondo, haz clic en 'Efecto > Eliminar ruido > Obtener perfil', luego selecciona todo el audio y aplica." }, fr: { tagline: "Éditeur et enregistreur audio multi-pistes", description: "Un éditeur et enregistreur audio multi-pistes facile à utiliser pour enregistrer de l'audio en direct, couper des podcasts, supprimer le bruit de fond et ajouter des effets audio.", whyItsAwesome: "Inclut des filtres intégrés de réduction de bruit qui éliminent le sifflement et le bourdonnement du ventilateur des enregistrements microphone en deux clics simples.", beginnerGuide: "Cliquez sur le cercle rouge pour enregistrer votre voix. Mettez en évidence le silence de fond, cliquez sur Effet > Suppression du bruit > Obtenir un profil, puis sélectionnez tout l'audio et appliquez." }, de: { tagline: "Multitrack-Audioeditor und -rekorder", description: "Ein einfacher, multitrackfähiger Audioeditor und -rekorder zum Aufnehmen von Live-Audio, Schneiden von Podcasts, Entfernen von Hintergrundgeräuschen und Hinzufügen von Audioeffekten.", whyItsAwesome: "Enthält integrierte Rauschunterdrückungsfilter, die Knistern und Lüftergeräusche aus Mikrofonaufnahmen in zwei einfachen Klicks entfernen.", beginnerGuide: "Klicke auf den roten Kreis, um deine Stimme aufzunehmen. Markiere die Hintergrundstille, klicke auf Effekt > Rauschunterdrückung > Profil erstellen, dann wähle die gesamte Audiospur aus und wende es an." } },
  'losslesscut': { fa: { tagline: "برش‌دهنده بدون اتلاف ویدیو و صدا", description: "چاقوی سوئیسی برش و بریدن بدون اتلاف ویدیو و صدا. ویدیو را مستقیماً با FFmpeg برش می‌دهد و بدون کدگذاری مجدد، کیفیت دقیق اصلی را حفظ می‌کند.", whyItsAwesome: "فایل‌های ویدیویی را در ثانیه برش و ادغام می‌کند به جای منتظر ماندن برای دقیقه‌ها یا ساعت‌ها کدگذاری مجدد، بدون هیچ اتلاف کیفی نسل.", beginnerGuide: "یک فایل ویدیو را بکشید و در برنامه بیندازید، از کلید I برای نقطه شروع و کلید O برای نقطه پایان بخش‌هایی که می‌خواهید نگه دارید استفاده کنید و روی دکمه Export کلیک کنید." }, es: { tagline: "Recortador de video y audio sin pérdida", description: "La navaja suiza del recorte y corte de video y audio sin pérdida. Corta flujos de video directamente usando FFmpeg sin volver a codificar, preservando la calidad original exacta.", whyItsAwesome: "Corta y une archivos de video en segundos en lugar de esperar minutos u horas para volver a codificar, con cero pérdida de calidad generacional.", beginnerGuide: "Arrastra un archivo de video, usa la tecla I para establecer el punto de entrada y la tecla O para el punto de salida de los segmentos que quieres mantener, y haz clic en el botón Exportar." }, fr: { tagline: "Raccourcisseur vidéo et audio sans perte", description: "Le couteau suisse du découpage et de la troncature vidéo et audio sans perte. Coupe les flux vidéo directement avec FFmpeg sans réencodage, préservant la qualité originale exacte.", whyItsAwesome: "Coupe et joint des fichiers vidéo en secondes au lieu d'attendre des minutes ou des heures pour le réencodage, avec une perte de qualité nulle entre les générations.", beginnerGuide: "Glissez un fichier vidéo, utilisez la touche I pour définir le point d'entrée et la touche O pour définir le point de sortie des segments que vous voulez garder, puis cliquez sur le bouton Exporter." }, de: { tagline: "Verlustfreier Video- und Audiotrimmer", description: "Das Schweizer Taschenmesser für das verlustfreie Schneiden von Videos und Audiodateien. Schneidet Videostreams direkt mit FFmpeg um, ohne sie neu zu codieren, und bewahrt die ursprüngliche Qualität.", whyItsAwesome: "Schneidet und verbindet Videodateien in Sekunden anstatt Minuten oder Stunden auf die Neucodierung zu warten, bei null Qualitätsverlust durch Generationen.", beginnerGuide: "Ziehe eine Videodatei hinein, verwende die I-Taste, um den Startpunkt und die O-Taste, um den Endpunkt für die zu behaltenden Segmente festzulegen, und klicke auf den Export-Button." } },
  'keepassxc': { fa: { tagline: "رمزنگار آفلاین و چندپلتفرمی", description: "شاخه جامعه‌ای از KeePass برای کاربرانی که می‌خواهند کنترل کامل بر پایگاه داده خود بدون هیچ وابستگی به سرور ابری داشته باشند.", whyItsAwesome: "تمام رمزهای عبور شما را در یک فایل رمزنگاری شده .kdbx واحد ذخیره می‌کند که می‌توانید روی کامپیوتر خود نگه دارید یا روی یک درایو USB نسخه پشتیبان بگیرید.", beginnerGuide: "یک پایگاه داده جدید بسازید و یک رمز عبور اصلی قوی تنظیم کنید. برای هر سایت ورودی اضافه کنید و از auto-type برای ورود امن به سایت‌ها استفاده کنید." }, es: { tagline: "Cofre de contraseñas offline multiplataforma", description: "Una bifurcación comunitaria de KeePass diseñada para usuarios que quieren control total sobre su base de datos sin ninguna dependencia de servidor en la nube.", whyItsAwesome: "Almacena todas tus contraseñas en un único archivo .kdbx cifrado que puedes mantener en tu computadora o respaldar en una unidad USB.", beginnerGuide: "Crea una nueva base de datos y establece una contraseña maestra fuerte. Añade entradas para cada sitio web, luego usa auto-tipeo para iniciar sesión en sitios de forma segura." }, fr: { tagline: "Coffre-fort de mots de passe hors ligne multi-plateforme", description: "Une bifurcation communautaire de KeePass conçue pour les utilisateurs qui veulent un contrôle total sur leur base de données sans aucune dépendance de serveur cloud.", whyItsAwesome: "Stocke tous vos mots de passe dans un seul fichier .kdbx chiffré que vous pouvez garder sur votre ordinateur ou sauvegarder sur une clé USB.", beginnerGuide: "Créez une nouvelle base de données et définissez un mot de passe maître fort. Ajoutez des entrées pour chaque site web, puis utilisez le remplissage automatique pour vous connecter en toute sécurité." }, de: { tagline: "Offline, plattformübergreifender Passwortspeicher", description: "Community-Version von KeePass für Benutzer, die die vollständige Kontrolle über ihre Datenbank ohne Abhängigkeiten von Cloud-Servern möchten.", whyItsAwesome: "Speichert alle deine Passwörter in einer einzigen verschlüsselten .kdbx-Datei, die du auf deinem Computer behalten oder auf einem USB-Laufwerk sichern kannst.", beginnerGuide: "Erstelle eine neue Datenbank und setze ein starkes Masterpasswort. Füge Einträge für jede Website hinzu, dann verwende Auto-Type, um sicher auf Seiten einzuloggen." } },
  'bruno': { fa: { tagline: "کلاینت آفلاین API، سریع و دوست‌دار Git", description: "یک کلاینت دسکتاپ متن‌باز API که مجموعه‌ها را مستقیماً در یک پوشه از فایل‌سیستم شما با استفاده از متن ساده ذخیره می‌کند تا کنترل نسخه‌ها طبیعی شود.", whyItsAwesome: "نیازی به همگام‌سازی ابری نیست، محدودیت ورود تیم صفر است، و می‌توانید مجموعه درخواست‌های API را مستقیماً با کد خود در Git ثبت کنید.", beginnerGuide: "یک پوشه محلی را به Bruno معرفی کنید، یک درخواست با یک URL بسازید، روی ارسال کلیک کنید، و هدرها، کوکی‌ها و پاسخ‌های JSON را بلافاصله بررسی کنید." }, es: { tagline: "Cliente de API rápido y amigable con Git", description: "Un cliente de API de código abierto que guarda colecciones directamente en una carpeta de tu sistema usando texto plano, haciendo el control de versiones natural.", whyItsAwesome: "No requiere sincronización en la nube, no tiene límites de inicio de sesión para equipos, y puedes guardar colecciones de peticiones de API en Git junto con tu código.", beginnerGuide: "Apunta Bruno a un directorio local, crea una petición con una URL, haz clic en Enviar e inspecciona encabezados, cookies y respuestas JSON al instante." }, fr: { tagline: "Client API hors ligne rapide et Git-friendly", description: "Un client API de bureau open source qui stocke les collections directement dans un dossier de votre système de fichiers en utilisant un balisage en texte brut, rendant le contrôle de version naturel.", whyItsAwesome: "Pas de synchronisation cloud requise, aucune limite d'équipe pour la connexion, et vous pouvez envoyer les collections de requêtes API directement dans Git avec votre base de code.", beginnerGuide: "Indiquez à Bruno un répertoire local, créez une requête avec une URL, cliquez sur Envoyer, et inspectez les en-têtes, les cookies et les réponses JSON instantanément." }, de: { tagline: "Schneller, git-freundlicher Offline-API-Client", description: "Eine Open-Source-Desktop-API-Anwendung, die Sammlungen direkt in einem Ordner auf deinem Dateisystem als Klartext speichert und Versionskontrolle einfach macht.", whyItsAwesome: "Keine Cloud-Sync-Anforderung, keine Login-Limits für Teams, und du kannst API-Sammlungen direkt mit deinem Code in Git committen.", beginnerGuide: "Weise Bruno einen lokalen Ordner zu, erstelle eine Anfrage mit einer URL, klicke auf Senden und untersuche Header, Cookies und JSON-Antworten sofort." } },
  'libreoffice': { fa: { tagline: "سوئیت دفتری کامل و رایگان", description: "یک سوئیت دفتری تمیز و متن‌باز که شامل Writer (واژه‌پرداز)، Calc (صفحه‌گسترده)، Impress (ارائه‌ها) و Draw (نمودارهای برداری) است.", whyItsAwesome: "سازگاری کامل با فرمت‌های Microsoft Office (docx, xlsx, pptx) بدون حق اشتراک ماهانه یا نیاز به ابر.", beginnerGuide: "Writer را برای مقالات و گزارش‌ها یا Calc برای صفحه‌گسترده‌ها باز کنید. از فایل > ذخیره با نام برای انتخاب فرمت ODF استاندارد یا Microsoft Office استفاده کنید." }, es: { tagline: "Suite de oficina gratuita y completa", description: "Una suite de oficina limpia y de código abierto que incluye Writer (procesador de texto), Calc (hojas de cálculo), Impress (presentaciones) y Draw (diagramas vectoriales).", whyItsAwesome: "Compatibilidad total con los formatos de Microsoft Office (docx, xlsx, pptx) sin cuotas de suscripción mensuales ni requisitos de nube.", beginnerGuide: "Abre LibreOffice Writer para ensayos e informes o Calc para hojas de cálculo. Usa Archivo > Guardar como para elegir el formato abierto ODF o el formato estándar de Microsoft Office." }, fr: { tagline: "Suite bureautique gratuite et complète", description: "Une suite bureautique propre et open source contenant Writer (traitement de texte), Calc (tableurs), Impress (présentations) et Draw (diagrammes vectoriels).", whyItsAwesome: "Compatibilité totale avec les formats Microsoft Office docx, xlsx et pptx, sans frais d'abonnement mensuel ni besoin de cloud.", beginnerGuide: "Ouvrez LibreOffice Writer pour les essais et rapports, ou Calc pour les tableaux. Utilisez Fichier > Enregistrer sous pour choisir le format ouvert ODF ou le format standard Microsoft Office." }, de: { tagline: "Vollständige kostenlose Office-Suite", description: "Eine saubere und quelloffene Office-Suite mit Writer (Textverarbeitung), Calc (Tabellenkalkulation), Impress (Präsentationen) und Draw (Vektorgrafiken).", whyItsAwesome: "Volle Kompatibilität mit Microsoft Office-Formaten (docx, xlsx, pptx) ohne monatliche Gebühren oder Cloud-Anforderungen.", beginnerGuide: "Öffne LibreOffice Writer für Aufsätze und Berichte oder Calc für Tabellen. Über Datei > Speichern unter wählst du das offene ODF-Format oder das Standard-Microsoft-Office-Format." } },
  'bleachbit': { fa: { tagline: "تمیزکننده سیستم و بهینه‌ساز حریم خصوصی", description: "به سرعت فضای دیسک را با حذف کش‌های سیستم، فایل‌های موقت اینترنت، لاگ‌ها و داده‌های محرمانه پاک‌شده که سرعت کامپیوتر را کاهش می‌دهند، آزاد می‌کند.", whyItsAwesome: "جایگزین رایگان و متن‌باز CCleaner بدون نرم‌افزار تبلیغاتی، ردیابی تله‌متری، و با امکان پاک‌سازی امن فایل‌ها.", beginnerGuide: "برنامه‌هایی که می‌خواهید تمیز شوند را در پنل چپ علامت بزنید، پیش‌نمایش را ببینید تا فضای آزادشده را ببینید، سپس روی تمیز کردن کلیک کنید." }, es: { tagline: "Limpiador de sistema y optimizador de privacidad", description: "Libera espacio en disco rápidamente eliminando cachés del sistema, archivos temporales de internet, archivos de registro y datos confidenciales que ralentizan el ordenador.", whyItsAwesome: "Alternativa gratuita y de código abierto a CCleaner sin adware integrado, seguimiento de telemetría y con opción de eliminación segura de archivos.", beginnerGuide: "Marca las casillas de las aplicaciones que quieres limpiar en el panel izquierdo, haz clic en Vista previa para ver cuánto espacio se liberará, luego haz clic en Limpiar." }, fr: { tagline: "Nettoyeur de système et optimiseur de disque pour la vie privée", description: "Libère rapidement de l'espace disque en supprimant les caches système, les fichiers internet temporaires, les journaux et les données confidentielles qui ralentissent l'ordinateur.", whyItsAwesome: "Alternative gratuite et open source à CCleaner sans publicité groupée, sans suivi de télémétrie et avec un effacement sécurisé de fichiers.", beginnerGuide: "Cochez les cases des applications que vous souhaitez nettoyer dans le panneau de gauche, cliquez sur Aperçu pour voir l'espace libéré, puis cliquez sur Nettoyer." }, de: { tagline: "Systemreiniger und Privatsphäre-Optimierer", description: "Schnelle Befreiung von Festplattenplatz durch das Löschen von Systemcaches, temporären Internetdateien, Protokolldateien und sicher gelöschten vertraulichen Daten.", whyItsAwesome: "Kostenlose und quelloffene Alternative zu CCleaner ohne vorinstallierte Adware, keine Telemetrie und sicheres Dateilöschen.", beginnerGuide: "Aktiviere die Kästchen für die Anwendungen, die du reinigen möchtest, klicke auf Vorschau, um zu sehen, wie viel Platz frei wird, und dann auf Bereinigen." } },
  'ollama': { fa: { tagline: "اجرای مدل‌های هوش مصنوعی محلی روی کامپیوتر شما", description: "به سرعت با مدل‌های زبانی بزرگ به صورت محلی کار را شروع کنید. Llama 3، Mistral و مدل‌های دیگر را روی کامپیوتر خود با حریم خصوصی کامل اجرا کنید.", whyItsAwesome: "کاملاً آفلاین روی سخت‌افزار کامپیوتر شما اجرا می‌شود. درخواست‌ها، کدها و اسناد شما هرگز کامپیوتر محلی را ترک نمی‌کنند.", beginnerGuide: "Ollama را نصب کنید، Command Prompt ویندوز یا ترمینال را باز کنید و \"ollama run llama3\" را تایپ کنید تا با یک مدل هوش مصنوعی به صورت آفلاین مکالمه کنید." }, es: { tagline: "Ejecuta modelos de IA localmente en tu máquina", description: "Pon en marcha modelos de lenguaje grandes localmente. Ejecuta Llama 3, Mistral y otros modelos abiertos en tu computadora con total privacidad.", whyItsAwesome: "Funciona completamente sin conexión en tu hardware. Tus indicaciones, código y documentos nunca abandonan tu máquina local.", beginnerGuide: "Instala Ollama, abre el Símbolo del sistema de Windows o la Terminal y escribe \"ollama run llama3\" para empezar a chatear con un modelo de IA sin conexión." }, fr: { tagline: "Faire tourner des modèles d'IA locaux sur votre propre machine", description: "Démarrez rapidement avec de grands modèles de langage en local. Faites tourner Llama 3, Mistral et d'autres modèles ouverts sur votre ordinateur avec une confidentialité totale.", whyItsAwesome: "Fonctionne entièrement hors ligne sur votre matériel. Vos invites, code et documents ne quittent jamais votre machine locale.", beginnerGuide: "Installez Ollama, ouvrez l'Invite de commandes Windows ou le Terminal, et tapez \"ollama run llama3\" pour discuter avec un modèle d'IA hors ligne." }, de: { tagline: "Lokale KI-Modelle auf deinem Computer", description: "Starte schnell mit großen Sprachmodellen lokal. Führe Llama 3, Mistral und andere Open-Modelle auf deinem Computer mit voller Privatsphäre aus.", whyItsAwesome: "Läuft vollständig offline auf deiner Hardware. Deine Prompts, Codes und Dokumente verlassen niemals deinen lokalen Computer.", beginnerGuide: "Installiere Ollama, öffne die Windows-Eingabeaufforderung oder das Terminal und tippe \"ollama run llama3\", um offline mit einem KI-Modell zu chatten." } },
  'flameshot': { fa: { tagline: "نرم‌افزار اسکرین‌شات قدرتمند و ساده", description: "ابزار اسکرین‌شات متن‌باز و چندپلتفرمی با ظاهر قابل تنظیم، ویرایش درون‌برنامه‌ای، پین کردن و ابزارهای اشاره‌گر/متن.", whyItsAwesome: "انتخاب منطقه فوق‌سریع با ابزار تار کردن پیکسلی فوری برای پنهان کردن رمزها و ایمیل‌ها در یک ضربه.", beginnerGuide: "رابط گرافیکی Flameshot را به یک میانبر کی‌بورد اختصاص دهید. یک مستطاع بکشید، از ابزار تار کردن برای سانسور جزئیات خصوصی استفاده کنید و Enter را فشار دهید تا در کلیپ‌بورد کپی شود." }, es: { tagline: "Software de captura de pantalla potente y sencillo", description: "Una herramienta de captura de pantalla de código abierto, multiplataforma, con apariencia personalizable, edición de capturas dentro de la app, anclaje y anotaciones con flechas y texto.", whyItsAwesome: "Selección de regiones súper rápida con una herramienta de desenfoque de píxeles instantáneo para ocultar contraseñas y correos en un solo trazo.", beginnerGuide: "Asigna un atajo de teclado a la interfaz de Flameshot. Arrastra un rectángulo, usa la herramienta de pixelar para ocultar detalles privados y presiona Entrar para copiar al portapapeles." }, fr: { tagline: "Logiciel de capture d'écran simple et puissant", description: "Un outil de capture d'écran open source et multiplateforme avec une apparence personnalisable, un éditeur intégré, la fonction d'épinglage et des annotations avec des flèches/texte.", whyItsAwesome: "Sélection de zone ultra-rapide avec un outil de floutage par pixelisation instantané pour masquer mots de passe et e-mails en un seul clic.", beginnerGuide: "Associez l'interface graphique de Flameshot à un raccourci clavier. Faites glisser un rectangle, utilisez l'outil de pixelation pour censurer les détails privés, et appuyez sur Entrée pour copier dans le presse-papiers." }, de: { tagline: "Leistungsstark, aber einfaches Screenshot-Tool", description: "Ein quelloffenes, plattformübergreifendes Screenshot-Tool mit anpassbarem Aussehen, In-App-Bearbeitung, Anheften und Pfeil-/Text-Annotationen.", whyItsAwesome: "Schnellste Regionsauswahl mit einem sofortigen Pixelierungs-Tool, um Passwörter und E-Mails mit einem Klick zu verbergen.", beginnerGuide: "Weise Flameshot GUI einer Tastenkürzel zu. Ziehe ein Rechteck, verwende das Pixelierungs-Tool, um private Details zu verwischen, und drücke Enter, um in die Zwischenablage zu kopieren." } },
  'shotcut': { fa: { tagline: "ویرایشگر ویدئوی رایگان، متن‌باز و چندپلتفرمی", description: "یک ویرایشگر ویدئوی غیرخطی که صدها فرمت و کدک صوتی و تصویری را از طریق FFmpeg پشتیبانی می‌کند، با پشتیبانی از رزولوشن 4K و خط زمانی چندمسیری.", whyItsAwesome: "ویرایش خط زمانی بومی بدون نیاز به وارد کردن. کاملاً رایگان بدون واترمارک یا محدودیت در رزولوشن خروجی.", beginnerGuide: "کلپ‌های ویدیویی را در لیست پخش بکشید، آن‌ها را روی خط زمانی بکشید، کلپ‌ها را با S تقسیم کنید و با استفاده از پreset یوتیوب خروجی بگیرید." }, es: { tagline: "Editor de video gratuito, de código abierto y multiplataforma", description: "Un editor de video no lineal que soporta cientos de formatos y códecs de audio y video a través de FFmpeg, con soporte para resolución 4K y líneas de tiempo múltiples.", whyItsAwesome: "Edición de línea de tiempo nativa sin necesidad de importar. Totalmente gratuito sin marca de agua ni restricciones de resolución al exportar.", beginnerGuide: "Arrastra clips de video a la lista de reproducción, bájalos a las pistas de la línea de tiempo, divide los clips con S y exporta usando el preajuste de YouTube." }, fr: { tagline: "Éditeur vidéo gratuit, open source et multiplateforme", description: "Un éditeur vidéo non linéaire prenant en charge des centaines de formats et codecs audio/vidéo via FFmpeg, avec un support en 4K et des pistes temporelles multiples.", whyItsAwesome: "Montage sur timeline natif sans importation requise. Complètement gratuit, sans filigrane ni restrictions sur la résolution d'exportation.", beginnerGuide: "Glissez des clips vidéo dans la liste de lecture, faites-les descendre sur les pistes de la timeline, divisez les clips avec S, et exportez avec le préréglage YouTube." }, de: { tagline: "Kostenloser, quelloffener, plattformübergreifender Videoeditor", description: "Ein nichtlinearer Videoeditor, der Hunderte von Audio- und Videoformaten und Codecs über FFmpeg unterstützt, mit 4K-Auflösung und Mehrspur-Timelines.", whyItsAwesome: "Native Timeline-Bearbeitung ohne Import nötig. Komplett kostenlos ohne Wasserzeichen oder Exportbeschränkungen.", beginnerGuide: "Ziehe Videoclips in die Playlist, ziehe sie auf die Timeline-Spuren, teile Clips mit S und exportiere mit dem YouTube-Voreinstellung." } },
  'syncthing': { fa: { tagline: "همگام‌سازی فایل توزیع‌شده و مداوم", description: "ابزار همگام‌سازی فایل همتا-به-همتا متن‌باز که فایل‌ها را بین دو یا چند کامپیوتر و دستگاه اندروید به صورت همزمان، امن و رمزگذاری شده همگام می‌کند.", whyItsAwesome: "داده‌ها مال شماست. هیچ سرور مرکزی قابل نفوذ یا جاسوسی نیست. به صورت محلی یا اینترنت با صفر هزینه اشتراک ابر کار می‌کند.", beginnerGuide: "Syncthing را روی دسکتاپ و اندروید نصب کنید. کد QR را اسکن کنید تا دستگاه‌ها جفت شوند، پوشه‌های مورد نظر برای همگام‌سازی را انتخاب کنید و فایل‌ها به‌روزرسانی خودکار می‌شوند." }, es: { tagline: "Sincronización descentralizada continua de archivos", description: "Una herramienta de sincronización de archivos de código abierto, punto a punto, que sincroniza archivos entre dos o más ordenadores y dispositivos Android en tiempo real, de forma segura y cifrada.", whyItsAwesome: "Tus datos te pertenecen a ti. Ningún servidor central puede ser comprometido o espiado. Funciona localmente o a través de internet sin cuotas de suscripción a la nube.", beginnerGuide: "Instala Syncthing en el escritorio y en Android. Escanea el código QR para emparejar dispositivos, elige qué carpetas sincronizar y los archivos se actualizarán automáticamente." }, fr: { tagline: "Synchronisation de fichiers décentralisée et continue", description: "Un outil de synchronisation de fichiers pair-à-pair open source qui synchronise les fichiers entre deux ordinateurs ou plus et des appareils Android en temps réel, de manière sécurisée et chiffrée.", whyItsAwesome: "Vos données vous appartiennent uniquement. Aucun serveur central ne peut être compromis ou espionné. Fonctionne localement ou sur internet sans abonnement cloud.", beginnerGuide: "Installez Syncthing sur le bureau et Android. Scannez le code QR pour appareiller les appareils, choisissez quels dossiers synchroniser, et les fichiers se mettent à jour automatiquement." }, de: { tagline: "Kontinuierliche, dezentrale Dateisynchronisation", description: "Ein Open-Source-Peer-to-Peer-Dateisynchronisationstool, das Dateien in Echtzeit, sicher und verschlüsselt zwischen zwei oder mehr Computern und Android-Geräten synchronisiert.", whyItsAwesome: "Deine Daten gehören dir allein. Kein zentraler Server kann kompromittiert oder ausspioniert werden. Funktioniert lokal oder über das Internet ohne Cloud-Abonnementgebühren.", beginnerGuide: "Installiere Syncthing auf Desktop und Android. Scanne den QR-Code, um Geräte zu verbinden, wähle Ordner zur Synchronisation aus und die Dateien werden automatisch aktualisiert." } },
  'joplin': { fa: { tagline: "یادداشت‌برداری امن با رمزنگاری سرتا سر", description: "یک برنامه یادداشت‌برداری و کارهای متن‌باز که می‌تواند تعداد زیادی یادداشت را با فرمت مارک‌داون و برچسب‌ها در دفترچه‌ها سازماندهی کند.", whyItsAwesome: "رمزنگاری سرتا سر (E2EE) تضمین می‌کند هیچ‌کس نمی‌تواند یادداشت‌های شما را بخواند. با Nextcloud، Dropbox، OneDrive یا WebDAV در دسکتاپ و اندروید همگام می‌شود.", beginnerGuide: "دفترچه‌ها بسازید، با مارک‌داون بنویسید و در تنظیمات، همگام‌سازی را با فضای ذخیره‌سازی ابری یا سرور WebDAV مورد نظر فعال کنید." }, es: { tagline: "Toma de notas segura con cifrado de extremo a extremo", description: "Una aplicación de toma de notas y tareas de código abierto que puede manejar una gran cantidad de notas organizadas en cuadernos con formato Markdown y etiquetas.", whyItsAwesome: "El cifrado de extremo a extremo (E2EE) garantiza que nadie pueda leer tus notas. Sincroniza con Nextcloud, Dropbox, OneDrive o WebDAV en escritorio y Android.", beginnerGuide: "Crea cuadernos, escribe en Markdown y activa la sincronización en Configuración usando tu servicio de almacenamiento en la nube preferido o servidor WebDAV." }, fr: { tagline: "Prise de notes sécurisée avec chiffrement de bout en bout", description: "Une application de prise de notes et de liste de tâches open source qui peut gérer un grand nombre de notes organisées en carnets avec un format Markdown et des étiquettes.", whyItsAwesome: "Le chiffrement de bout en bout (E2EE) garantit que personne ne peut lire vos notes. Synchronisez avec Nextcloud, Dropbox, OneDrive ou WebDAV sur le bureau et Android.", beginnerGuide: "Créez des carnets, écrivez en Markdown, et activez la synchronisation dans Configuration avec votre stockage cloud préféré ou votre serveur WebDAV." }, de: { tagline: "Sicheres Notizen mit Ende-zu-Ende-Verschlüsselung", description: "Eine Open-Source-Notiz- und To-Do-Anwendung, die eine große Anzahl von Notizen in Notizbüchern mit Markdown-Format und Tags organisieren kann.", whyItsAwesome: "Ende-zu-Ende-Verschlüsselung (E2EE) garantiert, dass niemand deine Notizen lesen kann. Synchronisiere mit Nextcloud, Dropbox, OneDrive oder WebDAV über Desktop und Android.", beginnerGuide: "Erstelle Notizbücher, schreibe in Markdown und aktiviere die Synchronisation in den Einstellungen mit deiner bevorzugten Cloud-Speicherung oder deinem WebDAV-Server." } },
  'newpipe': { fa: { tagline: "کلاینت استریمینگ اندروید، سبک و محور حریم خصوصی", description: "یک رابط کاربری سبک برای یوتیوب و رسانه‌ها در اندروید، بدون نیاز به سرویس‌های گوگل پلی یا APIهای اختصاصی.", whyItsAwesome: "بدون تبلیغات، پخش در پس‌زمینه، حالت تصویر در تصویر، اشتراک‌های محلی و بدون نیاز به حساب گوگل.", beginnerGuide: "فایل APK را از GitHub یا F-Droid دانلود، روی دستگاه اندرویدی نصب و کانال‌ها را جستجو یا اشتراک‌های خود را وارد کنید." }, es: { tagline: "Cliente ligero y privado para Android", description: "Un frontend ligero de YouTube y multimedia para Android, sin dependencias de Google Play Services ni APIs propietarias.", whyItsAwesome: "Sin anuncios, reproducción en segundo plano, modo picture-in-picture, suscripciones locales y sin cuenta de Google.", beginnerGuide: "Descarga el APK desde GitHub o F-Droid, instálalo en tu Android y busca canales o importa tus suscripciones." }, fr: { tagline: "Client Android léger et respectueux de la vie privée", description: "Une interface légère pour YouTube et d'autres médias sur Android, sans services Google ni API propriétaires.", whyItsAwesome: "Zéro publicité, lecture en arrière-plan, mode Picture-in-Picture, abonnements locaux, pas de compte Google requis.", beginnerGuide: "Téléchargez l'APK depuis GitHub ou F-Droid, installez-le sur votre appareil Android, et cherchez des chaînes ou importez vos abonnements." }, de: { tagline: "Datenschutz-fokussierter Android-Streaming-Client", description: "Ein leichtgewichtiger YouTube- und Medientfrontend für Android ohne Google Play Services oder proprietäre API-Abhängigkeiten.", whyItsAwesome: "Keine Werbung, Hintergrundwiedergabe, Bild-im-Bild-Modus, lokale Abonnements und kein Google-Konto nötig.", beginnerGuide: "Lade die APK von GitHub-Releases oder F-Droid herunter, installiere sie auf deinem Android-Gerät und suche nach Kanälen oder importiere deine Abonnements." } },
  'termux': { fa: { tagline: "محیط ترمینال و لینوکس برای اندروید", description: "یک اپلیکیشن شبیه‌ساز ترمینال و محیط لینوکس برای اندروید که بدون نیاز به روت کردن یا تنظیمات اضافه کار می‌کند.", whyItsAwesome: "سیستمی مینیمال به صورت خودکار نصب می‌شود؛ بسته‌های اضافی مانند پایتون، گیت، نود جی‌اس و سی‌پلاس‌پلاس از طریق APT قابل نصب هستند.", beginnerGuide: "Termux را از F-Droid یا GitHub نصب کنید. اپ را باز، pkg update را اجرا و سپس بسته مورد نظر مثل pkg install python git را نصب کنید." }, es: { tagline: "Emulador de terminal y entorno Linux para Android", description: "Un emulador de terminal y entorno Linux para Android que funciona directamente sin necesidad de root ni configuración.", whyItsAwesome: "Se instala un sistema base mínimo automáticamente; paquetes adicionales disponibles con el gestor APT (Python, Git, Node.js, C++).", beginnerGuide: "Instala Termux desde F-Droid o GitHub. Abre la app, ejecuta pkg update e instala cualquier paquete Linux como pkg install python git." }, fr: { tagline: "Émulateur de terminal et environnement Linux pour Android", description: "Un émulateur de terminal et environnement Linux pour Android qui fonctionne directement, sans root ni configuration.", whyItsAwesome: "Un système de base minimal est installé automatiquement ; des paquets supplémentaires sont disponibles via le gestionnaire de paquets APT (Python, Git, Node.js, C++).", beginnerGuide: "Installez Termux via F-Droid ou GitHub. Ouvrez l'application, lancez pkg update, et installez n'importe quel paquet Linux comme pkg install python git." }, de: { tagline: "Android-Terminal-Emulator und Linux-Umgebung", description: "Ein Android-Terminal-Emulator und Linux-Umgebung, die direkt funktioniert, ohne Root-Zugriff oder Einrichtung.", whyItsAwesome: "Ein minimales Basissystem wird automatisch installiert; zusätzliche Pakete stehen über den APT-Paketmanager (Python, Git, Node.js, C++) zur Verfügung.", beginnerGuide: "Installiere Termux über F-Droid oder GitHub. Öffne die App, führe pkg update aus und installiere beliebige Linux-Pakete wie pkg install python git." } },
  'antennapod': { fa: { tagline: "پخش‌کننده و مدیر پادکست متن‌باز برای اندروید", description: "یک پخش‌کننده پادکست ساده، انعطاف‌پذیر و متن‌باز برای اندروید. بدون تبلیغ، احترام به حریم خصوصی و با تمام ویژگی‌های مورد نیاز.", whyItsAwesome: "بدون تبلیغ و بدون نیاز به حساب، پشتیبانی از استریم، دانلود خودکار، تایمر خواب و همگام‌سازی با gpodder.net.", beginnerGuide: "از طریق F-Droid یا گوگل پلی نصب کنید. پادکست‌های مورد علاقه خود را با آدرس RSS یا نام جستجو و به صورت آفلاین گوش دهید." }, es: { tagline: "Reproductor y gestor de podcasts abierto para Android", description: "Un reproductor de podcasts fácil de usar, flexible y de código abierto para Android. Sin anuncios, respeta tu privacidad y tiene todas las funciones que necesitas.", whyItsAwesome: "Sin anuncios, sin cuenta requerida, soporta streaming, descargas automáticas, temporizador de sueño y sincronización con gpodder.net.", beginnerGuide: "Instálalo desde F-Droid o Google Play, busca tus podcasts favoritos por RSS o nombre, y escucha sin conexión." }, fr: { tagline: "Lecteur et gestionnaire de podcasts open source pour Android", description: "Un lecteur de podcasts simple, flexible et open source pour Android. Sans publicité, respectueux de votre vie privée, avec toutes les fonctionnalités nécessaires.", whyItsAwesome: "Zéro publicité, zéro compte requis, prend en charge le streaming, le téléchargement automatique, minuteur de sommeil et synchronisation avec gpodder.net.", beginnerGuide: "Installez via F-Droid ou Google Play, cherchez vos podcasts préférés par flux RSS ou par nom, et écoutez hors ligne." }, de: { tagline: "Open-Source-Podcast-Player und -Manager für Android", description: "Ein einfacher, flexibler und quelloffener Podcast-Player für Android. Frei von Werbung, respektiert deine Privatsphäre und hat alle Funktionen, die du zum Genießen von Podcasts brauchst.", whyItsAwesome: "Keine Werbung, kein Konto nötig, unterstützt Streaming, automatisches Herunterladen, Schlaf-Timer und gpodder.net-Synchronisation.", beginnerGuide: "Installiere über F-Droid oder Google Play, suche nach deinen Lieblings-Podcasts über RSS-Feed oder Namen und höre offline." } },
  'keepassdx': { fa: { tagline: "مدیریت رمز عبور، مخزن KeePass سبک و آفلاین", description: "یک مدیر رمز عبور سبک برای اندروید که ویرایش و ساخت فایل‌های رمزگذاری شده .kdbx را در رابط کاربری متریال و تمیز فراهم می‌کند.", whyItsAwesome: "100٪ آفلاین، احراز هویت بیومتریک (اثر انگشت/چهره)، پاک‌سازی خودکار کلیپ‌بورد و یکپارچه‌سازی با Magikeyboard برای ورود امن.", beginnerGuide: "فایل پایگاه داده .kdbx خود را روی دستگاه ذخیره یا از طریق Syncthing همگام کنید. با رمز اصلی یا کلید بیومتریک باز کنید." }, es: { tagline: "Gestor de contraseñas offline y ligero para KeePass", description: "Un gestor de contraseñas ligero para Android que permite editar y crear archivos .kdbx cifrados en una interfaz limpia de diseño material.", whyItsAwesome: "100% offline, autenticación biométrica (huella/cara), autolimpieza del portapapeles e integración con Magikeyboard para una entrada segura.", beginnerGuide: "Guarda tu archivo de base de datos .kdbx en tu dispositivo o sincronízalo con Syncthing. Desbloquea con tu contraseña maestra o clave biométrica." }, fr: { tagline: "Gestionnaire de mots de passe de coffre-fort KeePass léger et hors ligne", description: "Un gestionnaire de mots de passe pour Android qui permet de modifier et de créer des fichiers .kdbx chiffrés dans une interface Material Design épurée.", whyItsAwesome: "100 % hors ligne, authentification biométrique (empreinte/visage), nettoyage automatique du presse-papiers, et intégration Magikeyboard pour une saisie sécurisée.", beginnerGuide: "Stockez votre fichier de base de données .kdbx sur votre appareil ou synchronisez-le avec Syncthing. Déverrouillez avec votre mot de passe principal ou votre clé biométrique." }, de: { tagline: "Leichter, offline-fähiger KeePass-Vault-Passwortmanager", description: "Ein leichtgewichtiger Passwortmanager für Android, der das Bearbeiten und Erstellen von verschlüsselten .kdbx-Dateien in einem sauberen Material-Design-Interface ermöglicht.", whyItsAwesome: "Zu 100% offline, biometrische Authentifizierung (Fingerabdruck/Gesicht), automatische Zwischenablage-Löschung und Magikeyboard-Integration für sicheres Eingeben.", beginnerGuide: "Speichere deine .kdbx-Datenbankdatei auf deinem Gerät oder synchronisiere sie via Syncthing. Entsperre sie mit deinem Master-Passwort oder biometrischen Schlüssel." } },
  'organicmaps': { fa: { tagline: "نقشه‌های آفلاین سریع و GPS با قدرت اوپن‌استریت‌مپ", description: "یک اپلیکیشن متن‌باز، متمرکز بر حریم خصوصی برای نقشه‌برداری و ناوبری آفلاین، مبتنی بر داده‌های جمع‌ساز اوپن‌استریت‌مپ.", whyItsAwesome: "جستجو و مسیریابی ۱۰۰٪ آفلاین، ردیابی مکان صفر، و مصرف صفر باتری از سرویس‌های پس‌زمینه.", beginnerGuide: "اپ را روی وای‌فای باز کنید، نقشه منطقه یا ایالت خود را یک بار دانلود کنید و هر جای دنیا به صورت کاملا آفلاین ناوبری کنید." }, es: { tagline: "Mapas y GPS sin conexión rápidos", description: "Una app de mapas y navegación sin conexión, de código abierto y centrada en la privacidad, para viajeros, excursionistas y conductores, basada en datos de OpenStreetMap.", whyItsAwesome: "Búsqueda y enrutamiento 100% sin conexión, sin seguimiento de ubicación y sin consumo de batería por servicios de análisis.", beginnerGuide: "Abre la app con Wi-Fi, descarga el mapa de tu región o estado una vez y navega sin conexión en cualquier lugar del mundo." }, fr: { tagline: "Cartes hors ligne rapides et GPS avec OpenStreetMap", description: "Une application de cartographie et de navigation hors ligne, open source et respectueuse de la vie privée, pour voyageurs, randonneurs et conducteurs, basée sur les données OpenStreetMap.", whyItsAwesome: "Recherche et itinéraires 100% hors ligne, aucun suivi de localisation, aucune consommation de batterie par les services d'analyse.", beginnerGuide: "Ouvrez l'app en Wi-Fi, téléchargez une fois la carte de votre région, et naviguez complètement hors ligne n'importe où dans le monde." }, de: { tagline: "Schnelle Offline-Karten & GPS mit OpenStreetMap", description: "Eine quelloffene, datenschutzorientierte Offline-Navigations-App für Reisende, Wanderer und Autofahrer, basierend auf OpenStreetMap-Daten.", whyItsAwesome: "100% Offline-Suche und -Routing, keine Standortverfolgung, kein Akkuverbrauch durch Analysedienste.", beginnerGuide: "Öffne die App mit WLAN, lade deine Landkarte oder Region einmal herunter und navigiere weltweit komplett offline." } },
  'gimp': { fa: { tagline: "ویرایشگر تصویر کامل و جامع", description: "برنامه GNU برای دستکاری تصویر، جایگزین رایگان فتوشاپ: لایه‌ها، ماسک‌ها، فیلترها، ابزارهای رتوش و سیستم پلاگین‌های قابل اسکریپت.", whyItsAwesome: "توسعه‌یافته در ۳۰ سال گذشته، باز کردن فایل‌های PSD فتوشاپ، اجرا روی هر کامپیوتری و رایگان بدون محدودیت نسخه آزمایشی یا واترمارک.", beginnerGuide: "نصب کنید، یک عکس را باز و با فیلترهای یک کلیکی منوی Colors شروع کنید. بقیه در حدود یک ساعت با آموزش‌های رسمی پوشش داده می‌شود." }, es: { tagline: "Editor de imágenes completo", description: "El programa de manipulación de imágenes de GNU es la alternativa gratuita a Photoshop: capas, máscaras, filtros, herramientas de retoque y un sistema de plugins programable.", whyItsAwesome: "Casi 30 años de desarrollo, abre archivos PSD de Photoshop, funciona en cualquier computadora y es gratis sin límites de prueba ni marcas de agua.", beginnerGuide: "Instálalo, abre una foto y empieza con los filtros de un clic en el menú Colores. Los tutoriales oficiales cubren lo demás en una hora aproximadamente." }, fr: { tagline: "Éditeur d'images complet", description: "Le GNU Image Manipulation Program est l'alternative gratuite à Photoshop : calques, masques, filtres, outils de retouche et système de plugins scriptable.", whyItsAwesome: "Presque 30 ans de développement, ouvre les fichiers Photoshop PSD, fonctionne sur n'importe quel ordinateur, et ne coûte rien, sans limite d'essai ni filigrane.", beginnerGuide: "Installez-le, ouvrez une photo, et commencez avec les filtres en un clic sous le menu Couleurs. Les tutoriels officiels couvrent le reste en environ une heure." }, de: { tagline: "Vollständiger Bildeditor", description: "Das GNU Image Manipulation Program ist die kostenlose Alternative zu Photoshop: Ebenen, Masken, Filter, Retusche-Werkzeuge und ein scriptbares Plugin-System.", whyItsAwesome: "Fast 30 Jahre Entwicklung, öffnet Photoshop-PSD-Dateien, läuft auf jedem Computer und kostet nichts ohne Testlimits oder Wasserzeichen.", beginnerGuide: "Installiere es, öffne ein Foto und beginne mit den Ein-Klick-Filtern im Menü Farben. Die offiziellen Tutorials erklären den Rest in etwa einer Stunde." } },
  'obs-studio': { fa: { tagline: "ضبط صفحه نمایش و استریم زنده", description: "ابزار استاندارد متن‌باز برای ضبط صفحه و استریم به توییچ، یوتیوب و هر سرویس RTMP، با ساخت صحنه، فیلتر و پلاگین.", whyItsAwesome: "ضبیلی نامحدود بدون واترمارک، پشتیبانی از کدگذاری سخت‌افزاری و اکوسیستم بزرگ پلاگین برای افزودن همه چیز از تل‌پرومپتر تا افکت‌ها.", beginnerGuide: "یک منبع Display Capture اضافه، روی Start Recording کلیک کنید. هر چیزی روی صفحه به MP4 ذخیره می‌شود. راه‌اندازی استریم با یک کلیک اتصال انجام می‌شود." }, es: { tagline: "Grabación de pantalla y streaming en vivo", description: "La herramienta estándar de código abierto para grabar tu pantalla y hacer streaming a Twitch, YouTube y cualquier servicio RTMP, con composición de escenas, filtros y plugins.", whyItsAwesome: "Grabación ilimitada sin marca de agua, soporte para codificación de hardware y un gran ecosistema de plugins que añade desde teleprompters hasta efectos.", beginnerGuide: "Añade una fuente de Captura de Pantalla, haz clic en Iniciar Grabación y todo lo que esté en pantalla se guarda en un MP4. La configuración de streaming toma un solo clic de conexión." }, fr: { tagline: "Enregistrement d'écran et streaming en direct", description: "L'outil open source standard pour enregistrer votre écran et diffuser sur Twitch, YouTube et tout service RTMP, avec composition de scènes, filtres et plugins.", whyItsAwesome: "Enregistrement illimité sans filigrane, support du matériel d'encodage, et un vaste écosystème de plugins qui ajoutent tout depuis les téléprompters jusqu'aux effets.", beginnerGuide: "Ajoutez une source Capture d'affichage, cliquez sur Démarrer l'enregistrement, et tout ce qui est à l'écran est sauvegardé en MP4. La configuration du streaming ne prend qu'un clic de connexion." }, de: { tagline: "Bildschirmaufnahme und Live-Streaming", description: "Das Standard-Open-Source-Tool zum Aufzeichnen deines Bildschirms und Streamen zu Twitch, YouTube und jedem RTMP-Dienst mit Szenenkomposition, Filtern und Plugins.", whyItsAwesome: "Unbegrenzte Aufnahme ohne Wasserzeichen, Hardware-Encoding-Unterstützung und ein riesiges Plugin-Ökosystem, das von Telepromptern bis Effekten alles hinzufügt.", beginnerGuide: "Füge eine Display Capture-Quelle hinzu, klicke Aufnahme starten und alles auf dem Bildschirm wird als MP4 gespeichert. Die Einrichtung des Streamings erfordert nur einen Klick auf die Verbindung." } },
  'thunderbird': { fa: { tagline: "کلاینت ایمیل و تقویم خصوصی", description: "اپلیکیشن کلاسیک ایمیل موزیلا: IMAP, POP, Exchange از طریق افزونه، تقویم، وظایف، رمزنگاری با OpenPGP و بدون هیچ تبلیغاتی در رابط کاربری.", whyItsAwesome: "ایمیل‌های شما روی دستگاه شما می‌ماند و برای تبلیغات استخراج نمی‌شوند. صندوق ورودی یکپارچه، جستجوی سریع و فیلترهای پیام که واقعاً کار می‌کنند.", beginnerGuide: "حساب ایمیل خود با آدرس و رمز معمولی اضافه کنید. تاندربرد معمولاً تنظیمات سرور را به صورت خودتشخیصی پیدا می‌کند." }, es: { tagline: "Cliente de correo y calendario privado", description: "La aplicación de correo clásica de Mozilla: IMAP, POP, Exchange a través de complemento, calendarios, tareas, cifrado con OpenPGP y sin anuncios en ninguna parte de la interfaz.", whyItsAwesome: "Tu correo se queda en tu máquina, no se explora para publicidad. Bandeja unificada, búsqueda rápida y filtros de mensaje que realmente funcionan.", beginnerGuide: "Añade tu cuenta de correo con tu dirección y contraseña habituales, y Thunderbird suele detectar la configuración del servidor automáticamente." }, fr: { tagline: "Client de messagerie et de calendrier privé", description: "L'application de messagerie classique de Mozilla : IMAP, POP, Exchange via module, calendriers, tâches, chiffrement avec OpenPGP, et aucune publicité dans l'interface.", whyItsAwesome: "Vos e-mails restent sur votre machine, pas exploités pour la publicité. Boîte de réception unifiée, recherche rapide et filtres de message qui fonctionnent vraiment.", beginnerGuide: "Ajoutez votre compte e-mail avec votre adresse et mot de passe habituels, et Thunderbird détecte généralement les paramètres du serveur automatiquement." }, de: { tagline: "Privater E-Mail- und Kalender-Client", description: "Mozilla's klassische E-Mail-Anwendung: IMAP, POP, Exchange über Add-on, Kalender, Aufgaben, Verschlüsselung mit OpenPGP und keine Werbung irgendwo in der Oberfläche.", whyItsAwesome: "Deine E-Mails bleiben auf deinem Rechner, werden nicht für Werbung ausgebeutet. Unified Inbox, schnelle Suche und Filter, die tatsächlich funktionieren.", beginnerGuide: "Füge deine E-Mail-Adresse mit deinem normalen Namen und Passwort hinzu, und Thunderbird erkennt in der Regel die Servereinstellungen automatisch." } },
  'qbittorrent': { fa: { tagline: "کلاینت BitTorrent تمیز", description: "محبوب‌ترین کلاینت رایگان تورنت: بدون تبلیغ، بدون نرم‌افزارهای اضافی، دانلود متوالی، پشتیبانی RSS، تب جستجوی داخلی و رابط وب.", whyItsAwesome: "ظاهر و عملکرد مانند یو تورنت قبل از تجاری شدن. سبک، شفاف و در تمام پلتفرم‌های دسکتاپ موجود است.", beginnerGuide: "نصب کنید، هر فایل .torrent یا لینک مگنت را باز کنید. دانلودها بلافاصله شروع می‌شوند. تب جستجو تورنت‌ها را از ترکرهای عمومی پیدا می‌کند." }, es: { tagline: "Cliente BitTorrent limpio", description: "El cliente torrent más popular: sin anuncios, sin software bundled, descarga secuencial, soporte para RSS, pestaña de búsqueda integrada e interfaz web.", whyItsAwesome: "Se ve y comporta como uTorrent antes de volverse comercial. Ligero, honesto y disponible en todas las plataformas de escritorio.", beginnerGuide: "Instálalo, abre cualquier archivo .torrent o enlace magnet y las descargas empiezan al instante. La pestaña de búsqueda encuentra torrents de trackers públicos." }, fr: { tagline: "Client BitTorrent propre", description: "Le client torrent gratuit le plus populaire : pas de publicité, pas de logiciels bundled, téléchargement séquentiel, support des flux RSS, onglet de recherche intégré et interface web.", whyItsAwesome: "Ressemble et se comporte comme uTorrent avant qu'il ne devienne commercial. Léger, honnête, et disponible sur toutes les plateformes de bureau.", beginnerGuide: "Installez-le, ouvrez n'importe quel fichier .torrent ou lien magnet, et les téléchargements commencent immédiatement. L'onglet de recherche trouve des torrents sur les trackers publics." }, de: { tagline: "Sauberer BitTorrent-Client", description: "Der beliebteste kostenlose Torrent-Client: keine Werbung, kein vorinstallierter Müll, sequenzielles Herunterladen, RSS-Feed-Unterstützung, eine eingebaute Suchleiste und eine Weboberfläche.", whyItsAwesome: "Sieht und verhält sich wie uTorrent vor seiner Kommerzialisierung. Leichtgewichtig, ehrlich und auf jeder Desktop-Plattform verfügbar.", beginnerGuide: "Installiere es, öffne eine beliebige .torrent-Datei oder Magnet-Link und die Downloads starten sofort. Die Suchleiste findet Torrents von öffentlichen Trackern." } },
  'signal': { fa: { tagline: "پیام‌رسانی و تماس خصوصی", description: "استاندارد طلایی پیام‌رسانی خصوصی: چت‌ها، تماس‌های صوتی و تصویری، گروه‌ها و پیام‌های ناپدیدشونده با رمزنگاری سرتاسری، اداره شده توسط یک بنیاد غیرانتفاعی.", whyItsAwesome: "پروتکل رمزنگاری متن‌باز است که واتس‌اپ هم از آن استفاده می‌کند، اما تقریبا هیچ اطلاعاتی از شما جمع‌آوری نمی‌کند. برای همیشه رایگان و با کمک‌های مالی اداره می‌شود.", beginnerGuide: "نصب کنید، با شماره تلفن ثبت‌نام کنید و دوستان را دعوت کنید. دقیقا مثل یک پیام‌رسانی معمولی کار می‌کند، فقط خصوصی است." }, es: { tagline: "Mensajes y llamadas privados", description: "El estándar de mensajería privada: chats, llamadas de voz y video, grupos y mensajes que desaparecen, con cifrado de extremo a extremo. Operado por una sin fines de lucro.", whyItsAwesome: "Su protocolo de cifrado es de código abierto y usa WhatsApp, pero Signal casi no recoge datos tuyos. Siempre gratis, financiado por donaciones.", beginnerGuide: "Instálalo, regístrate con tu número e invita a amigos. Funciona como un mensajero normal, solo que es privado." }, fr: { tagline: "Messages et appels privés", description: "Le standard de la messagerie privée : discussions, appels vocaux et vidéo, groupes et messages éphémères, chiffrés de bout en bout, géré par une à but non lucratif.", whyItsAwesome: "Le protocole de chiffrement est open source et utilisé par WhatsApp, mais Signal collecte presque aucune donnée sur vous. Gratuit à vie, financé par des dons.", beginnerGuide: "Installez-le, inscrivez-vous avec votre numéro de téléphone, et invitez des amis. Ça fonctionne comme un messager normal, juste en privé." }, de: { tagline: "Private Nachrichten und Anrufe", description: "Der Goldstandard für private Nachrichten: Ende-zu-Ende-verschlüsselte Chats, Sprach- und Videogespräche, Gruppen und verschwindende Nachrichten, betrieben von einer Non-Profit-Organisation.", whyItsAwesome: "Das Verschlüsselungsprotokoll ist Open Source und wird auch von WhatsApp genutzt, aber Signal sammelt fast nichts über dich. Kostenlos für immer, finanziert durch Spenden.", beginnerGuide: "Installiere es, registriere dich mit deiner Telefonnummer und lade Freunde ein. Es funktioniert genau wie ein normaler Messenger, nur privat." } },
  'tor-browser': { fa: { tagline: "مرورگر ناشناس و سانسورناپذیر", description: "یک نسخه تقویت‌شده فایرفاکس که ترافیک را از طریق شبکه Tor هدایت می‌کند تا وب‌سایت‌ها نشانی IP و موقعیت واقعی شما را نبینند.", whyItsAwesome: "با یک کلیک، ناشناسی قوی و دسترسی به وب آزاد پشت شبکه‌های سانسورشده را فراهم می‌کند. توسط یک بنیاد غیرانتفاعی با حسابرسی عمومی نگهداری می‌شود.", beginnerGuide: "نصب کنید، روی Connect بزنید و به طور عادی مرور کنید. خواندن نکات داخلی دو دقیقه طول می‌کشد و همه چیز مورد نیاز اکثر افراد را پوشش می‌دهد." }, es: { tagline: "Navegación anónima y resistente a la censura", description: "Una versión de Firefox endurecida que enruta el tráfico por la red Tor para que los sitios web no vean tu IP ni ubicación reales.", whyItsAwesome: "Un solo clic da fuerte anonimato y acceso a la web abierta detrás de redes censuradas. Mantenido por una sin fines de lucro con auditorías públicas.", beginnerGuide: "Instálalo, pulsa Conectar y navega normalmente. Leer los consejos integrados toma dos minutos y cubre lo que la mayoría necesita." }, fr: { tagline: "Navigation anonyme et contre la censure", description: "Une version de Firefox renforcée qui achemine le trafic via le réseau Tor, pour que les sites ne voient pas votre vraie adresse IP ou votre localisation.", whyItsAwesome: "Un seul clic pour une forte anonymat et l'accès au web libre derrière des réseaux censurés, maintenu par une à but non lucratif avec des audits publics.", beginnerGuide: "Installez, appuyez sur Connectez, et naviguez normalement. Lire les astuces intégrées prend deux minutes et couvre tout ce dont la plupart des gens ont besoin." }, de: { tagline: "Anonymes und zensursicheres Surfen", description: "Eine abgesicherte Firefox-Version, die den Verkehr über das Tor-Netzwerk leitet, sodass Webseiten deine echte IP-Adresse oder deinen Standort nicht sehen können.", whyItsAwesome: "Ein Klick gibt dir starke Anonymität und Zugang zum offenen Web hinter zensierten Netzwerken, gepflegt von einer Non-Profit-Organisation mit öffentlichen Audits.", beginnerGuide: "Installiere, drücke Verbinden und surfe normal. Die eingebauten Tipps in zwei Minuten zu lesen, deckt alles ab, was die meisten brauchen." } },
  'sumatra': { fa: { tagline: "خواننده PDF و کتاب الکترونیک کوچک و سریع", description: "یک خواننده سبک برای PDF، EPUB، MOBI، CHM، XPS، DjVu، CBZ و CBR که بلافاصله اجرا می‌شود و حافظه کمی مصرف می‌کند.", whyItsAwesome: "یک اجرای کوچک و قابل حمل. اسناد را قبل از اینکه خواننده‌های سنگین صفحه بارگذاری خود را نشان دهند، باز می‌کند.", beginnerGuide: "نصب کنید یا نسخه قابل حمل را دانلود کنید، روی هر PDF دوبار کلیک کنید و بلافاصله باز می‌شود. تنظیمات مزاحم شما نمی‌شوند." }, es: { tagline: "Lector ligero y rápido de PDF y ebooks", description: "Un lector minimalista para PDF, EPUB, MOBI, CHM, XPS, DjVu, CBZ y CBR que arranca al instante y usa poca memoria.", whyItsAwesome: "Veinte herramientas en un instalador, mantenido por Microsoft en GitHub. Cada una soluciona un problema real de Windows que nunca corrigió.", beginnerGuide: "Instálalo, pulsa Alt+Espacio para probar el lanzador y revisa la lista de módulos. Habilita solo las herramientas que quieras." }, fr: { tagline: "Lecteur PDF et ebooks léger et rapide", description: "Un lecteur plume pour PDF, EPUB, MOBI, CHM, XPS, DjVu, CBZ et CBR qui démarre instantanément et consomme peu de mémoire.", whyItsAwesome: "Un seul petit exécutable, disponible aussi en version portable. Ouvre les documents avant que les lecteurs plus lourds aient fini de charger leurs écrans de démarrage.", beginnerGuide: "Installez ou téléchargez l'exécutable portable, double-cliquez sur un PDF, et il s'ouvre instantanément. Les paramètres restent discrets." }, de: { tagline: "Kleiner, schneller PDF- und E-Book-Reader", description: "Ein federleichter Reader für PDF, EPUB, MOBI, CHM, XPS, DjVu, CBZ und CBR, der sofort startet und wenig Speicher verbraucht.", whyItsAwesome: "Eine einzige kleine ausführbare Datei, auch als portable Version verfügbar. Öffnet Dokumente, bevor schwerere Reader ihre Startbildschirme geladen haben.", beginnerGuide: "Installiere oder lade die portable exe herunter, doppelklicke eine beliebige PDF-Datei und sie öffnet sich sofort. Einstellungen bleiben dir aus dem Weg." } },
  'powertoys': { fa: { tagline: "ابزارهای پیشرفته برای ویندوز", description: "جعبه‌ابزار متن‌باز رسمی مایکروسافت: چیدمان پنجره‌های FancyZones، PowerRename، انتخابگر رنگ، استخراج متن از تصاویر، بازنمایی کلید و بیشتر.", whyItsAwesome: "بیست ابزار در یک نصب، توسط مایکروسافت روی GitHub نگهداری می‌شود. هر کدام یک مشکل واقعی را که ویندوز هرگز برطرف نکرد، حل می‌کند.", beginnerGuide: "نصب کنید، Alt+Space را بزنید تا لانчер را امتحان کنید و لیست ماژول‌ها را نگاه کنید. فقط ابزارهایی را که می‌خواهید فعال کنید." }, es: { tagline: "Utilidades para usuarios avanzados de Windows", description: "El kit de herramientas oficial de Microsoft: diseños de ventanas FancyZones, PowerRename, selector de color, extracción de texto de imágenes, reasignación de teclas y más.", whyItsAwesome: "Veinte herramientas en un solo instalador, mantenidas por Microsoft en GitHub. Cada una soluciona un problema real de Windows que nunca se corrigió.", beginnerGuide: "Instálalo, presiona Alt+Espacio para probar el lanzador y revisa la lista de módulos. Habilita solo las herramientas que necesites." }, fr: { tagline: "Utilitaires pour utilisateurs avancés sur Windows", description: "La boîte à outils officielle open source de Microsoft : agencements de fenêtres FancyZones, PowerRename, un pipette de couleur, extraction de texte d'images, remappage de touches, et plus.", whyItsAwesome: "Vingt outils dans un seul installeur, maintenu par Microsoft sur GitHub. Chacun résout un vrai défaut de Windows.", beginnerGuide: "Installez-le, appuyez sur Alt+Espace pour essayer le lanceur, et parcourez la liste des modules. Activez seulement les outils que vous voulez." }, de: { tagline: "Werkzeuge für Windows-Profis", description: "Microsofts offizielle Open-Source-Toolbox: FancyZones für Fensteranordnungen, PowerRename, ein Farbwähler, Textextraktion aus Bildern, Tastaturbelegung und mehr.", whyItsAwesome: "Zwanzig Werkzeuge in einem Installer, gepflegt von Microsoft auf GitHub. Jedes löst ein echtes Problem, das Windows nie behoben hat.", beginnerGuide: "Installiere es, drücke Alt+Leertaste, um den Launcher auszuprobieren, und blättere durch die Modulliste. Aktiviere nur die Werkzeuge, die du brauchst." } },
  'calibre': { fa: { tagline: "مدیریت کامل کتاب الکترونیک", description: "کتابخانه کتاب‌های الکترونیک خود را سازماندهی، تبدیل و منتقل کنید: هر فرماتی را وارد و خارج می‌کند، متادیتا و جلد را دانلود می‌کند، خواننده و ویرایشگر داخلی دارد.", whyItsAwesome: "بین فرمت‌های EPUB، MOBI، AZW3، PDF و بیشتر را با یک کلیک تبدیل می‌کند و کتاب‌ها را مستقیما به Kindle یا Kobo شما از طریق USB یا ایمیل ارسال می‌کند.", beginnerGuide: "آن را به پوشه‌ای از کتاب‌های الکترونیک اشاره دهید، کتاب‌ها را انتخاب کنید و از Convert یا Send to device استفاده کنید. رابط متراکم است اما هر دکمه مستند شده است." }, es: { tagline: "El gestor completo de ebooks", description: "Organiza, convierte y transfiere tu biblioteca de ebooks: todos los formatos de entrada y salida, descarga de metadatos y portadas, lector y editor integrados.", whyItsAwesome: "Convierte entre EPUB, MOBI, AZW3, PDF y más en un clic, y envía libros directamente a tu Kindle o Kobo por USB o email.", beginnerGuide: "Indícale una carpeta de ebooks, selecciona los libros y usa Convertir o Enviar a dispositivo. La interfaz es densa pero cada botón está documentado." }, fr: { tagline: "Le gestionnaire complet d'ebooks", description: "Organisez, convertissez et transférez votre bibliothèque d'ebooks : tous les formats en entrée et sortie, métadonnées et téléchargements de couvertures, un lecteur intégré et un éditeur d'ebooks.", whyItsAwesome: "Convertit entre EPUB, MOBI, AZW3, PDF et plus en un clic, et envoie les livres directement à votre Kindle ou Kobo par USB ou email.", beginnerGuide: "Pointez-le vers un dossier d'ebooks, sélectionnez-les, et utilisez Convertir ou Envoyer vers l'appareil. L'interface est dense mais chaque bouton est documenté." }, de: { tagline: "Der vollständige E-Book-Manager", description: "Organisiere, konvertiere und übertrage deine E-Book-Bibliothek: jedes Format hin und her, Metadaten- und Cover-Downloads, ein eingebauter Reader und ein E-Book-Editor.", whyItsAwesome: "Konvertiert mit einem Klick zwischen EPUB, MOBI, AZW3, PDF und mehr und schickt Bücher direkt an deinen Kindle oder Kobo per USB oder E-Mail.", beginnerGuide: "Wähle einen Ordner mit E-Books aus, markiere die Bücher und nutze Konvertieren oder an Gerät senden. Die Oberfläche ist dicht, aber jeder Knopf ist dokumentiert." } },
  'kdenlive': { fa: { tagline: "ویرایشگر ویدیوی چندمسیره", description: "ویرایشگر ویدیوی جدول‌محور جدی از KDE: مسیرهای نامحدود، افکت‌ها، گذارها، ویرایش پروکسی برای لپ‌تاپ و خروجی با شتاب‌سخت‌افزاری.", whyItsAwesome: "شکاف بین ویرایشگرهای ساده و سوئیت‌های گران‌قیمت را پر می‌کند. پروژه‌ها همیشه باز و رایگان می‌مانند و موتور MLT تقریبا هر فرماتی را مدیریت می‌کند.", beginnerGuide: "کلپ‌ها را وارد کنید، روی خط زمانه بکشید، با ابزار تیغه ببرید و با یک از پیش‌تعیین‌شده خروجی بگیرید. KDE یک راهنمای کامل مبتدیان را به صورت آنلاین ارائه می‌دهد." }, es: { tagline: "Editor de video con múltiples pistas", description: "Un editor de video serio, basado en línea de tiempo: pistas ilimitadas, efectos, transiciones, edición por proxy para portátiles y exportación con aceleración de hardware.", whyItsAwesome: "Llena el hueco entre editores sencillos y suites caras. Los proyectos son gratuitos y abiertos, y el motor MLT maneja casi cualquier formato.", beginnerGuide: "Importa clips, arrástralos a la línea de tiempo, corta con la herramienta de afeitar y exporta con un preestablecido. KDE ofrece un manual completo para principiantes en línea." }, fr: { tagline: "Monteur vidéo multi-pistes", description: "Un monteur vidéo sérieux à base de timeline de KDE : pistes illimitées, effets, transitions, édition proxy pour ordinateurs portables, et export accéléré matériellement.", whyItsAwesome: "Remplit le vide entre les monteurs d'amateurs et les suites chères. Les projets restent ouverts et gratuits, et le moteur MLT gère presque tous les formats.", beginnerGuide: "Importez des clips, glissez-les sur la timeline, coupez avec l'outil rasoir, et exportez avec un préréglage. KDE fournit un manuel complet pour débutants en ligne." }, de: { tagline: "Multispur-Videobearbeitungsprogramm", description: "Ein ernstzunehmender, zeitbasierten Videobearbeiter von KDE: unbegrenzte Spuren, Effekte, Übergänge, Proxy-Bearbeitung für Laptops und hardwarebeschleunigtes Exportieren.", whyItsAwesome: "Füllt die Lücke zwischen einfachen Editoren und teuren Suiten. Projekte bleiben offen und kostenlos, und die MLT-Engine verarbeitet fast jedes Format.", beginnerGuide: "Importiere Clips, ziehe sie auf die Zeitachne, schneide mit dem Rasierwerkzeug und exportiere mit einer Voreinstellung. KDE liefert ein vollständiges Anfängerhandbuch online." } },
  'balenaetcher': { fa: { tagline: "فلش کردن ایمن تصویر USB", description: "تصاویر ISO را روی درایوهای USB بدون ترس بنویسید: تصویر را انتخاب کنید، درایو را انتخاب کنید، فلش کنید. هر بار نوشته را تأیید می‌کند و از لمس دیسک سیستم شما خودداری می‌کند.", whyItsAwesome: "ایمن‌ترین راه برای ساخت USBهای بوت‌شدن لینوکس یا بازیابی، با رابط سه مرحله‌ای که هر کسی می‌تواند اولین بار دنبال کند.", beginnerGuide: "بازش کنید، ISO دانلودشده را انتخاب کنید، یک فلش USB بزنید، روی Flash کلیک کنید. تا تأیید سبز منتظر بمانید." }, es: { tagline: "Grabación segura de imágenes USB", description: "Escribe imágenes ISO a USB sin miedo: selecciona la imagen, selecciona la unidad y graba. Verifica cada escritura y no toca tu disco del sistema.", whyItsAwesome: "La forma más segura de crear USB de arranque de Linux o recuperación, con una interfaz de tres pasos que cualquiera puede seguir a la primera.", beginnerGuide: "Abrelo, selecciona tu ISO descargada, inserta una memoria USB y haz clic en Grabar. Espera a la marca de verificación verde." }, fr: { tagline: "Gravure d'images USB en toute sécurité", description: "Écrivez des images ISO sur des clés USB sans risque : choisissez l'image, choisissez le lecteur, gravez. Il valide chaque écriture et refuse de toucher votre disque système.", whyItsAwesome: "La méthode la plus sûre pour créer des clés USB amorçables Linux ou de récupération, avec une interface en trois étapes que tout le peut suivre dès la première fois.", beginnerGuide: "Ouvrez-le, sélectionnez votre ISO téléchargé, insérez une clé USB, cliquez sur Graver. Attendez la coche verte de vérification." }, de: { tagline: "Sicheres Schreiben von USB-Images", description: "Schreibe ISO-Images auf USB-Laufwerke ohne Sorgen: wähle das Image, wähle das Laufwerk, flashen. Es überprüft jeden Schreibvorgang und berührt niemals deine Systemfestplatte.", whyItsAwesome: "Der sicherste Weg, bootfähige Linux- oder Wiederherstellungs-USB-Sticks zu erstellen, mit einer Drei-Schritt-Oberfläche, die jeder beim ersten Versuch versteht.", beginnerGuide: "Öffne es, wähle dein heruntergeladenes ISO, stecke einen USB-Stick ein und klicke Flash. Warte auf den grünen Verifizierungs-Haken." } },
  'zotero': { fa: { tagline: "مدیریت پژوهش و منابع", description: "مقالات، وب‌سایت‌ها و کتاب‌ها را با یک کلیک در مرورگر جمع‌آوری کنید؛ آن‌ها را در مجموعه‌ها سازماندهی کنید؛ و ارجاع‌ها و bibliographies در ۱۰۰۰۰+ سبک تولید کنید.", whyItsAwesome: "رایگان و متن‌باز در حالی که EndNote صدها دلار هزینه دارد. افزونه‌های Word، LibreOffice و Google Docs ارجاعات با فرمت‌بندی ایده‌آل را هنگام نوشتن درج می‌کنند.", beginnerGuide: "Zotero و افزونه مرورگر را نصب کنید، روی دکمه ذخیره در هر صفحه مقاله کلیک کنید، سپس ارجاعات را از پردازشگر کلمات خود درج کنید." }, es: { tagline: "Gestor de investigación y referencias", description: "Recopila artículos, sitios web y libros con un clic en el navegador; organízalos en colecciones; y genera citas y bibliografías en más de 10 000 estilos.", whyItsAwesome: "Gratis y de código abierto, donde EndNote cuesta cientos. Los complementos para Word, LibreOffice y Google Docs insertan citas perfectamente formateadas mientras escribes.", beginnerGuide: "Instala Zotero más el conector del navegador, haz clic en el botón de guardar en cualquier página de artículo, luego inserta citas desde tu procesador de texto." }, fr: { tagline: "Gestionnaire de recherche et de références", description: "Rassemblez des articles, sites web et livres en un clic de navigateur ; organisez-les en collections ; et générez des citations et bibliographies dans 10 000+ styles.", whyItsAwesome: "Gratuit et open source là où EndNote coûte des centaines. Les extensions pour Word, LibreOffice et Google Docs insèrent des citations parfaitement formatées pendant que vous écrivez.", beginnerGuide: "Installez Zotero et l'extension de navigateur, cliquez sur le bouton Enregistrer sur la page d'un article, puis insérez des citations depuis votre traitement de texte." }, de: { tagline: "Manager für Forschung und Zitate", description: "Sammle mit einem Klick im Browser wissenschaftliche Artikel, Webseiten und Bücher; ordne sie in Sammlungen; und erzeuge Zitate und Bibliografien in über 10.000 Stilen.", whyItsAwesome: "Kostenlos und Open Source, wo EndNote hunderte kostet. Plugins für Word, LibreOffice und Google Docs fügen perfekt formatierte Zitate beim Schreiben ein.", beginnerGuide: "Installiere Zotero plus den Browser-Connector, klicke den Speichern-Knopf auf einer Artikelseite, füge dann Zitate aus deinem Textverarbeitungsprogramm ein." } },
  'jitsi-meet': { fa: { tagline: "تماس‌های ویدیویی بدون حساب کاربری", description: "شروع یا پیوستن به کنفرانس‌های ویدیویی رمزگذاری‌شده در مرورگر بدون نیاز به حساب یا نصب کلاینت. شامل اشتراک‌گذاری صفحه، چت و ضبط مکالمه است.", whyItsAwesome: "یک لینک را به اشتراک بگذارید، فوراً صحبت کنید. حتی می‌توانید سرور را خود میزبان باشید تا کنترل کامل داشته باشید، کاری که.zoom هرگز ارائه نمی‌دهد.", beginnerGuide: "به meet.jit.si بروید، یک نام اتاق را تایپ کنید و لینک را به مهمانان ارسال کنید. با یک کلیک در مرورگر به اتاق می‌پیوندند." }, es: { tagline: "Videoconferencias sin cuenta", description: "Inicia o únete a videoconferencias cifradas en el navegador, sin cuenta ni cliente instalado. Incluye compartir pantalla, chat y grabaciones.", whyItsAwesome: "Comparte un enlace y habla al instante. Puedes alojar tu propio servidor para tener control total, algo que Zoom nunca ofrecerá.", beginnerGuide: "Abre meet.jit.si, escribe un nombre de sala y envía el enlace a tus invitados. Se unen con un clic desde su navegador." }, fr: { tagline: "Appels vidéo sans compte", description: "Lancez ou rejoignez des conférences vidéo chiffrées directement dans votre navigateur, sans inscription ni client à installer. Partage d'écran, chat et enregistrements inclus.", whyItsAwesome: "Partagez un lien, parlez instantanément. Vous pouvez même auto-héberger le serveur pour un contrôle total, ce que Zoom ne proposera jamais.", beginnerGuide: "Ouvrez meet.jit.si, tapez un nom de salon, et envoyez le lien à vos invités. Ils rejoignent depuis leur navigateur en un clic." }, de: { tagline: "Videocalls ohne Konto", description: "Starte oder trete verschlüsselte Videokonferenzen im Browser bei, ohne Konto oder installierte Software. Teile deinen Bildschirm, chatte und nimm auf.", whyItsAwesome: "Teile einen Link und sofort kannst du reden. Du kannst den Server sogar selbst hosten für volle Kontrolle, was Zoom nie bieten wird.", beginnerGuide: "Öffne meet.jit.si, gib einen Raumnamen ein und schicke den Link an deine Gäste. Klicken sie einmal im Browser, sind sie dabei." } },
  'f-droid': { fa: { tagline: "فروشگاه اپ‌های متن‌باز برای اندروید", description: "یک کاتالوگ مستقل از اپ‌های رایگان و متن‌باز اندروید. هر اپ از سورس ساخته و توسط F-Droid امضا شده و نیازی به حساب گوگل ندارد.", whyItsAwesome: "ایمن‌ترین منبع برای فایل‌های APK خارج از گوگل پلی، و محل ابزارهای اندرویدی که سیاست‌های فروشگاه پلی آن‌ها را رد می‌کند. پشتیبانی از به‌روزرسانی داخلی دارد.", beginnerGuide: "فایل APK F-Droid را از f-droid.org دانلود کنید، هنگام درخواست نصب از مرورگر را بپذیرید، سپس اپ‌ها را مانند هر فروشگاهی مرور و نصب کنید." }, es: { tagline: "Tienda de apps de código abierto para Android", description: "Un catálogo independiente de apps gratuitas y de código abierto para Android. Cada app se compila desde el código y es firmada por F-Droid, sin cuenta de Google.", whyItsAwesome: "La fuente más segura de APKs fuera de Google Play y el hogar de herramientas de Android que las políticas de la Play Store excluyen. Lleva un seguimiento de actualizaciones.", beginnerGuide: "Descarga el APK de F-Droid desde f-droid.org, permite la instalación desde tu navegador cuando se solicite, luego explora e instala apps como en cualquier tienda." }, fr: { tagline: "Le magasin d'applications open source pour Android", description: "Un catalogue indépendant d'applications Android gratuites et open source. Chaque application est compilée à partir du code source et signée par F-Droid, sans besoin de compte Google.", whyItsAwesome: "La source la plus sûre pour les APK en dehors du Google Play, et la maison des outils Android exclus par les politiques du Play Store. Le suivi des mises à jour est intégré.", beginnerGuide: "Téléchargez le F-Droid APK depuis f-droid.org, autorisez l'installation depuis votre navigateur lorsque demandé, puis parcourez et installez les applications comme dans n'importe quelle boutique." }, de: { tagline: "Der Open-Source-App-Store für Android", description: "Ein unabhängiger Katalog kostenloser und quelloffener Android-Apps. Jede App wird aus dem Quellcode gebaut und von F-Droid signiert, kein Google-Konto nötig.", whyItsAwesome: "Die sicherste Quelle für APKs außerhalb des Google Play Store und Heimat für Android-Tools, die der Play Store ausschließt. Hat eingebaute Update-Prüfung.", beginnerGuide: "Lade die F-Droid APK von f-droid.org herunter, erlaube die Installation aus dem Browser wenn gefragt, und durchsuche und installiere Apps wie in jedem Store." } },
  'immich': { fa: { tagline: "جایگزین خودمیزبان گوگل فوتوز", description: "یک سرویس پشتیبان‌گیری از عکس و ویدیوی شخصی: آپلود خودکار گوشی، زمان‌سنج، جستجوی چهره و اشیاء، آلبوم‌ها و اشتراک‌گذاری، همه روی سخت‌افزار خودتان.", whyItsAwesome: "پروژه خودمیزبان با رشد سریع در سال‌های اخیر. اپ‌های موبایل شبیه گوگل فوتوز هستند، اما داده‌ها هرگز از دستگاه یا سرور شما خارج نمی‌شوند.", beginnerGuide: "اسکریپت نصب را روی هر کامپیوتر همیشه‌روشن با داکر اجرا کنید، اپ موبایل را نصب کنید، آن را به آدرس سرور خود اشاره دهید و پشتیبان‌گیری را فعال کنید." }, es: { tagline: "Alternativa autoalojada a Google Photos", description: "Ejecuta tu propio servicio de respaldo de fotos y vídeos: carga automática desde el móvil, cronología, búsqueda por rostro y objeto, álbumes y compartir, todo en tu propio hardware.", whyItsAwesome: "El proyecto autoalojado de más rápido crecimiento en años. Las apps móviles se sienten como Google Photos, pero los datos nunca abandonan tu máquina o servidor.", beginnerGuide: "Ejecuta el script de instalación en cualquier ordenador siempre encendido con Docker, instala la app móvil, apúntala a la dirección de tu servidor y activa el respaldo." }, fr: { tagline: "Alternative auto-hébergée à Google Photos", description: "Gérez votre propre service de sauvegarde de photos et de vidéos : téléversement automatique depuis votre téléphone, chronologie, recherche par visage et par objet, albums et partage, le tout sur votre propre matériel.", whyItsAwesome: "Le projet auto-hébergé en plus forte croissance ces dernières années. Les applications mobiles ressemblent à Google Photos, mais vos données ne quittent jamais votre machine ou serveur.", beginnerGuide: "Exécutez le script d'installation sur un ordinateur toujours allumé avec Docker, installez l'application mobile, indiquez l'adresse de votre serveur et activez la sauvegarde." }, de: { tagline: "Selbst gehostete Google-Photos-Alternative", description: "Betriebe deinen eigenen Foto- und Videobackup-Service: automatische Handy-Uploads, Zeitleiste, Suche nach Gesichtern und Objekten, Alben und Freigaben, alles auf deiner eigenen Hardware.", whyItsAwesome: "Das am schnellsten wachsende selbst gehostete Projekt der letzten Jahre. Die Mobile-Apps fühlen sich wie Google Photos an, aber deine Daten verlassen nie deinen Rechner oder Server.", beginnerGuide: "Führe das Installations-Skript auf einem immer eingeschalteten PC mit Docker aus, installiere die Mobile-App, verbinde sie mit deiner Server-Adresse und aktiviere den Backup." } },
  'nextcloud': { fa: { tagline: "ابر همگام‌سازی و همکاری خودتان", description: "بلوغ‌ترین پلتفرم میزبانی شده برای همگام‌سازی فایل، اشتراک‌گذاری، تقویم، مخاطبان، یادداشت‌ها و همکاری دفتری، با اپلیکیشن برای هر دستگاه.", whyItsAwesome: "جایگزین مستقیم Dropbox و Google Drive که سازمان‌ها و دولت‌ها واقعاً از آن استفاده می‌کنند. هزاران اپلیکیشن جامعه آن را گسترش داده‌اند.", beginnerGuide: "از نصب‌کننده رسمی Docker AIO یا یک میزبان مدیریت شده استفاده کنید، یک حساب ادمین بسازید، سپس اپ‌های همگام‌سازی دسکتاپ و موبایل را نصب کنید." }, es: { tagline: "Tu propia nube para archivos y colaboración", description: "La plataforma autoalojada más madura para sincronización de archivos, compartir, calendarios, contactos, notas y colaboración de oficina, con apps para todo dispositivo.", whyItsAwesome: "Sustituto directo de Dropbox y Google Drive que usan organizaciones y gobiernos. Miles de apps de la comunidad la extienden.", beginnerGuide: "Usa el instalador oficial AIO de Docker o un alojamiento gestionado, crea una cuenta de admin, e instala las apps de escritorio y móvil para sincronizar." }, fr: { tagline: "Votre propre cloud pour synchronisation et collaboration", description: "La plateforme auto-hébergée la plus mûre pour la synchronisation de fichiers, le partage, les calendriers, les contacts, les notes et la bureautique, avec des applications pour chaque appareil.", whyItsAwesome: "Un remplacement direct pour Dropbox et Google Drive que les organisations et gouvernements utilisent réellement. Des milliers d'applications communautaires l'étendent.", beginnerGuide: "Utilisez l'installateur Docker AIO officiel ou un hébergement géré, créez un compte administrateur, puis installez les applications de synchronisation pour le bureau et le téléphone." }, de: { tagline: "Deine eigene Cloud für Dateien & Teamarbeit", description: "Das ausgereifteste selbst gehostete System für Dateisync, Sharing, Kalender, Kontakte, Notizen und Office-Zusammenarbeit, mit Apps für jedes Gerät.", whyItsAwesome: "Drop-in-Ersatz für Dropbox und Google Drive, den Organisationen und Regierungen tatsächlich nutzen. Tausende Community-Apps erweitern es.", beginnerGuide: "Nutze den offiziellen AIO Docker Installer oder einen Managed Host, erstelle einen Admin-Account und installiere die Desktop- und Phone-Sync-Apps." } },
  'home-assistant': { fa: { tagline: "کنترل هوشمند خانه به صورت محلی", description: "هر چراغ هوشمند، سنسور، ترموستات و دوربین را تحت یک داشبورد محلی واحد مدیریت کنید که حتی وقتی اینترنت شما کار نمی‌کند، همچنان فعال است.", whyItsAwesome: "از دستگاه‌های بیشتری از هر هاب تجاری پشتیبانی می‌کند، روی یک Raspberry Pi اجرا می‌شود و داده‌های دستگاه شما را به کسی ارسال نمی‌کند. جامعه بزرگ اتوماسیون دارد.", beginnerGuide: "Home Assistant OS را با balenaEtcher روی Raspberry Pi فلش کنید، راه‌اندازی وب را باز کنید و دستگاه‌های شما به طور خودکار کشف می‌شوند." }, es: { tagline: "Control de domótica local", description: "Controla desde un tablero local todas tus luces inteligentes, sensores, termostatos y cámaras. Sigue funcionando aunque tu internet falle.", whyItsAwesome: "Soporta más dispositivos que cualquier hub comercial, corre en una Raspberry Pi y no envía tus datos a nadie. Gran comunidad de automatización.", beginnerGuide: "Instala Home Assistant OS en una Raspberry Pi con balenaEtcher, abre la configuración web y descubrirá tus dispositivos automáticamente." }, fr: { tagline: "Contrôle local de la maison connectée", description: "Rassemblez toutes vos lumières intelligentes, capteurs, thermostats et caméras sur un tableau de bord local qui continue de fonctionner même sans Internet.", whyItsAwesome: "Prend en charge plus d'appareils que n'importe quel hub commercial, fonctionne sur un Raspberry Pi, et n'envoie vos données d'appareils à personne. Une grande communauté d'automatisation.", beginnerGuide: "Flashez Home Assistant OS sur un Raspberry Pi avec balenaEtcher, ouvrez la configuration web, et il détecte automatiquement vos appareils." }, de: { tagline: "Lokale Smart-Home-Steuerung", description: "Bringe alle Smart-Lichter, Sensoren, Thermostate und Kameras unter ein lokales Dashboard, das auch ohne Internet funktioniert.", whyItsAwesome: "Unterstützt mehr Geräte als jeder kommerzielle Hub, läuft auf einem Raspberry Pi und schickt deine Gerätedaten an niemanden. Große Automatisierungs-Community.", beginnerGuide: "Flashe Home Assistant OS auf einen Raspberry Pi mit balenaEtcher, öffne die Web-Einrichtung und es findet deine Geräte automatisch." } },
  'pi-hole': { fa: { tagline: "مسدودسازی تبلیغات در کل شبکه", description: "یک سینک DNS که تبلیغات و ردیاب‌ها را برای تمام دستگاه‌های شبکه شما، از جمله گوشی‌ها، تلویزیون‌ها و گجت‌هایی که از مسدودکننده‌های تبلیغات مرورچی چشم‌پوشی می‌کنند، مسدود می‌کند.", whyItsAwesome: "یک بار روی Raspberry Pi یا هر جعبه‌ای همیشه روشن نصب کنید و هر دستگاه مرور تمیزتر و سریع‌تر با صفر تنظیمات برای هر دستگاه خواهد داشت.", beginnerGuide: "تصویر را روی Raspberry Pi فلش کنید، DNS روتر خود را به آن اشاره دهید و داشبورد تعداد درخواست‌های مسدود شده را بشمارید." }, es: { tagline: "Bloqueo de anuncios en toda la red", description: "Un sumidero de DNS que bloquea anuncios y rastreadores para todos los dispositivos de tu red, incluyendo móviles, TVs y gadgets que ignoran los bloqueadores de navegador.", whyItsAwesome: "Instálalo una vez en una Raspberry Pi o cualquier dispositivo siempre encendido y todos tus dispositivos tendrán una navegación más limpia y rápida, sin configuración por dispositivo.", beginnerGuide: "Instala la imagen en una Raspberry Pi, apunta el DNS de tu router a ella y observa en el tablero las peticiones bloqueadas." }, fr: { tagline: "Blocage publicitaire sur tout le réseau", description: "Un puits DNS qui bloque les publicités et les traqueurs pour tous les appareils de votre réseau, y compris les téléphones, les téléviseurs et les gadgets qui ignorent les bloqueurs de publicités de navigateur.", whyItsAwesome: "Installez une fois sur un Raspberry Pi ou n'importe quelle boîte toujours allumée, et chaque appareil bénéficie d'un navigation plus propre et plus rapide sans configuration par appareil.", beginnerGuide: "Flashez l'image sur un Raspberry Pi, pointez le DNS de votre routeur dessus, et regardez le tableau de bord compter les requêtes bloquées." }, de: { tagline: "Netzwerkweiter Werbeblocker", description: "Ein DNS-Sinkhole, das Werbung und Tracker für alle Geräte in deinem Netz blockiert, auch auf Handys, TVs und Geräten, die Browser-Blocker ignorieren.", whyItsAwesome: "Installiere es einmal auf einem Raspberry Pi oder einem immer-an-Server und jedes Gerät bekommt sauberes, schnelles Surfen ohne zusätzliche Einrichtung pro Gerät.", beginnerGuide: "Flashe das Image auf einen Raspberry Pi, weise deinem Router die IP dieses Pi-holes als DNS zu und schau auf dem Dashboard, wie viele Anfragen blockiert werden." } },
  'searxng': { fa: { tagline: "موتور جستجوی متادیتای خصوصی", description: "در ده‌ها موتور جستجو به طور همزمان جستجو کنید بدون اینکه ردیابی شوید: هیچ کوکی، لاگ یا پروفایلی، و نتایج از گوگل، بینگ، DuckDuckGo و دیگرها جمع‌آوری شده است.", whyItsAwesome: "فوراً از نمونه‌های عمومی متعدد استفاده کنید یا نمونه خصوصی خود را میزبانی کنید. این پاسخ حریم خصوصی به نظارت موتورهای جستجو است.", beginnerGuide: "searx.be یا هر نمونه عمومی را باز کنید و جستجو کنید. برای میزبانی خصوصی، یک کانتینر Docker یک نمونه خصوصی به شما می‌دهد." }, es: { tagline: "Metabuscador privado", description: "Busca en docenas de motores a la vez sin ser rastreado: sin cookies, sin registros, sin perfiles y los resultados se agregan de Google, Bing, DuckDuckGo y más.", whyItsAwesome: "Usa las muchas instancias públicas al instante o aloja la tuya. Es la respuesta a la vigilancia de los motores de búsqueda.", beginnerGuide: "Abre searx.be o cualquier instancia pública y busca. Para alojarlo, un contenedor Docker te da una instancia privada." }, fr: { tagline: "Moteur de métarecherche privé", description: "Recherchez sur des dizaines de moteurs à la fois sans être suivi : pas de cookies, pas de journaux, pas de profilage, et les résultats sont agrégés à partir de Google, Bing, DuckDuckGo, etc.", whyItsAwesome: "Utilisez instantanément les nombreuses instances publiques ou auto-hébergez la vôtre. C'est la réponse à la surveillance par les moteurs de recherche.", beginnerGuide: "Ouvrez searx.be ou n'importe quelle instance publique et cherchez. Pour auto-héberger, un seul conteneur Docker vous donne une instance privée." }, de: { tagline: "Private Metasuchmaschine", description: "Suche gleichzeitig Dutzende Suchmaschinen ohne verfolgt zu werden: keine Cookies, keine Protokolle, kein Profiling, Ergebnisse werden von Google, Bing, DuckDuckGo und mehr aggregiert.", whyItsAwesome: "Nutze die vielen öffentlichen Instanzen sofort oder hoste deine eigene. Es ist die Antwort auf die Überwachung durch Suchmaschinen.", beginnerGuide: "Öffne searx.be oder eine andere öffentliche Instanz und suche. Zum Selbhosten reicht ein einzelner Docker-Container für eine private Instanz." } },
  'vaultwarden': { fa: { tagline: "سرور Bitwarden خود میزبان", description: "یک سرور سبک Bitwarden-سازگار که می‌توانید آن را هرجا اجرا کنید. از اپ‌ها و اکستنشن‌های رسمی Bitwarden استفاده کنید، ولی گاوصندوق خود را روی سخت‌افزار شخصی خود نگه دارید.", whyItsAwesome: "خوشحال روی یک VPS کوچک یا Raspberry Pi اجرا می‌شود، ورود دو مرحله‌ای و کلیدهای عبور را پشتیبانی می‌کند و هیچ هزینه‌ای جز سرور خودتان ندارد.", beginnerGuide: "ایمج Docker را مستقر کنید، یک دامنه و HTTPS تنظیم کنید، سپس از اپ Bitwarden با آدرس سرور خود وارد شوید." }, es: { tagline: "Servidor autoalojado de Bitwarden", description: "Un servidor ligero y compatible con Bitwarden que puedes ejecutar en cualquier sitio. Usa las apps y extensiones oficiales de Bitwarden, pero la bóveda queda en tu hardware.", whyItsAwesome: "Funciona perfectamente en una VPS pequeña o una Raspberry Pi, soporta inicio de sesión de dos factores y claves de acceso y no cuesta más allá de tu servidor.", beginnerGuide: "Implementa la imagen Docker, establece un dominio y HTTPS, luego inicia sesión desde la app de Bitwarden con la URL de tu servidor." }, fr: { tagline: "Serveur Bitwarden auto-hébergé", description: "Un serveur compatible Bitwarden léger que vous pouvez exécuter n'importe où. Utilisez les applications et extensions officielles Bitwarden, mais gardez le coffre-fort sur votre propre matériel.", whyItsAwesome: "Fonctionne parfaitement sur un petit VPS ou un Raspberry Pi, prend en charge la connexion à deux facteurs et les passkeys, et ne coûte rien au-delà de votre propre serveur.", beginnerGuide: "Déployez l'image Docker, définissez un domaine et HTTPS, puis connectez-vous depuis l'application Bitwarden avec l'URL de votre serveur." }, de: { tagline: "Selbst gehosteter Bitwarden-Server", description: "Ein leichtgewichtiger, Bitwarden-kompatibler Server, den du überall ausführen kannst. Nutze die offiziellen Bitwarden-Apps, aber der Tresor bleibt auf deiner Hardware.", whyItsAwesome: "Läuft problemlos auf einem kleinen VPS oder Raspberry Pi, unterstützt 2FA und Passkeys und kostet nichts außer deinem eigenen Server.", beginnerGuide: "Deploy das Docker Image, setze eine Domain und HTTPS, und logge dich in der Bitwarden-App mit deiner Server-URL ein." } },
  'stirling-pdf': { fa: { tagline: "جعبه‌ابزار PDF روزمره که خودتان میزبانی می‌کنید", description: "ادغام، تقسیم، فشرده‌سازی، تبدیل، OCR، امضا، واترمارک و محو کردن متن در PDFها از طریق رابط وب تمیز، میزبانی شده محلی تا اسناد محرمانه هرگز ماشین شما را ترک نکنند.", whyItsAwesome: "جایگزین ابزارهای آنلاین مشکوک PDF: همان راحتی، اما اسناد محرمانه شما با شما می‌ماند. 50+ ابزار و در حال افزایش.", beginnerGuide: "کانتینر Docker یا نصب‌کننده ویندوز را اجرا کنید، صفحه وب محلی را باز کنید و یک فایل PDF را روی هر کارت ابزار بکشید و رها کنید." }, es: { tagline: "Caja de herramientas para PDF que puedes alojar", description: "Combina, divide, comprime, convierte, OCR, firma, marca de agua y redacta PDFs desde una interfaz web local, para que los documentos nunca salgan de tu máquina.", whyItsAwesome: "Reemplaza las herramientas online de PDF dudosas: la misma comodidad, pero tus documentos confidenciales se quedan contigo. Más de 50 herramientas y contando.", beginnerGuide: "Ejecuta el contenedor Docker o el instalador para Windows, abre la página web local y arrastra un PDF sobre cualquier tarjeta de herramienta." }, fr: { tagline: "Boîte à outils PDF quotidienne auto-hébergée", description: "Fusionnez, divisez, compressez, convertissez, OCR, signez, ajoutez un filigrane et masquez des PDF depuis une interface web propre, hébergée localement pour que les documents ne quittent jamais votre machine.", whyItsAwesome: "Remplace les outils PDF en ligne douteux : la même commodité, mais vos documents confidentiels restent avec vous. 50+ outils et plus encore.", beginnerGuide: "Exécutez le conteneur Docker ou l'installeur Windows, ouvrez la page web locale, et glissez-déposez un PDF sur n'importe quelle carte d'outil." }, de: { tagline: "Dein lokaler PDF-Toolkasten", description: "Zusammenfügen, teilen, komprimieren, konvertieren, OCR, signieren, wasserzeichen und schwärzen PDFs über eine saubere Web-Interface, lokal gehostet, also verlassen Dokumente nie deinen Rechner.", whyItsAwesome: "Ersetzt dubiose Online-PDF-Tools: gleiche Bequemlichkeit, aber deine vertraulichen Dokumente bleiben bei dir. 50+ Tools und es werden mehr.", beginnerGuide: "Starte den Docker Container oder die Windows-Installer, öffne die lokale Webseite und ziehe eine PDF-Datei auf ein beliebiges Tool-Karten." } },
  'appflowy': { fa: { tagline: "جایگزین متن-باز نوتین", description: "مستندات، ویکی‌ها، تخته‌های کانبان و تقویم با بلوک‌های سبک نوتین، قابل استفاده کاملاً آفلاین با ذخیره‌سازی محلی یا همگام‌سازی با سرور خودتان.", whyItsAwesome: "رابط کاربری در چند ثانیه آشنا می‌شود و داده‌هایتان در فایل‌های ساده‌ای که خودتان کنترل می‌کنید، باقی می‌مانند نه ابری دیگران.", beginnerGuide: "نصب کنید، یک فضای کاری بسازید و صفحات یا تخته‌ها اضافه کنید. صادرات‌های موجود از نوتین را مستقیماً وارد کنید." }, es: { tagline: "Alternativa de código abierto a Notion", description: "Documentos, wikis, tableros kanban y calendarios con bloques al estilo de Notion, funcionando completamente sin conexión y almacenados localmente o sincronizados en tu propio servidor.", whyItsAwesome: "La interfaz se siente familiar en segundos y tus datos quedan en archivos simples que controlas, en lugar de la nube de alguien más.", beginnerGuide: "Instala, crea un espacio de trabajo y añade páginas o tableros. Importa exportaciones existentes de Notion directamente." }, fr: { tagline: "Alternative open-source à Notion", description: "Docs, wikis, tableaux Kanban et calendriers avec des blocs à la Notion, utilisables hors ligne en local ou synchronisés sur votre propre serveur.", whyItsAwesome: "L'interface est familière en quelques secondes, et vos données restent dans des fichiers que vous contrôlez, pas dans un cloud tiers.", beginnerGuide: "Installez, créez un espace de travail et ajoutez des pages ou des tableaux. Importez directement vos exports Notion existants." }, de: { tagline: "Open-Source-Alternative zu Notion", description: "Dokumente, Wikis, Kanban-Boards und Kalender mit Notion-Blöcken. Funktioniert offline oder auf deinem eigenen Server.", whyItsAwesome: "Die Oberfläche ist sofort vertraut, und deine Daten bleiben in einfachen Dateien, die du kontrollierst.", beginnerGuide: "Installieren, einen Workspace erstellen und Seiten oder Boards hinzufügen. Notion-Exporte direkt importieren." } },
  'upscayl': { fa: { tagline: "افزایش دهنده کیفیت تصویر با هوش مصنوعی، آفلاین", description: "عکس‌ها و اسکن‌های با رزولوشن پایین را با مدل‌های هوش مصنوعی که کاملاً روی GPU خودتان اجرا می‌شوند، بزرگ‌تر و واضح‌تر کنید. آپلود بدون نیاز، اشتراک بدون نیاز، محدودیت بدون نیاز.", whyItsAwesome: "یک اپ رایگان جایگزین سرویس‌های پولی افزایش کیفیت می‌شود: پردازش دسته‌ای، مدل‌های مختلف برای عکس، هنر و چهره، و کارکرد آفلاین.", beginnerGuide: "نصب کنید، یک عکس را در آن بیندازید، یک مدل انتخاب کنید و روی Upscayl کلیک کنید. مدل پیش‌فرض برای بیشتر عکس‌ها مناسب است." }, es: { tagline: "Mejorador de imágenes con IA, sin conexión", description: "Amplía y mejora fotos y escaneos de baja resolución con modelos de IA que funcionan completamente en tu propia GPU. Sin subir archivos, sin suscripción, sin límites.", whyItsAwesome: "Una aplicación gratuita reemplaza a los mejoradores de pago: procesamiento por lotes, varios modelos para fotos, arte y rostros, y funciona sin conexión.", beginnerGuide: "Instala, arrastra una imagen, elige un modelo, haz clic en Upscayl. El modelo por defecto es el adecuado para la mayoría de las fotos." }, fr: { tagline: "Amélioration d'images IA, hors ligne", description: "Agrandissez et affinez les photos et scans de basse résolution avec des modèles IA qui fonctionnent entièrement sur votre propre GPU. Pas d'envoi, pas d'abonnement, pas de limites.", whyItsAwesome: "Une seule application gratuite remplace les payantes : traitement par lots, plusieurs modèles pour photos, art et visages, et fonctionne hors ligne.", beginnerGuide: "Installez, déposez une image, choisissez un modèle, cliquez sur Upscayl. Le modèle par défaut est parfait pour la plupart des photos." }, de: { tagline: "KI-Bildskalierer, offline", description: "Vergrößere und schärfere niedrigauflösende Fotos und Scans mit KI-Modellen auf deiner GPU. Kein Upload, kein Abo, keine Limits.", whyItsAwesome: "Eine kostenlose App ersetzt teure Skalierer: Batch-Verarbeitung, verschiedene Modelle für Fotos, Kunst und Gesichter, funktioniert offline.", beginnerGuide: "Installieren, ein Bild hineinziehen, ein Modell auswählen und auf Upscayl klicken. Das Standardmodell ist für die meisten Fotos richtig." } },
  'nocodb': { fa: { tagline: "جایگزین متن-از ایرتایبل", description: "هر دیتابیس را به یک صفحه‌گسترده هوشمند با نماها، فرم‌ها، کانبان و دسترسی API تبدیل می‌کند. خود میزبانی کنید یا بلافاصله در ابری آنها.", whyItsAwesome: "ابزارهای داخلی و اپ‌های کسب‌وکار کوچک را روی MySQL، Postgres یا ذخیره‌سازی خودش بدون نوشتن کد می‌سازد.", beginnerGuide: "یک فضای کاری رایگان ابری راه‌اندازی کنید یا تصویر Docker را اجرا کنید، یک پایگاه داده بسازید، فیلدها را اضافه کنید و یک فرم را برای جمع‌آوری داده به اشتراک بگذارید." }, es: { tagline: "Alternativa de código abierto a Airtable", description: "Convierte cualquier base de datos en una hoja de cálculo inteligente con vistas, formularios, tableros kanban y acceso a API. Autohospedado o en su nube al instante.", whyItsAwesome: "Construye herramientas internas y aplicaciones para pequeñas empresas sobre MySQL, Postgres o su propio almacenamiento, sin escribir código.", beginnerGuide: "Inicia un espacio de trabajo en la nube gratuito o ejecuta la imagen de Docker, crea una base, añade campos y comparte un formulario para recopilar datos." }, fr: { tagline: "Alternative open-source à Airtable", description: "Transforme n'importe quelle base de données en une feuille de calcul intelligente avec des vues, des formulaires, un tableau Kanban et un accès API. Auto-hébergé ou sur leur cloud.", whyItsAwesome: "Créez des outils internes et des applications petites entreprises sur MySQL, Postgres ou son propre stockage, sans écrire de code.", beginnerGuide: "Créez un espace de travail cloud gratuit ou lancez l'image Docker, créez une base, ajoutez des champs et partagez un formulaire pour collecter des données." }, de: { tagline: "Open-Source-Alternative zu Airtable", description: "Macht aus jeder Datenbank eine intelligente Tabelle mit Ansichten, Formularen, Kanban und API-Zugriff. Selbst gehostet oder in der Cloud.", whyItsAwesome: "Erstellt interne Tools und kleine Business-Apps auf MySQL, Postgres oder der eigenen Speicherung, ohne Code zu schreiben.", beginnerGuide: "Einen kostenlosen Cloud-Workspace starten oder das Docker-Image ausführen, eine Basis erstellen, Felder hinzufügen und ein Formular zum Sammeln von Daten teilen." } },
  'cal-com': { fa: { tagline: "زمان‌بندی متن‌باز برای همه", description: "یک لینک به اشتراک بگذارید و به دیگران اجازه دهید زمانی در تقویم شما رزرو کنند. انواع رویداد، فاصله‌های زمانی، زمان‌بندی تیمی و لینک‌های تماس ویدیویی، روی سرور آنها یا سرور خودتان.", whyItsAwesome: "کارگردانی Calendly با هسته‌ی متن‌باز که خود میزبانی می‌شود، بنابراین صفحات رزرو هرگز مخاطبان شما را به شخص ثالث نشت نمی‌دهند.", beginnerGuide: "در cal.com ثبت‌نام کنید، تقویم گوگل یا آوت‌لوک خود را متصل کنید، یک نوع رویداد بسازید و لینک رزرو خود را به اشتراک بگذارید." }, es: { tagline: "Programación abierta para todos", description: "Comparte un enlace y deja que la gente reserve tiempo en tu calendario. Tipos de eventos, tiempos de preparación, programación de equipo y enlaces de videollamadas, en su nube o tu servidor.", whyItsAwesome: "El mismo flujo de trabajo que Calendly, con un núcleo abierto que puedes autohospedar, así que las páginas de reserva nunca filtran tus contactos a terceros.", beginnerGuide: "Regístrate en cal.com, conecta tu calendario de Google u Outlook, crea un tipo de evento y comparte tu enlace de reserva." }, fr: { tagline: "Planification open-source pour tous", description: "Partagez un lien, laissez les gens réserver un créneau dans votre agenda. Types d'événements, temps tampon, planification d'équipe et liens d'appel vidéo, sur leur cloud ou votre serveur.", whyItsAwesome: "Le workflow de Calendly avec un cœur open que vous pouvez auto-héberger, ainsi vos pages de réservation ne divulguent jamais vos contacts à un tiers.", beginnerGuide: "Inscrivez-vous sur cal.com, connectez votre agenda Google ou Outlook, créez un type d'événement et partagez votre lien de réservation." }, de: { tagline: "Open-Source-Terminplanung für alle", description: "Einen Link teilen und Termine im Kalender buchen lassen. Event-Typen, Puffer, Team-Terminplanung und Videocall-Links, in der Cloud oder auf deinem Server.", whyItsAwesome: "Der Workflow von Calendly mit offenem Kern, den du selbst hosten kannst. Buchungsseiten geben niemals Kontakte an Dritte weiter.", beginnerGuide: "Bei cal.com anmelden, Google- oder Outlook-Kalender verbinden, einen Event-Typ erstellen und den Buchungslink teilen." } },
  'listmonk': { fa: { tagline: "مدیریت خبرنامه و لیست ایمیل", description: "کمپین‌ها را ارسال کنید و لیست‌های ایمیل را با تحلیل‌ها، قالب‌ها و صفحات اشتراک عمومی مدیریت کنید. یک باینری تک‌پکیج با پست‌گرس.", whyItsAwesome: "جایگزین سرویس‌های گران‌قیمت خبرنامه است: با همان ویژگی‌ها، میلیون‌ها مشترک و لیست شما مال خودتان می‌ماند.", beginnerGuide: "با Docker Compose اجرایش کنید، مشترکان را از CSV وارد کنید، محتوای خود را در ویرایشگر قالب Paste کنید و یک کمپین آزمایشی ارسال کنید." }, es: { tagline: "Gestor de boletines y listas de correo", description: "Envía campañas y gestiona listas de correo con analíticas, plantillas y páginas de suscripción públicas. Un único binario autocontenido con Postgres.", whyItsAwesome: "Reemplaza servicios de boletines costosos: mismas funciones, millones de suscriptores y tu lista te pertenece.", beginnerGuide: "Ejecútalo con Docker Compose, importa suscriptores desde un CSV, pega tu contenido en el editor de plantillas y envía una campaña de prueba." }, fr: { tagline: "Gestionnaire de newsletters et de listes d'envoi", description: "Envoyez des campagnes et gérez des listes d'envoi avec des analyses, des modèles et des pages d'abonnement publiques. Un seul binaire autonome avec Postgres.", whyItsAwesome: "Remplace les services de newsletters coûteux : mêmes fonctionnalités, millions d'abonnés, et votre liste vous appartient.", beginnerGuide: "Lancez-le avec Docker Compose, importez des abonnés au format CSV, collez votre contenu dans l'éditeur de modèles et envoyez une campagne de test." }, de: { tagline: "Newsletter- und Mailinglisten-Manager", description: "Kampagnen versenden und Mailinglisten mit Analysen, Vorlagen und öffentlichen Anmeldeseiten verwalten. Ein einzelnes, selbstständiges Binary mit Postgres.", whyItsAwesome: "Ersetzt teure Newsletter-Dienste: gleiche Features, Millionen von Abonnenten und deine Liste bleibt deine.", beginnerGuide: "Mit Docker Compose ausführen, Abonnenten als CSV importieren, Inhalt in den Vorlageneditor einfügen und eine Testkampagne versenden." } },
  'formbricks': { fa: { tagline: "نظرسنجی‌ها و فرم‌های تجربه متن‌باز", description: "نظرسنجی بسازید، مبتنی بر لینک یا جاسازی شده در اپ خودتان، با پرش‌های منطقی، تحلیل پاسخ‌ها و ردیابی محافظه‌کارانه از نظر حریم خصوصی که خودتان کنترل می‌کنید.", whyItsAwesome: "جایگزین Typeform/Qualtrics که خود میزبانی می‌شود و از اول برای GDPR طراحی شده، با محدودیت‌های رایگان سخاوتمندانه در ابری آنها هم.", beginnerGuide: "یک حساب رایگان بسازید یا تصویر Docker را اجرا کنید، یک قالب نظرسنجی انتخاب کنید و لینک را به اشتراک بگذارید. برای جاسازی کردن نیاز به یک تگ اسکریپت است." }, es: { tagline: "Encuestas y formularios de experiencia, de código abierto", description: "Crea encuestas, por enlace o incrustadas en tu app, con saltos lógicos, analíticas de respuestas y un seguimiento respetuoso de la privacidad que controlas.", whyItsAwesome: "Una alternativa a Typeform/Qualtrics que puedes autohospedar, con enfoque GDPR y límites generosos en su versión de nube gratuita.", beginnerGuide: "Crea una cuenta gratuita o ejecuta la imagen de Docker, elige una plantilla de encuesta y comparte el enlace. Para incrustar se necesita una etiqueta de script." }, fr: { tagline: "Sondages et formulaires d'expérience open-source", description: "Créez des sondages, par lien ou intégrés dans votre app, avec sauts logiques, analyses de réponses et un suivi respectueux de la vie privée que vous contrôlez.", whyItsAwesome: "Une alternative à Typeform/Qualtrics que vous pouvez auto-héberger, conçue dans l'optique du premier GDPR, avec des limites gratuites généreuses sur leur cloud.", beginnerGuide: "Créez un compte gratuit ou lancez l'image Docker, choisissez un modèle de sondage et partagez le lien. L'intégration nécessite une seule balise de script." }, de: { tagline: "Open-Source-Umfragen und Erfahrungsbögen", description: "Erstelle Umfragen, verlinkt oder in deiner App eingebettet, mit Logik-Sprüngen, Antwortanalysen und datenschutzfreundlichem Tracking, das du kontrollierst.", whyItsAwesome: "Eine Typeform/Qualtrics-Alternative, die du selbst hosten kannst. Von Anfang an GDPR-konform und mit großzügigen kostenlosen Limits in der Cloud.", beginnerGuide: "Ein kostenloses Konto erstellen oder das Docker-Image ausführen, eine Umfrage-Vorlage auswählen und den Link teilen. Einbetten erfordert ein einziges Script-Tag." } },
  'whisper-desktop': { fa: { tagline: "تبدیل گفتار به متن آفلاین با کارت گرافیک شما", description: "یک برنامه فشرده ویندوز که با استفاده از مدل‌های ویسپر اوپن‌ای‌آی، فایل‌های صوتی و تصویری را به صورت محلی به متن تبدیل می‌کند و با کارت گرافیک شما شتاب‌دهی می‌شود.", whyItsAwesome: "تبدیل متن نامحدود بدون آپلود و بدون اشتراک، در ۹۰+ زبان، مبتنی بر پیاده‌سازی معروف متن‌باز.", beginnerGuide: "فایل exe و مدل را دانلود کنید، فایل صوتی خود را انتخاب کنید، زبان را مشخص کنید و روی تبدیل کلیک کنید. خروجی زیرنویس هم در دسترس است." }, es: { tagline: "Reconocimiento de voz sin conexión en tu GPU", description: "Un programa compacto para Windows que transcribe archivos de audio y vídeo a texto localmente usando los modelos de Whisper de OpenAI, acelerado por tu tarjeta gráfica.", whyItsAwesome: "Transcripción ilimitada sin subidas ni suscripciones, en más de 90 idiomas, con una implementación de código abierto conocida.", beginnerGuide: "Descarga el ejecutable y un archivo de modelo, selecciona tu audio, elige el idioma y pulsa transcribir. Incluye exportación de subtítulos." }, fr: { tagline: "Reconnaissance vocale hors ligne sur votre GPU", description: "Un programme compact pour Windows qui transcrit des fichiers audio et vidéo en texte localement, en utilisant les modèles Whisper d'OpenAI et accéléré par votre carte graphique.", whyItsAwesome: "Transcription illimitée sans envoi ni abonnement, dans plus de 90 langues, alimentée par une implémentation open source réputée.", beginnerGuide: "Téléchargez l'exécutable et un modèle, sélectionnez votre fichier audio, choisissez la langue, et cliquez sur transcrire. L'exportation de sous-titres est inclus." }, de: { tagline: "Offline-Spracherkennung mit deiner GPU", description: "Ein kleines Windows-Programm, das Audio- und Videodateien mit OpenAIs Whisper-Modellen lokal auf Text umwandelt, beschleunigt durch deine Grafikkarte.", whyItsAwesome: "Unbegrenzte Transkription ohne Uploads oder Abo in 90+ Sprachen, betrieben durch eine bekannte Open-Source-Implementierung.", beginnerGuide: "Lade die exe-Datei und ein Modell herunter, wähle deine Audiodatei, Sprache und starte die Transkription. Export von Untertiteln ist enthalten." } },

  'tuta': { fa: { tagline: "ایمیل رمزنگاری‌شده ساخت آلمان", description: "سرویسی ایمیلی که هر پیام، مخاطب و رویداد تقویم به‌صورت پیش‌فرض سرتاسری رمزنگاری می‌شود. حتی خط موضوع و جزئیات مخاطب هم رمزنگاری می‌شوند که تقریباً هیچ سرویس دیگری انجام نمی‌دهد. شرکت در آلمان مستقر است و سرورهایش را خودش همان‌جا مدیریت می‌کند.", whyItsAwesome: "قوی‌ترین محافظت از فراداده در میان صندوق‌های ایمیل رایج: رمزنگاری از اولین ورود فعال است، نه یک افزودنی که باید پیکربندی کنید. کلاینت‌های متن‌باز، ممیزی‌های امنیتی مستقل، نشانگر احضاریه، ثبت‌نام ناشناس بدون شماره تلفن و رمزنگاری پساکوانتومی که همین حالا فعال شده.", beginnerGuide: "در tuta.com یک حساب رایگان بسازید (بدون نیاز به شماره تلفن یا نام واقعی)، سپس برنامه دسکتاپ یا موبایل را نصب و وارد شوید. ارسال به نشانی دیگر توتا خودکار رمزنگاری می‌شود؛ برای مخاطبان بیرونی می‌توانید رمزی بگذارید که گیرنده برای بازکردن پیام وارد می‌کند." }, es: { tagline: "Correo cifrado hecho en Alemania", description: "Un servicio de correo donde cada mensaje, contacto y evento de calendario se cifra de extremo a extremo por defecto. También se cifran los asuntos y los datos de contacto, algo que casi ningún otro proveedor hace. La empresa tiene su sede en Alemania y gestiona allí sus propios servidores.", whyItsAwesome: "La protección de metadatos más fuerte entre los buzones convencionales: el cifrado está activo desde el primer inicio de sesión, no es un complemento que haya que configurar. Clientes de código abierto, auditorías de seguridad independientes, warrant canary, registro anónimo sin número de teléfono y criptografía postcuántica ya desplegada.", beginnerGuide: "Crea una cuenta gratuita en tuta.com (sin número de teléfono ni nombre real), instala la app de escritorio o móvil e inicia sesión. Enviar a otra dirección de Tuta se cifra automáticamente; para contactos externos puedes fijar una contraseña que el destinatario introduce para abrir el mensaje." }, fr: { tagline: "E-mail chiffré, made in Germany", description: "Un service de messagerie où chaque message, contact et évènement d’agenda est chiffré de bout en bout par défaut. Les objets et les détails des contacts sont aussi chiffrés, ce que presque aucun autre fournisseur ne fait. La société est basée en Allemagne et y exploite ses propres serveurs.", whyItsAwesome: "La protection des métadonnées la plus solide des boîtes grand public : le chiffrement est actif dès la première connexion, ce n’est pas une option à configurer. Clients open source, audits de sécurité indépendants, warrant canary, inscription anonyme sans numéro de téléphone et cryptographie post-quantique déjà déployée.", beginnerGuide: "Créez un compte gratuit sur tuta.com (sans numéro de téléphone ni nom réel), puis installez l’appli de bureau ou mobile et connectez-vous. L’envoi vers une autre adresse Tuta est chiffré automatiquement ; pour les contacts extérieurs, vous pouvez fixer un mot de passe que le destinataire saisit pour ouvrir le message." }, de: { tagline: "Verschlüsselte E-Mail, made in Germany", description: "Ein E-Mail-Dienst, bei dem jede Nachricht, jeder Kontakt und jeder Kalendereintrag standardmäßig Ende-zu-Ende verschlüsselt ist. Auch Betreffzeilen und Kontaktdaten werden verschlüsselt, was fast kein anderer Anbieter tut. Die Firma sitzt in Deutschland und betreibt dort ihre eigenen Server.", whyItsAwesome: "Der stärkste Metadatenschutz unter den gängigen Postfächern: Verschlüsselung ab der ersten Anmeldung, kein Zubehör zum Konfigurieren. Open-Source-Clients, unabhängige Sicherheitsaudits, Warrant Canary, anonyme Anmeldung ohne Telefonnummer und bereits eingeführte post-quanten-sichere Kryptografie.", beginnerGuide: "Konto kostenlos auf tuta.com anlegen (ohne Telefonnummer oder echten Namen), dann die Desktop- oder Mobile-App installieren und anmelden. Senden an eine andere Tuta-Adresse wird automatisch verschlüsselt; für externe Kontakte können Sie ein Passwort setzen, das der Empfänger zum Öffnen eingibt." } },
  'proton-mail': { fa: { tagline: "ایمیل رمزنگاری‌شده زیر قوانین سوئیس", description: "سرویسی ایمیلی از سوئیس ساخته‌شده بر رمزنگاری دسترسی‌ناپذیر: پیام‌ها روی سرورها به شکلی ذخیره می‌شوند که خود ارائه‌دهنده هم نمی‌تواند بخواند. رمزنگاری میان نشانی‌های پروتون پیش‌فرض است و برنامه‌ها متن‌باز هستند.", whyItsAwesome: "راحت‌ترین صندوق پستی خصوصی: قانون حریم خصوصی سوئیس از حساب محافظت می‌کند، کد از ممیزی‌های مستقل گذشته (از جمله Securitum)، برای ثبت‌نام شماره تلفن نمی‌خواهد و همان حساب تقویم، درایو و VPN را هم پوشش می‌دهد. گزارش شفافیت هم به‌طور منظم منتشر می‌شود.", beginnerGuide: "در proton.me ثبت‌نام کنید با هر گزینه بازیابی که خواستید (ایمیل بازیابی اختیاری است و ناشناس می‌ماند)، سپس برنامه دسکتاپ یا موبایل را نصب کنید. اختیاری: افزودنی Proton Bridge حساب را با IMAP معمولی به Thunderbird یا Outlook وصل می‌کند." }, es: { tagline: "Correo cifrado bajo ley suiza", description: "Un servicio de correo de Suiza construido sobre el cifrado de acceso cero: los mensajes reposan en los servidores en una forma que el propio proveedor no puede leer. El cifrado entre direcciones de Proton funciona por defecto y las apps son de código abierto.", whyItsAwesome: "El buzón privado más cómodo de usar: la ley suiza de privacidad protege la cuenta, el código ha pasado auditorías independientes (Securitum entre otras), no hace falta número de teléfono para registrarse y la misma cuenta cubre Calendar, Drive y VPN. Publica un informe de transparencia con regularidad.", beginnerGuide: "Regístrate en proton.me con la opción de recuperación que prefieras (un correo de recuperación es opcional, lo que lo mantiene anónimo) e instala la app de escritorio o móvil. Opcional: el complemento Proton Bridge conecta la cuenta a Thunderbird u Outlook por IMAP normal." }, fr: { tagline: "E-mail chiffré sous droit suisse", description: "Un service de messagerie suisse construit autour du chiffrement à accès zéro : les messages reposent sur les serveurs sous une forme que le fournisseur lui-même ne peut pas lire. Le chiffrement entre adresses Proton est par défaut et les applis sont open source.", whyItsAwesome: "La boîte privée la plus simple au quotidien : le droit suisse protège le compte, le code a passé des audits indépendants (Securitum notamment), aucun numéro de téléphone n’est requis à l’inscription et le même compte couvre Calendar, Drive et VPN. Un rapport de transparence est publié régulièrement.", beginnerGuide: "Inscrivez-vous sur proton.me avec l’option de récupération de votre choix (un e-mail de récupération est facultatif, ce qui préserve l’anonymat), puis installez l’appli de bureau ou mobile. En option : le module Proton Bridge relie le compte à Thunderbird ou Outlook en IMAP standard." }, de: { tagline: "Verschlüsselte E-Mail nach Schweizer Recht", description: "Ein Schweizer E-Mail-Dienst rund um Zero-Access-Verschlüsselung: Nachrichten liegen auf den Servern in einer Form, die der Anbieter selbst nicht lesen kann. Verschlüsselung zwischen Proton-Adressen ist Standard und die Apps sind quelloffen.", whyItsAwesome: "Das bequemste private Postfach im Alltag: Schweizer Datenschutzrecht schützt das Konto, der Code hat unabhängige Audits bestanden (u. a. Securitum), keine Telefonnummer nötig, und dasselbe Konto deckt Calendar, Drive und VPN ab. Ein Transparenzbericht erscheint regelmäßig.", beginnerGuide: "Auf proton.me mit beliebiger Wiederherstellungsoption registrieren (eine Wiederherstellungs-E-Mail ist optional und hält es anonym), dann Desktop- oder Mobile-App installieren. Optional: Das Proton-Bridge-Add-on verbindet das Konto per normalem IMAP mit Thunderbird oder Outlook." } },
  'ente-photos': { fa: { tagline: "پشتیبان‌گیری رمزنگاری‌شده عکس، قابل بازبینی", description: "برنامه ذخیره عکس که هر تصویر و ویدیو را پیش از بارگذاری روی خود دستگاه رمزنگاری می‌کند، پس شرکتی که سرورها را اداره می‌کند حتی اگر بخواهد هم نمی‌تواند آن‌ها را ببیند. هم برنامه‌ها و هم کد سرور متن‌باز هستند و تیم گزارش شفافیت منتشر می‌کند.", whyItsAwesome: "راحتی Google Photos بدون اسکن‌کردن: رمزنگاری سرتاسری پیش‌فرض، اشتراک‌گذاری خانوادگی، سطح رایگان که بیشتر کتابخانه‌های گوشی را پوشش می‌دهد و کل این مجموعه از ممیزی Cure53 گذشته است. اگر شرکت ناپدید شود، برنامه دسکتاپ همچنان می‌تواند بایگانی شما را محلی رمزگشایی کند؛ تقریباً هیچ رقیبی چنین چیزی ارائه نمی‌دهد.", beginnerGuide: "برنامه یا کلاینت دسکتاپ را نصب کنید، فقط با یک ایمیل ثبت‌نام کنید و اجازه دهید پوشه دوربین را بارگذاری کند. کلیدهای بازیابی یک‌بار هنگام ثبت‌نام نشان داده می‌شوند: آن‌ها را جایی امن نگه دارید، چون بدون آن‌ها هیچ‌کس، حتی Ente، نمی‌تواند پشتیبان را باز کند." }, es: { tagline: "Copia de fotos cifrada y auditable", description: "Una app de almacenamiento de fotos que cifra cada imagen y vídeo en tu dispositivo antes de subirlos, así que la empresa que gestiona los servidores no podría verlos aunque quisiera. Las apps y el código del servidor son de código abierto y el equipo publica informes de transparencia.", whyItsAwesome: "La comodidad de Google Photos sin el escaneo: cifrado de extremo a extremo por defecto, uso compartido familiar, un nivel gratuito que cubre la mayoría de las fototecas y todo el conjunto superó una auditoría de Cure53. Si la empresa desapareciera, la app de escritorio podría seguir descifrando tu archivo localmente, algo que casi ningún competidor ofrece.", beginnerGuide: "Instala la app o el cliente de escritorio, regístrate solo con un correo y deja que suba tu carpeta de cámara. Las claves de recuperación se muestran una vez al registrarte: guárdalas en un lugar seguro, porque sin ellas nadie, ni siquiera Ente, puede abrir la copia." }, fr: { tagline: "Sauvegarde de photos chiffrée et auditable", description: "Une appli de stockage photo qui chiffre chaque image et vidéo sur votre appareil avant l’envoi : la société qui gère les serveurs ne pourrait pas les regarder même si elle le voulait. Les applis et le code du serveur sont open source, et l’équipe publie des rapports de transparence.", whyItsAwesome: "Le confort de Google Photos sans le scan : chiffrement de bout en bout par défaut, partage familial, un forfait gratuit qui couvre la plupart des bibliothèques de téléphone, et l’ensemble a passé un audit Cure53. Si la société disparaissait, l’appli de bureau pourrait toujours déchiffrer vos archives en local, ce qu’aucun concurrent ne propose quasiment.", beginnerGuide: "Installez l’appli ou le client de bureau, inscrivez-vous avec un simple e-mail et laissez-le envoyer votre dossier d’appareil photo. Les clés de récupération s’affichent une fois à l’inscription : gardez-les en lieu sûr, car sans elles personne, pas même Ente, ne peut déverrouiller la sauvegarde." }, de: { tagline: "Verschlüsseltes Foto-Backup, auditierbar", description: "Eine Foto-App, die jedes Bild und Video auf dem Gerät verschlüsselt, bevor es hochgeladen wird: Die Firma hinter den Servern könnte selbst dann nicht hineinschauen, wenn sie wollte. Apps und Servercode sind quelloffen, und das Team veröffentlicht Transparenzberichte.", whyItsAwesome: "Google-Photos-Komfort ohne das Scannen: Ende-zu-Ende-Verschlüsselung standardmäßig, Familienfreigabe, ein kostenloser Tarif, der die meisten Handybibliotheken abdeckt, und der ganze Stack bestand ein Cure53-Audit. Verschwindet die Firma, kann die Desktop-App das Archiv weiterhin lokal entschlüsseln — das bietet fast kein Wettbewerber.", beginnerGuide: "App oder Desktop-Client installieren, nur mit einer E-Mail registrieren und den Kamera-Ordner hochladen lassen. Die Wiederherstellungsschlüssel werden bei der Registrierung einmalig angezeigt: bewahren Sie sie sicher auf, denn ohne sie kann niemand — nicht einmal Ente — das Backup öffnen." } },
  'ente-auth': { fa: { tagline: "کدهای ورود دومرحله‌ای با همگام‌سازی رمزنگاری‌شده", description: "احرازکننده متن‌باز که توکن‌های ورود دومرحله‌ای شما را سرتاسری رمزنگاری و میان گوشی و دسکتاپ همگام می‌کند؛ پس گم‌شدن گوشی دیگر شما را از همه حساب‌ها بیرون نمی‌گذارد. از Google Authenticator و Authy و ده‌ها برنامه دیگر به‌طور مستقیم درون‌ریزی می‌کند.", whyItsAwesome: "Authy کاربران را از برنامه دسکتاپ محروم کرد و Google Authenticator هرگز پشتیبانِ تحت کنترل شما نداشت. Ente Auth راه‌حل است: تولید کد آفلاین، همگام‌سازی رمزنگاری‌شده چنددستگاهی، جستجو و پوشه برای فهرست‌های بزرگ توکن، با پشتوانه ممیزی Cure53. با هر سایتی که برنامه TOTP استاندارد می‌پذیرد کار می‌کند.", beginnerGuide: "آن را نصب کنید و سپس QR‌کد «تنظیم احرازکننده» هر سایت را مثل همیشه اسکن کنید. برای مهاجرت، درون‌ریزی داخلی می‌تواند فایل خروجی یا صفحه برنامه احرازکننده قدیمی شما را در چند ضربه بخواند." }, es: { tagline: "Códigos 2FA con sincronización cifrada", description: "Un autenticador de código abierto que guarda tus tokens de verificación en dos pasos cifrados de extremo a extremo y los sincroniza entre móvil y escritorio, así que perder el teléfono ya no te deja fuera de todas tus cuentas. Importa directamente desde Google Authenticator, Authy y decenas de apps más.", whyItsAwesome: "Authy bloqueó a sus usuarios en la app de escritorio y Google Authenticator nunca ofreció copias que controlaras tú. Ente Auth es la solución: generación de códigos sin conexión, sincronización cifrada entre dispositivos, búsqueda y carpetas para listas largas de tokens, y una auditoría de Cure53 detrás. Funciona con cualquier sitio que acepte una app TOTP estándar.", beginnerGuide: "Instálalo y usa el código QR de «configurar autenticador» de cada sitio como siempre. Para migrar, la importación integrada lee el archivo de exportación o la pantalla de tu autenticador antiguo en unos toques." }, fr: { tagline: "Codes 2FA avec synchronisation chiffrée", description: "Un authentificateur open source qui stocke vos jetons de double authentification chiffrés de bout en bout et les synchronise entre téléphone et ordinateur : perdre son téléphone ne vous verrouille plus hors de tous vos comptes. Importe directement depuis Google Authenticator, Authy et des dizaines d’autres applis.", whyItsAwesome: "Authy a enfermé ses utilisateurs hors de l’appli de bureau et Google Authenticator n’a jamais offert de sauvegardes sous votre contrôle. Ente Auth est la réponse : génération de codes hors ligne, synchronisation chiffrée entre appareils, recherche et dossiers pour les longues listes de jetons, avec un audit Cure53. Fonctionne avec tout site qui accepte une appli TOTP standard.", beginnerGuide: "Installez-le, puis scannez comme d’habitude le QR code « configurer un authentificateur » de chaque site. Pour migrer, l’import intégré lit le fichier d’export ou l’écran de votre ancienne appli en quelques gestes." }, de: { tagline: "2FA-Codes mit verschlüsselter Synchronisierung", description: "Ein Open-Source-Authenticator, der Ihre 2FA-Token Ende-zu-Ende verschlüsselt speichert und zwischen Handy und Desktop synchronisiert: Ein verlorenes Telefon sperrt Sie nicht mehr aus allen Konten aus. Importiert direkt von Google Authenticator, Authy und Dutzenden anderen Apps.", whyItsAwesome: "Authy sperrte Nutzer aus der Desktop-App aus, und Google Authenticator bot nie Backups unter Ihrer Kontrolle. Ente Auth ist die Lösung: Offline-Code-Erzeugung, verschlüsselte Geräte-Sync, Suche und Ordner für große Tokenlisten, dazu ein Cure53-Audit. Funktioniert mit jeder Seite, die eine Standard-TOTP-App akzeptiert.", beginnerGuide: "Installieren und dann wie üblich den „Authenticator einrichten“-QR-Code jeder Seite scannen. Zum Umzug liest der eingebaute Import die Exportdatei oder den Bildschirm Ihrer alten Authenticator-App in wenigen Schritten." } },
  'aegis': { fa: { tagline: "گاوصندوق ورود دومرحله‌ای که هرگز به شبکه دست نمی‌زند", description: "برنامه اندرویدی رایگان، امن و متن‌باز برای مدیریت توکن‌های ورود دومرحله‌ای. کدها در گاوصندوقی رمزنگاری‌شده می‌مانند که با گذرواژه یا اثر انگشت باز می‌شود و پشتیبان‌ها به‌صورت فایل‌های رمزنگاری‌شده‌ای خروجی می‌گیرند که فقط شما می‌توانید بازشان کنید.", whyItsAwesome: "این برنامه بدون مجوز اینترنت عرضه می‌شود؛ یعنی عملاً نمی‌تواند توکن‌های شما را به جایی بفرستد. پشتیبان‌گیری خودکار رمزنگاری‌شده، بازکردن با زیست‌سنج، آیکون برای سرویس‌ها و درون‌ریزی از همه احرازکننده‌های رایج. برای کسانی که عامل دوم را کاملاً آفلاین می‌خواهند، انتخاب مرجع است.", beginnerGuide: "از F-Droid نصب کنید، یک گذرواژه گاوصندوق بگذارید که فراموشش نکنید و با اسکن QR هر سایت توکن اضافه کنید. در تنظیمات پشتیبان‌گیری رمزنگاری‌شده را روشن کنید تا خرابی گوشی ورودهایتان را همراهش نبرد." }, es: { tagline: "Una caja fuerte 2FA que nunca toca la red", description: "Una app de Android gratuita, segura y de código abierto para gestionar tus tokens de verificación en dos pasos. Los códigos viven en una caja fuerte cifrada que abres con contraseña o huella, y las copias se exportan como archivos cifrados que solo tú puedes abrir.", whyItsAwesome: "La app se distribuye sin permiso de internet, o sea que físicamente no puede enviar tus tokens a ningún sitio. Copias automáticas cifradas, desbloqueo biométrico, iconos para servicios e importación desde todos los autenticadores conocidos. Para quien quiera los segundos factores totalmente fuera de línea, es la opción de referencia.", beginnerGuide: "Instálala desde F-Droid, fija una contraseña de bóveda que no vayas a olvidar y añade tokens escaneando el QR de cada sitio. Activa las copias cifradas en los ajustes para que un teléfono roto no se lleve tus accesos." }, fr: { tagline: "Un coffre 2FA qui ne touche jamais au réseau", description: "Une appli Android gratuite, sûre et open source pour gérer vos jetons de vérification en deux étapes. Les codes vivent dans un coffre chiffré que vous ouvrez avec un mot de passe ou une empreinte, et les sauvegardes s’exportent en fichiers chiffrés que vous seul pouvez ouvrir.", whyItsAwesome: "L’appli s’installe sans permission internet : physiquement, elle ne peut envoyer vos jetons nulle part. Sauvegardes automatiques chiffrées, déverrouillage biométrique, icônes par service et import depuis tous les authentificateurs connus. Pour qui veut un second facteur totalement hors ligne, c’est le choix de référence.", beginnerGuide: "Installez-la depuis F-Droid, fixez un mot de passe de coffre que vous n’oublierez pas et ajoutez les jetons en scannant le QR de chaque site. Activez les sauvegardes chiffrées dans les réglages pour qu’un téléphone cassé n’emporte pas vos connexions." }, de: { tagline: "Ein 2FA-Tresor, der das Netz nie anfasst", description: "Eine kostenlose, sichere Open-Source-Android-App zur Verwaltung Ihrer Zwei-Faktor-Token. Die Codes liegen in einem verschlüsselten Tresor hinter Passwort oder Fingerabdruck, und Backups exportieren als verschlüsselte Dateien, die nur Sie öffnen können.", whyItsAwesome: "Die App kommt ohne Internetberechtigung aus: Sie kann Ihre Token physisch nirgendwohin senden. Automatische verschlüsselte Backups, biometrisches Entsperren, Symbole für Dienste und Import von jedem gängigen Authenticator. Wer Zweitfaktoren komplett offline halten will, greift hier zu.", beginnerGuide: "Aus F-Droid installieren, ein Tresor-Passwort setzen, das Sie nicht vergessen, und Token per QR-Code jeder Seite hinzufügen. In den Einstellungen verschlüsselte Backups einschalten, damit ein kaputtes Telefon Ihre Logins nicht mitnimmt." } },
  'fossify-gallery': { fa: { tagline: "گالری گوشی بدون تبلیغ و بدون ردیاب", description: "گالری عکس و ویدیوی متن‌باز اندروید، ساخته انشعاب اجتماعی Simple Mobile Tools پس از فروش نسخه اصلی به یک شرکت تبلیغاتی. آلبوم‌ها را سازماندهی می‌کند، ویرایش، پنهان‌سازی و قفل‌کردن دارد و کاملاً آفلاین کار می‌کند.", whyItsAwesome: "وقتی Simple Mobile Tools خریده شد، مالکان جدید تبلیغ و ردیابی را به برنامه‌هایی افزودند که میلیون‌ها نفر به آن‌ها اعتماد داشتند. فاسیفای پاسخ جامعه است: همان گالری تمیز، بدون SDK تبلیغاتی، بدون آنالیتیکس، با پشتیبانی کامل از شخصی‌سازی و بازیابی، و برای همیشه تحت GPL-3.0.", beginnerGuide: "از F-Droid نصب کنید و هنگام پرسش، آن را گالری پیش‌فرض کنید. برای انتخاب آیتم‌ها لمس طولانی بزنید، برای تغییر چیدمان دو انگشت را باز و بسته کنید و برای برش و فیلتر از ویرایشگر داخلی استفاده کنید. پین فراموش‌شده فقط روی دستگاه شما می‌ماند." }, es: { tagline: "Una galería sin anuncios ni rastreadores", description: "Una galería de fotos y vídeos de código abierto para Android, creada por la bifurcación comunitaria de Simple Mobile Tools después de que los originales se vendieran a una empresa de publicidad. Organiza álbumes, edita, oculta y bloquea elementos, y funciona totalmente sin conexión.", whyItsAwesome: "Cuando compraron Simple Mobile Tools, los nuevos dueños añadieron anuncios y rastreo a apps en las que confiaban millones. Fossify es la respuesta comunitaria: la misma galería limpia, sin SDKs publicitarios, sin analíticas, con soporte completo de personalización y restauración, bajo GPL-3.0 para siempre.", beginnerGuide: "Instálala desde F-Droid y ponla como galería predeterminada cuando lo pregunte. Mantén pulsado para seleccionar, pellizca para cambiar la disposición y usa el editor integrado para recortes y filtros. Los PIN olvidados se quedan solo en tu dispositivo." }, fr: { tagline: "Une galerie sans pub ni traqueurs", description: "Une galerie photo et vidéo open source pour Android, créée par le fork communautaire de Simple Mobile Tools après la vente des originaux à une société de publicité. Organise les albums, édite, masque et verrouille des éléments, et fonctionne entièrement hors ligne.", whyItsAwesome: "Quand Simple Mobile Tools a été racheté, les nouveaux propriétaires ont ajouté pub et traçage à des applis que des millions de personnes utilisaient. Fossify est la réponse de la communauté : la même galerie propre, sans SDK publicitaire, sans analytique, avec un support complet de personnalisation et de restauration, sous GPL-3.0 pour toujours.", beginnerGuide: "Installez-la depuis F-Droid et définissez-la comme galerie par défaut quand on vous le demande. Appui long pour sélectionner, pincer pour changer la disposition, et l’éditeur intégré pour recadrages et filtres. Les PIN oubliés restent sur votre appareil." }, de: { tagline: "Eine Handy-Galerie ohne Werbung und Tracker", description: "Eine Open-Source-Foto- und Video-Galerie für Android, gebaut von der Community-Gabelung von Simple Mobile Tools, nachdem die Originale an eine Werbefirma verkauft wurden. Ordnet Alben, bearbeitet, versteckt und sperrt Elemente und läuft komplett offline.", whyItsAwesome: "Als Simple Mobile Tools verkauft wurde, fügten die neuen Eigentümer Werbung und Tracking in Apps ein, denen Millionen vertrauten. Fossify ist die Community-Antwort: dieselbe saubere Galerie, keine Werbe-SDKs, keine Analytik, volle Anpassungs- und Wiederherstellungsunterstützung, für immer unter GPL-3.0.", beginnerGuide: "Aus F-Droid installieren und bei Nachfrage als Standard-Galerie einstellen. Lange drücken zum Auswählen, auf- und zuziehen fürs Layout, und der eingebaute Editor übernimmt Zuschnitt und Filter. Vergessene PINs bleiben auf Ihrem Gerät." } },

  'librewolf': { fa: { tagline: "فایرفاکس تنظیم‌شده علیه ردیابی", description: "انشعابی از فایرفاکس ساخته جامعه داوطلبان که تلمتری، Pocket و محتوای تبلیغاتی را پیش از اولین بازکردن حذف می‌کند و uBlock Origin را با پیش‌فرض‌های منطقی ارائه می‌دهد. هر تنظیمی ابتدا بر پایه مقاومت در برابر ردیابی انتخاب شده و به‌روزرسانی‌ها چند روزی با فایرفاکس همراه‌اند.", whyItsAwesome: "از همان ابتدا کوکی‌ها را هنگام بستن پاک می‌کند، داده انگشت‌نگاری را جعل می‌کند و هیچ چیزی به Mozilla نمی‌فرستد. شما کل دنیای افزونه‌های فایرفاکس را دارید، بدون اینکه Mozilla به‌جای شما تصمیم بگیرد.", beginnerGuide: "نصبش کنید، وارد هیچ حسابی نشوید و مرور کنید. اگر سایتی خراب شد، آیکون سپر را بزنید و حفاظت را فقط برای همان سایت کم کنید." }, es: { tagline: "Firefox ajustado contra el rastreo", description: "Una bifurcación de Firefox creada por una comunidad de voluntarios que elimina telemetría, Pocket y contenido patrocinado antes de que lo abras por primera vez, y trae uBlock Origin con valores por defecto sensatos. Cada ajuste se elige primero por resistencia al rastreo y las actualizaciones siguen a Firefox en días.", whyItsAwesome: "De serie borra las cookies al cerrar, falsea los datos de fingerprinting y no envía nada a Mozilla. Conservas todo el mundo de extensiones de Firefox sin que Mozilla decida por ti.", beginnerGuide: "Instálalo, no inicies sesión en nada y navega. Si un sitio falla, pulsa el icono del escudo y baja la protección solo para ese sitio." }, fr: { tagline: "Firefox accordé contre le pistage", description: "Un dérivé de Firefox créé par une communauté de bénévoles qui retire la télémétrie, Pocket et le contenu sponsorisé avant même la première ouverture, et livre uBlock Origin avec des réglages sains. Chaque option privilégie d’abord la résistance au pistage, et les mises à jour suivent Firefox en quelques jours.", whyItsAwesome: "D’origine, il efface les cookies à la fermeture, usurpe les données d’empreinte et n’envoie rien à Mozilla. Vous gardez tout l’écosystème d’extensions Firefox sans que Mozilla décide à votre place.", beginnerGuide: "Installez-le, ne connectez aucun compte et naviguez. Si un site casse, cliquez l’icône bouclier et baissez la protection pour ce seul site." }, de: { tagline: "Gegen Tracking optimiertes Firefox", description: "Ein Firefox-Fork einer Freiwilligen-Community, der Telemetrie, Pocket und gesponserte Inhalte schon vor dem ersten Öffnen entfernt und uBlock Origin mit sinnvollen Vorgaben mitbringt. Jede Einstellung priorisiert Tracking-Widerstand, Updates folgen Firefox binnen Tagen.", whyItsAwesome: "Ab Werk löscht es Cookies beim Schließen, täuscht Fingerprinting-Daten und sendet nichts an Mozilla. Sie behalten die ganze Firefox-Addon-Welt, ohne dass Mozilla für Sie entscheidet.", beginnerGuide: "Installieren, nirgends anmelden und losbrowsen. Bricht eine Seite, klicken Sie auf das Schild-Symbol und senken Sie den Schutz nur für diese eine Seite." } },
  'mullvad-vpn': { fa: { tagline: "VPN بدون حساب کاربری", description: "مالواد حساب‌های شماره‌دار بدون ایمیل، نام و گذرواژه صادر می‌کند، پول نقد با پست و رمزارز می‌پذیرد و زیرساخت خود را به ممیزی‌های عمومی توسط Cure53 و دیگران سپرده است. برنامه‌ها متن‌باز هستند و شبکه روی سرورهایی می‌چرخد که خود شرکت مستقیماً کنترلشان می‌کند.", whyItsAwesome: "هر چیزی که VPN‌ها را ترسناک می‌کند حذف شده: بدون ردیابی معرفی، بدون ایمیل بازاریابی، بدون ردپای حساب. فقط WireGuard، با کلید قطع اضطراری که ترافیک را پیش از برقراری تونل مسدود می‌کند.", beginnerGuide: "برنامه را نصب کنید، یک شماره حساب بسازید، یک ماه پرداخت کنید و وصل شوید. یک اشتراک پنج دستگاه را پوشش می‌دهد." }, es: { tagline: "La VPN sin cuentas", description: "Mullvad emite cuentas numeradas sin correo, sin nombre y sin contraseña, acepta efectivo por correo y criptomonedas, y ha abierto su infraestructura a auditorías públicas de Cure53 y otros. Las apps son de código abierto y la red corre sobre servidores que la propia empresa controla.", whyItsAwesome: "Todo lo que hace inquietantes a las VPN ha desaparecido: sin rastreo de referidos, sin correos de marketing, sin rastro de cuenta. Solo WireGuard, con un interruptor de muerte que bloquea el tráfico antes de que el túnel esté arriba.", beginnerGuide: "Instala la app, genera un número de cuenta, paga un mes y conéctate. Una suscripción cubre cinco dispositivos." }, fr: { tagline: "Le VPN sans comptes", description: "Mullvad émet des comptes numérotés sans e-mail, sans nom et sans mot de passe, accepte le liquide par courrier et les cryptos, et a ouvert son infrastructure à des audits publics par Cure53 et d’autres. Les applis sont open source et le réseau tourne sur des serveurs que la société contrôle elle-même.", whyItsAwesome: "Tout ce qui rend les VPN inquiétants a disparu : pas de suivi de parrainage, pas d’e-mails marketing, pas de trace de compte. WireGuard uniquement, avec un kill switch qui bloque le trafic avant que le tunnel ne monte.", beginnerGuide: "Installez l’appli, générez un numéro de compte, payez un mois et connectez-vous. Un abonnement couvre cinq appareils." }, de: { tagline: "Das VPN ohne Konten", description: "Mullvad stellt nummerierte Konten ohne E-Mail, ohne Namen und ohne Passwort aus, nimmt Bargeld per Post und Krypto an, und hat seine Infrastruktur öffentlichen Audits von Cure53 und anderen geöffnet. Die Apps sind quelloffen, das Netz läuft auf Servern, die die Firma selbst kontrolliert.", whyItsAwesome: "Alles, was VPNs unheimlich macht, ist weg: kein Empfehlungs-Tracking, keine Marketing-Mails, keine Konto-Spuren. Nur WireGuard, mit Kill-Switch, der den Verkehr blockt, bevor der Tunnel steht.", beginnerGuide: "App installieren, Kontonummer erzeugen, einen Monat bezahlen und verbinden. Ein Abo deckt fünf Geräte ab." } },
  'proton-vpn': { fa: { tagline: "VPN سوئیسی از خانواده پروتون", description: "پروتون VPN تحت قوانین سوئیس با سیاست بدون ثبت گزارش که ممیزی‌های مستقل بررسی کرده‌اند، برنامه‌های متن‌باز و مسیریابی Secure Core از سرورهای سخت‌گیری در ایسلند، سوئد و سوئیس کار می‌کند. سطح رایگانش واقعاً قابل استفاده است؛ بدون سقف داده و بدون تبلیغ.", whyItsAwesome: "یکی از معدود VPN‌هایی است که کل شرکت ممیزی می‌شود، نه فقط سرورها. کلید قطع اضطراری، تونل‌سازی دوگانه و Tor-over-VPN همگی در برنامه‌های استاندارد هستند.", beginnerGuide: "یک حساب رایگان پروتون بسازید، برنامه را نصب کنید و سریع‌ترین کشور را برگزینید. طرح‌های پولی Secure Core و لوکیشن‌های بیشتری می‌افزایند." }, es: { tagline: "VPN suiza de la familia Proton", description: "Proton VPN opera bajo jurisdicción suiza con una política de no registros revisada por auditores independientes, apps de código abierto y enrutado Secure Core por servidores reforzados en Islandia, Suecia y Suiza. El nivel gratuito es realmente utilizable, sin límites de datos ni anuncios.", whyItsAwesome: "Es una de las pocas VPN donde se audita toda la empresa, no solo los servidores. Kill switch, túnel dividido y Tor sobre VPN están en las apps estándar.", beginnerGuide: "Crea una cuenta gratuita de Proton, instala la app y elige el país más rápido. Los planes de pago añaden Secure Core y más ubicaciones." }, fr: { tagline: "VPN suisse de la famille Proton", description: "Proton VPN opère sous juridiction suisse avec une politique sans journaux examinée par des auditeurs indépendants, des applis open source et un routage Secure Core par des serveurs durcis en Islande, en Suède et en Suisse. Le forfait gratuit est réellement utilisable, sans limite de données ni publicité.", whyItsAwesome: "C’est l’un des rares VPN où toute la société est auditée, pas seulement les serveurs. Kill switch, split tunneling et Tor sur VPN sont dans les applis standard.", beginnerGuide: "Créez un compte Proton gratuit, installez l’appli et choisissez le pays le plus rapide. Les offres payantes ajoutent Secure Core et davantage de pays." }, de: { tagline: "Schweizer VPN aus der Proton-Familie", description: "Proton VPN läuft unter Schweizer Jurisdiktion mit einer No-Logs-Richtlinie, die unabhängige Prüfer begutachtet haben, quelloffenen Apps und Secure-Core-Routing über gehärtete Server in Island, Schweden und der Schweiz. Der Gratis-Tarif ist wirklich nutzbar, ohne Datenlimits und ohne Werbung.", whyItsAwesome: "Eines der wenigen VPNs, bei denen das ganze Unternehmen auditiert wird, nicht nur die Server. Kill-Switch, Split-Tunneling und Tor-über-VPN sind in den Standard-Apps enthalten.", beginnerGuide: "Kostenloses Proton-Konto erstellen, App installieren und das schnellste Land wählen. Bezahlte Tarife ergänzen Secure Core und mehr Standorte." } },
  'element': { fa: { tagline: "گفتگو روی شبکه Matrix", description: "المنت برنامه پرچم‌دار Matrix است، پروتکل فدراسیون باز که هر کسی می‌تواند سرور خودش را راه بیندازد و همچنان با بقیه صحبت کند. پیام‌های خصوصی و اتاق‌های خصوصی سرتاسری رمزنگاری می‌شوند و تاریخچه شما می‌تواند فقط روی دستگاه‌های خودتان بماند.", whyItsAwesome: "هیچ شرکتی مالک شبکه نیست: حساب‌ها نام‌کاربری روی سرورهایی هستند که خودتان برمی‌گزینید، پل‌ها به IRC و تلگرام و بیشتر وصل می‌شوند و رمزنگاری‌اش از بازبینی‌های رسمی NCC Group و دیگران سر بلند کرده است.", beginnerGuide: "روی matrix.org یا هر سرور مورد اعتمادتان حساب بسازید و گفتگو را شروع کنید. تنظیم رمزنگاری از شما کلید بازیابی می‌خواهد؛ حتماً نگهش دارید." }, es: { tagline: "Chat en la red Matrix", description: "Element es la app insignia de Matrix, un protocolo federado abierto donde cualquiera puede montar un servidor y aun así hablar con todos los demás. Los mensajes y salas privadas se cifran de extremo a extremo y tu historial puede vivir solo en tus propios dispositivos.", whyItsAwesome: "Ninguna empresa es dueña de la red: las cuentas son nombres de usuario en servidores que tú eliges, los puentes conectan IRC, Telegram y más, y su criptografía ha sobrevivido a revisiones formales de NCC Group y otros.", beginnerGuide: "Crea una cuenta en matrix.org o en cualquier servidor de confianza y empieza a chatear. La configuración de cifrado te pide guardar una clave de recuperación; hazlo." }, fr: { tagline: "Discuter sur le réseau Matrix", description: "Element est l’appli phare de Matrix, un protocole fédéré ouvert où chacun peut héberger un serveur tout en parlant à tous les autres. Les messages et salons privés sont chiffrés de bout en bout, et votre historique peut ne vivre que sur vos propres appareils.", whyItsAwesome: "Aucune société ne possède le réseau : les comptes sont des noms d’utilisateur sur des serveurs que vous choisissez, les passerelles relient IRC, Telegram et plus, et le chiffrement a survécu aux revues formelles de NCC Group et d’autres.", beginnerGuide: "Créez un compte sur matrix.org ou sur tout serveur de confiance, puis lancez une discussion. La configuration du chiffrement demande de garder une clé de récupération ; faites-le." }, de: { tagline: "Chat im Matrix-Netzwerk", description: "Element ist die Vorzeige-App für Matrix, ein offenes Föderationsprotokoll, bei dem jeder einen Server betreiben kann und trotzdem mit allen anderen schreiben kann. Direktnachrichten und private Räume sind Ende-zu-Ende-verschlüsselt, und Ihr Verlauf kann nur auf Ihren eigenen Geräten liegen.", whyItsAwesome: "Keine Firma besitzt das Netz: Konten sind Benutzernamen auf Servern, die Sie wählen, Brücken verbinden IRC, Telegram und mehr, und die Kryptografie hat formale Prüfungen von NCC Group und anderen überstanden.", beginnerGuide: "Konto auf matrix.org oder einem vertrauenswürdigen Server erstellen und loschatten. Die Verschlüsselungseinrichtung bittet um einen Wiederherstellungsschlüssel; bewahren Sie ihn auf." } },
  'simplex': { fa: { tagline: "پیام‌رسانی بدون هیچ شناسه کاربری", description: "سیمپلکس آخرین شناسه را هم حذف می‌کند: نه شماره تلفن، نه ایمیل، نه کلید عمومی قابل مشاهده برای شبکه. پیام‌ها از سرورهایی عبور می‌کنند که هرگز نمی‌فهمند چه کسی با چه کسی حرف می‌زند و طراحی آن به‌طور رسمی توسط Trail of Bits و Equilibrium بازبینی شده است.", whyItsAwesome: "حتی Signal پروفایل شما را به شماره تلفن گره می‌زند. سیمپلکس شما را به هیچی گره نمی‌زند، پس فهرست کاربران مرکزی‌ای وجود ندارد که احضار یا سرقت شود. گروه‌ها، تماس‌ها و انتقال فایل همه روی آن کار می‌کنند.", beginnerGuide: "نصبش کنید، یک پروفایل بسازید و لینک یک‌بارمصرف یا QR خود را با دوستتان به اشتراک بگذارید. هر دو می‌توانید ترافیک را از Tor یا پروکسی SOCKS رد کنید برای بالاترین سطح." }, es: { tagline: "Mensajería sin ningún ID de usuario", description: "SimpleX elimina el último identificador: sin número de teléfono, sin correo, sin clave pública visible para la red. Los mensajes pasan por servidores que nunca saben quién habla con quién, y su diseño ha sido revisado formalmente por Trail of Bits y Equilibrium.", whyItsAwesome: "Hasta Signal ata tu perfil a un número de teléfono. SimpleX no te ata a nada, así que no hay una lista central de usuarios que confiscar o rascar. Grupos, llamadas y transferencia de archivos funcionan sobre él.", beginnerGuide: "Instálalo, crea un perfil y comparte tu enlace de un solo uso o código QR con un amigo. Ambos podéis enrutar por Tor o proxies SOCKS para el trato completo." }, fr: { tagline: "Messagerie sans aucun identifiant d’utilisateur", description: "SimpleX supprime le dernier identifiant : pas de numéro de téléphone, pas d’e-mail, pas de clé publique visible du réseau. Les messages relaient par des serveurs qui ne sauront jamais qui parle à qui, et la conception a été revue formellement par Trail of Bits et Equilibrium.", whyItsAwesome: "Même Signal lie votre profil à un numéro de téléphone. SimpleX ne vous lie à rien, donc il n’existe aucune liste centrale d’utilisateurs à réquisitionner ou à moissonner. Groupes, appels et transfert de fichiers fonctionnent dessus.", beginnerGuide: "Installez-le, créez un profil et partagez votre lien à usage unique ou QR avec un ami. Tous les deux pouvez router via Tor ou des proxies SOCKS pour le traitement complet." }, de: { tagline: "Messaging ohne jegliche Nutzerkennung", description: "SimpleX entfernt den letzten Bezeichner: keine Telefonnummer, keine E-Mail, kein für das Netz sichtbarer öffentlicher Schlüssel. Nachrichten laufen über Server, die nie erfahren, wer mit wem spricht, und der Entwurf wurde formal von Trail of Bits und Equilibrium geprüft.", whyItsAwesome: "Selbst Signal bindet Ihr Profil an eine Telefonnummer. SimpleX bindet Sie an nichts, also gibt es keine zentrale Nutzerliste, die man vorladen oder absaugen könnte. Gruppen, Anrufe und Dateiübertragung funktionieren darüber.", beginnerGuide: "Installieren, Profil anlegen und Ihren Einmal-Link oder QR-Code mit einem Freund teilen. Beide können über Tor oder SOCKS-Proxys routen für die volle Ausführung." } },
  'mastodon': { fa: { tagline: "شبکه‌های اجتماعی که کنترلش با شماست", description: "ماستودون شبکه اجتماعی غیرمتمرکز روی پروتکل ActivityPub است: سروری را برمی‌گزینید که قوانینش را بپسندید، افراد را در همه سرورهای دیگر دنبال می‌کنید و هر وقت بخواهید با دنبال‌کننده‌هایتان می‌روید. بدون تبلیغ و بدون فید الگوریتمی که مجبور به بحث با آن شوید.", whyItsAwesome: "برنامه رسمی اندروید نرم‌افزار آزاد است و شبکه را هزاران اپراتور مستقل اداره می‌کنند به‌جای یک شرکت تبلیغاتی. خط زمانی زمانی، هشدار محتوا و مدیریتی که به جامعه‌اش پاسخ می‌دهد.", beginnerGuide: "به یک سرور عمومی مثل mastodon.online بپیوندید، چند حساب را دنبال کنید و joinmastodon.org را ببینید تا بقیه فضا را بشناسید. جابه‌جایی سرور بعداً پشتیبانی می‌شود." }, es: { tagline: "Redes sociales que controlas tú", description: "Mastodon es redes sociales descentralizadas sobre el protocolo ActivityPub: eliges un servidor cuyas reglas te gustan, sigues gente de todos los demás servidores y te vas con tus seguidores cuando quieras. Sin anuncios ni algoritmo con el que discutir.", whyItsAwesome: "La app oficial de Android es software libre y la red la gestionan miles de operadores independientes en lugar de una empresa de publicidad. Líneas temporales cronológicas, avisos de contenido y moderación que responde a su comunidad.", beginnerGuide: "Únete a un servidor general como mastodon.online, sigue unas cuentas y mira joinmastodon.org para ver qué más hay. Cambiar de servidor luego es posible." }, fr: { tagline: "Des fils sociaux que vous contrôlez", description: "Mastodon, c’est le social décentralisé sur le protocole ActivityPub : choisissez un serveur dont les règles vous plaisent, suivez des gens sur tous les autres serveurs, et partez avec vos abonnés quand vous voulez. Pas de pub, pas de fil algorithmique à combattre.", whyItsAwesome: "L’appli Android officielle est un logiciel libre et le réseau est tenu par des milliers d’opérateurs indépendants plutôt que par une société publicitaire. Fils chronologiques, avertissements de contenu et une modération qui répond à sa communauté.", beginnerGuide: "Rejoignez un serveur généraliste comme mastodon.online, suivez quelques comptes et parcourez joinmastodon.org pour voir le reste. Changer de serveur plus tard est possible." }, de: { tagline: "Soziale Feeds unter Ihrer Kontrolle", description: "Mastodon ist dezentrales Social Networking auf dem ActivityPub-Protokoll: Wählen Sie einen Server, dessen Regeln Ihnen passen, folgen Sie Menschen auf allen anderen Servern und gehen Sie mit Ihren Followern jederzeit. Keine Werbung, kein algorithmischer Feed.", whyItsAwesome: "Die offizielle Android-App ist freie Software, und das Netz wird von Tausenden unabhängigen Betreibern geführt statt von einer Werbefirma. Chronologische Timelines, Inhaltswarnungen und Moderation, die ihrer Community antwortet.", beginnerGuide: "Treten Sie einem allgemeinen Server wie mastodon.online bei, folgen Sie ein paar Konten und stöbern Sie auf joinmastodon.org. Ein späterer Serverwechsel wird unterstützt." } },

  'jellyfin': { fa: { tagline: "فیلم‌های شما، سرور شما", description: "جلی‌فین کتابخانه رسانه‌ای خودتان را سازماندهی و به هر صفحه‌ای در خانه پخش می‌کند: وب، گوشی، تلویزیون و پخش‌کننده‌ها. حساب ابری نیست، تلمتری نیست و قفل پولی نیست، چون سرور کاملاً در خانه اجرا می‌شود.", whyItsAwesome: "همان تجربه Plex بدون حساب Plex: ترنسکد سخت‌افزاری، همگام‌سازی وضعیت تماشا، تلویزیون زنده و DVR، همه نرم‌افزار آزاد و نگه‌داری‌شده توسط هزاران مشارکت‌کننده.", beginnerGuide: "سرور را نصب کنید، به پوشه فیلم‌ها اشاره دهید و بگذارید کاورها را بگیرد. اول برنامه وب را در مرورگر باز کنید، بعد برای تلویزیون یا گوشی برنامه نصب کنید." }, es: { tagline: "Tus películas, tu servidor", description: "Jellyfin organiza tu propia biblioteca multimedia y la emite a cada pantalla de la casa: web, móviles, televisiones y reproductores. No hay cuenta en la nube, ni telemetría, ni desbloqueos de pago, porque el servidor corre entero en casa.", whyItsAwesome: "Es la experiencia de Plex sin la cuenta de Plex: transcodificación por hardware, sincronización de lo visto, TV en directo y DVR, todo software libre mantenido por miles de colaboradores.", beginnerGuide: "Instala el servidor, apúntalo a tu carpeta de películas y deja que busque las carátulas. Abre primero la app web en el navegador y luego añade apps para tu TV o móvil." }, fr: { tagline: "Vos films, votre serveur", description: "Jellyfin organise votre bibliothèque multimédia et la diffuse sur tous les écrans de la maison : web, téléphones, TV et lecteurs. Pas de compte cloud, pas de télémétrie, pas de déblocages payants, car le serveur tourne entièrement chez vous.", whyItsAwesome: "L’expérience Plex sans le compte Plex : transcodage matériel, synchro de visionnage, TV en direct et DVR, tout en logiciel libre entretenu par des milliers de contributeurs.", beginnerGuide: "Installez le serveur, pointez-le vers votre dossier de films et laissez-le récupérer les jaquettes. Ouvrez d’abord l’appli web dans un navigateur, puis ajoutez des applis pour la TV ou le téléphone." }, de: { tagline: "Deine Filme, dein Server", description: "Jellyfin ordnet deine eigene Mediensammlung und streamt sie auf jeden Bildschirm im Haus: Web, Handys, TVs und Player. Kein Cloud-Konto, keine Telemetrie, keine Bezahlfreischaltungen, denn der Server läuft komplett zu Hause.", whyItsAwesome: "Das Plex-Erlebnis ohne das Plex-Konto: Hardware-Transcoding, Wiedergabestatus-Sync, Live-TV und DVR, alles freie Software von Tausenden Mitwirkenden gepflegt.", beginnerGuide: "Server installieren, auf den Filme-Ordner zeigen und Cover abrufen lassen. Zuerst die Web-App im Browser öffnen, dann Apps für TV oder Handy hinzufügen." } },
  'libretranslate': { fa: { tagline: "ترجمه ماشینی که خودتان میزبانی می‌کنید", description: "لایبرترنسلیت مدل‌های ترجمه باز را روی دستگاه یا سرور خودتان اجرا می‌کند، با نیروی Argos Translate. یک API میزبانی‌شده هم هست، اما هیچ چیز مانع نمی‌شود متن را کاملاً آفلاین ترجمه کنید بدون اینکه شخص ثالثی بخواند.", whyItsAwesome: "Google Translate و DeepL هر جمله‌ای را که می‌نویسید می‌بینند. لایبرترنسلیت ده‌ها جفت زبان، یک API ساده REST و ایمیج‌های Docker ارائه می‌دهد که میزبانی شخصی را دو خطی می‌کنند.", beginnerGuide: "اول صفحه عمومی را امتحان کنید، بعد pip install libretranslate را اجرا کنید و localhost:5000 را باز کنید؛ همان رابط بدون محدودیت و بدون لاگ." }, es: { tagline: "Traducción automática que puedes alojar", description: "LibreTranslate ejecuta modelos de traducción abiertos en tu propia máquina o servidor, con Argos Translate debajo. Existe una API alojada, pero nada te impide traducir texto sin conexión con cero terceros leyendo.", whyItsAwesome: "Google Translate y DeepL ven cada frase que escribes. LibreTranslate trae decenas de pares de idiomas, una API REST sencilla e imágenes Docker que hacen del autoalojamiento un trabajo de dos líneas.", beginnerGuide: "Prueba primero la página pública, luego ejecuta pip install libretranslate y abre localhost:5000 para la misma interfaz sin límites y sin registros." }, fr: { tagline: "Traduction automatique hébergeable", description: "LibreTranslate exécute des modèles de traduction ouverts sur votre machine ou votre serveur, propulsé par Argos Translate. Une API hébergée existe, mais rien ne vous empêche de traduire hors ligne avec zéro tiers à la lecture.", whyItsAwesome: "Google Translate et DeepL voient chaque phrase que vous tapez. LibreTranslate livre des dizaines de paires de langues, une API REST simple et des images Docker qui font de l’auto-hébergement un travail de deux lignes.", beginnerGuide: "Essayez d’abord la page publique, puis lancez pip install libretranslate et ouvrez localhost:5000 pour la même interface sans limites et sans journaux." }, de: { tagline: "Maschinelle Übersetzung, die du hosten kannst", description: "LibreTranslate betreibt offene Übersetzungsmodelle auf deinem eigenen Rechner oder Server, angetrieben von Argos Translate. Eine gehostete API existiert, aber nichts hindert dich, Text offline zu übersetzen, ohne dass Dritte mitlesen.", whyItsAwesome: "Google Translate und DeepL sehen jeden Satz, den du tippst. LibreTranslate bringt Dutzende Sprachpaare, eine einfache REST-API und Docker-Images mit, die Selbsthosten zum Zwei-Zeiler machen.", beginnerGuide: "Zuerst die öffentliche Seite testen, dann pip install libretranslate ausführen und localhost:5000 öffnen — dieselbe Oberfläche ohne Limits und ohne Logs." } },
  'cryptomator': { fa: { tagline: "فایل‌ها را پیش از دیدن هر ابری قفل کنید", description: "کریپتوماتور گاوصندوق‌هایی می‌سازد که نام و محتوای فایل‌ها را پیش از رسیدن به Dropbox، Google Drive، OneDrive یا هر پوشه همگام دیگری رمزنگاری می‌کند. قالب گاوصندوق متن‌باز است و توسط Cure53 و SEC Consult ممیزی شده.", whyItsAwesome: "ارائه‌دهندگان ابری به‌جای اسناد شما نام‌های به‌هم‌ریخته و بلوک‌های هم‌اندازه می‌بینند. حساب نمی‌خواهد، روی هر دسکتاپ و گوشی کار می‌کند و با همان گذرواژه در همه باز می‌شود.", beginnerGuide: "داخل پوشه همگام ابری فعلی‌تان یک گاوصندوق بسازید، یک گذرواژه قوی بگذارید و فایل‌ها را داخلش جابه‌جا کنید. بقیه کارها مثل یک پوشه معمولی است." }, es: { tagline: "Bloquea archivos antes de que la nube los vea", description: "Cryptomator crea bóvedas que cifran nombres y contenidos antes de que aterricen en Dropbox, Google Drive, OneDrive o cualquier carpeta de sincronización. El formato de la bóveda es de código abierto y lo han auditado Cure53 y SEC Consult.", whyItsAwesome: "Los proveedores de nube ven nombres revueltos y bloques del mismo tamaño en lugar de tus documentos. No necesita cuenta, funciona en cada escritorio y teléfono, y se desbloquea con la misma frase de acceso en todos.", beginnerGuide: "Crea una bóveda dentro de tu carpeta de sincronización existente, fija una frase de acceso fuerte y mueve archivos dentro. Todo lo demás se comporta como una carpeta normal." }, fr: { tagline: "Verrouillez les fichiers avant que le cloud ne les voie", description: "Cryptomator crée des coffres qui chiffrent noms et contenus avant qu’ils n’atterrissent dans Dropbox, Google Drive, OneDrive ou tout dossier de synchronisation. Le format de coffre est open source et audité par Cure53 et SEC Consult.", whyItsAwesome: "Les fournisseurs de cloud voient des noms brouillés et des blocs de taille égale au lieu de vos documents. Pas de compte nécessaire, ça marche sur tous les ordinateurs et téléphones, et ça se déverrouille avec la même phrase de passe partout.", beginnerGuide: "Créez un coffre dans votre dossier de synchronisation existant, fixez une phrase de passe solide et déplacez les fichiers dedans. Tout le reste se comporte comme un dossier normal." }, de: { tagline: "Dateien sperren, bevor eine Cloud sie sieht", description: "Cryptomator erzeugt Tresore, die Dateinamen und Inhalte verschlüsseln, bevor sie in Dropbox, Google Drive, OneDrive oder einen anderen Sync-Ordner landen. Das Tresorformat ist quelloffen und von Cure53 und SEC Consult auditiert.", whyItsAwesome: "Cloud-Anbieter sehen wirre Namen und gleich große Blöcke statt Ihrer Dokumente. Kein Konto nötig, läuft auf jedem Desktop und Telefon und entsperrt überall mit derselben Passphrase.", beginnerGuide: "Einen Tresor im bestehenden Cloud-Sync-Ordner anlegen, starke Passphrase setzen und Dateien hineinverschieben. Alles andere verhält sich wie ein normaler Ordner." } },
  'fossify-calendar': { fa: { tagline: "تقویم بدون ابر", description: "تقویم Material You که رویدادها را روی دستگاه یا در هر حساب CalDAV که به آن اشاره کنید ذخیره می‌کند. یادآوری، تکرار، درون‌ریزی و برون‌بری همه بدون حساب و بدون مجوز اینترنت کار می‌کنند.", whyItsAwesome: "همان تبار Simple Calendar است که جامعه پس از فروش Simple Mobile Tools به شرکت تبلیغاتی بازساخته. ویجت‌ها، رنگ‌ها و نماهای هفتگی رایگان‌اند و کد GPL با صفر ردیاب است.", beginnerGuide: "نصبش کنید، برنامه تقویم پیش‌فرض کنید و رویداد اضافه کنید. برای همگام‌سازی با سرور خودتان، CalDAV را در تنظیمات فعال کنید." }, es: { tagline: "Calendario sin nube", description: "Un calendario Material You que guarda los eventos en el dispositivo o en cualquier cuenta CalDAV que le indiques. Recordatorios, repetición, importación y exportación funcionan sin cuenta y sin permiso de internet.", whyItsAwesome: "Es la estirpe de Simple Calendar, reconstruida por la comunidad después de que vendieran Simple Mobile Tools a una empresa de publicidad. Widgets, colores y vistas de semana vienen de serie, y el código es GPL con cero rastreadores.", beginnerGuide: "Instálala, ponla como app de calendario predeterminada y añade eventos. Para sincronizar con tu propio servidor, activa CalDAV en los ajustes." }, fr: { tagline: "Un calendrier sans cloud", description: "Un calendrier Material You qui stocke les évènements sur l’appareil ou dans n’importe quel compte CalDAV. Rappels, répétition, import et export fonctionnent sans compte et sans permission internet du tout.", whyItsAwesome: "C’est la lignée de Simple Calendar, reconstruite par la communauté après la vente de Simple Mobile Tools à une société de publicité. Widgets, couleurs et vues semaine offerts, et le code est GPL avec zéro traqueur.", beginnerGuide: "Installez-la, faites-en l’appli de calendrier par défaut et ajoutez des évènements. Pour synchroniser avec votre propre serveur, activez CalDAV dans les réglages." }, de: { tagline: "Kalender ohne Cloud", description: "Ein Material-You-Kalender, der Termine auf dem Gerät oder in einem beliebigen CalDAV-Konto speichert. Erinnerungen, Wiederholung, Import und Export funktionieren ganz ohne Konto und ohne Internetberechtigung.", whyItsAwesome: "Es ist die Simple-Calendar-Linie, von der Community neu gebaut, nachdem Simple Mobile Tools an eine Werbefirma verkauft wurde. Widgets, Farben und Wochenansichten gratis, und der Code ist GPL mit null Trackern.", beginnerGuide: "Installieren, zur Standard-Kalender-App machen und Termine anlegen. Für Sync mit dem eigenen Server CalDAV in den Einstellungen aktivieren." } },
  'fossify-contacts': { fa: { tagline: "مخاطب‌هایی که روی گوشی‌تان می‌مانند", description: "مدیر مخاطبان سریعی که دفترچه نشانی استاندارد را می‌خواند و می‌نویسد بدون اینکه دسترسی اینترنت بخواهد. ادغام تکراری‌ها، علاقه‌مندی‌ها، گروه‌ها و برون‌بری vCard کاملاً آفلاین کار می‌کنند.", whyItsAwesome: "فهرست مخاطبان حساس‌ترین داده گوشی است. این یکی نمی‌تواند به خانه زنگ بزند چون کد شبکه ندارد، و جایگزین برنامه‌های سازنده‌ای می‌شود که بی‌سروصدا همه چیز را برای دیگری همگام می‌کنند.", beginnerGuide: "نصب و یک بار بازش کنید تا کنش‌های مخاطبان به آن منتقل شود. پیش از تعویض گوشی، یک پشتیبان vCard بگیرید." }, es: { tagline: "Contactos que se quedan en tu teléfono", description: "Un gestor de contactos rápido que lee y escribe la libreta estándar sin pedir acceso a internet. Fusión de duplicados, favoritos, grupos y exportación vCard funcionan totalmente sin conexión.", whyItsAwesome: "Tu lista de contactos es el dato más sensible de un teléfono. Este no puede llamar a casa porque no tiene código de red, y sustituye a las apps del fabricante que sincronizan calladamente todo con otro.", beginnerGuide: "Instálala y ábrela una vez para que sea la app predeterminada de contactos. Exporta una copia vCard antes de cambiar de teléfono." }, fr: { tagline: "Des contacts qui restent sur votre téléphone", description: "Un gestionnaire de contacts rapide qui lit et écrit le carnet d’adresses standard sans demander d’accès internet. Fusion des doublons, favoris, groupes et export vCard fonctionnent entièrement hors ligne.", whyItsAwesome: "Votre liste de contacts est la donnée la plus sensible d’un téléphone. Celle-ci ne peut pas téléphoner à la maison car elle n’a pas de code réseau, et elle remplace les applis du fabricant qui synchronisent tranquillement tout chez quelqu’un d’autre.", beginnerGuide: "Installez-la et ouvrez-la une fois pour qu’elle devienne l’appli par défaut des contacts. Exportez une sauvegarde vCard avant de changer de téléphone." }, de: { tagline: "Kontakte, die auf dem Handy bleiben", description: "Ein schneller Kontaktmanager, der das Standard-Adressbuch liest und schreibt, ohne Internetzugang zu verlangen. Duplikate zusammenführen, Favoriten, Gruppen und vCard-Export laufen komplett offline.", whyItsAwesome: "Ihre Kontaktliste sind die sensibelsten Daten eines Handys. Diese App kann nicht nach Hause telefonieren, weil sie keinen Netzwerkcode hat, und ersetzt die Hersteller-Apps, die still alles zu jemand anderem synchronisieren.", beginnerGuide: "Installieren und einmal öffnen, damit sie Standard-App für Kontaktaktionen wird. Vor dem Handywechsel ein vCard-Backup exportieren." } },
  'cake-wallet': { fa: { tagline: "مونرو و چندسکه، بدون KYC", description: "کیف‌پول رسمی متن‌باز مونرو که به بیت‌کوین، لایت‌کوین، اتریوم و بیشتر گسترش یافته. کلیدها روی دستگاه ساخته و نگهداری می‌شوند و کیف‌پول به نودهای عمومی یا نود خودتان وصل می‌شود بدون هیچ ثبت‌نامی.", whyItsAwesome: "بیشتر کیف‌پول‌ها هویت می‌خواهند یا کد بسته دارند. Cake Wallet با مجوز MIT است، اتصال Tor به نودها را پشتیبانی می‌کند تا موجودی حتی از ارائه‌دهنده اینترنتتان پنهان بماند و با همین بذر کاغذی همه‌جا بازیابی می‌شود.", beginnerGuide: "کیف‌پول بسازید، بذر ۲۵ کلمه‌ای را روی کاغذ بنویسید و اول یک مبلغ کم را تست کنید. بازیابی همه‌جا فقط با بذر کار می‌کند." }, es: { tagline: "Monero y multimoneda, sin KYC", description: "El monedero oficial de código abierto de Monero, ampliado a Bitcoin, Litecoin, Ethereum y más. Las claves se generan y guardan en el dispositivo, y el monedero se conecta a nodos públicos o propios sin ningún registro.", whyItsAwesome: "La mayoría de monederos piden identidad o traen código cerrado. Cake Wallet tiene licencia MIT, admite conexiones Tor a nodos para que el saldo quede privado incluso ante tu ISP, y se restaura en cualquier lugar solo con la semilla.", beginnerGuide: "Crea un monedero, escribe la semilla de 25 palabras en papel y envía primero una cantidad pequeña de prueba. La restauración funciona en cualquier sitio solo con la semilla." }, fr: { tagline: "Monero et multi-monnaies, sans KYC", description: "Le portefeuille Monero officiel open source, étendu à Bitcoin, Litecoin, Ethereum et plus. Les clés sont générées et stockées sur l’appareil, et le portefeuille se connecte à des nœuds publics ou aux vôtres sans aucune inscription.", whyItsAwesome: "La plupart des portefeuilles demandent une identité ou livrent du code fermé. Cake Wallet est sous licence MIT, gère les connexions Tor aux nœuds pour que le solde reste privé même devant votre FAI, et se restaure partout depuis une phrase seed papier.", beginnerGuide: "Créez un portefeuille, écrivez la seed de 25 mots sur papier et envoyez d’abord un petit montant de test. La restauration fonctionne partout avec la seule seed." }, de: { tagline: "Monero und Multi-Coin, ohne KYC", description: "Die offizielle Open-Source-Monero-Wallet, erweitert um Bitcoin, Litecoin, Ethereum und mehr. Schlüssel werden auf dem Gerät erzeugt und gespeichert, und die Wallet verbindet sich mit öffentlichen oder eigenen Nodes ohne jede Registrierung.", whyItsAwesome: "Die meisten Wallets verlangen Identität oder haben geschlossenen Code. Cake Wallet ist MIT-lizenziert, unterstützt Tor-Verbindungen zu Nodes, damit das Guthaben selbst vor dem ISP privat bleibt, und stellt überall allein aus der Seed wieder her.", beginnerGuide: "Wallet erstellen, die 25-Wort-Seed auf Papier schreiben und zuerst einen kleinen Testbetrag senden. Die Wiederherstellung klappt überall allein mit der Seed." } },
};
